function Backdrop({ scene, house, art }) {
  const h = HOUSE[house] || HOUSES[0];
  useEffect(() => { if (REDUCED()) return; let raf = 0; const mv = (e) => { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; document.documentElement.style.setProperty("--px", ((e.clientX / innerWidth) - 0.5).toFixed(3)); document.documentElement.style.setProperty("--py", ((e.clientY / innerHeight) - 0.5).toFixed(3)); }); };
    addEventListener("pointermove", mv); return () => removeEventListener("pointermove", mv); }, []);
  return html`<div className=${"backdrop scene-" + scene} aria-hidden="true" style=${{ "--house": h.colour, "--house-deep": h.deep }}>
    <div className="bd-sky" style=${{ backgroundImage: `url(${art || IMG.castle})` }}></div>
    <div className="bd-left" style=${{ backgroundImage: `url(${scene === "room" ? IMG.fireplace : IMG.candles})` }}></div>
    <div className="bd-right" style=${{ backgroundImage: `url(${IMG.windows})` }}></div>
    <div className="bd-glow"></div><${Particles} scene=${scene} /><div className="bd-vignette"></div>
  </div>`;
}

/* ===== Interaction & atmosphere ===== */
const tilt = {
  onPointerMove: (e) => { if (REDUCED() || e.pointerType === "touch") return; const el = e.currentTarget, r = el.getBoundingClientRect(); const x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
    el.style.setProperty("--ry", ((x - 0.5) * 10).toFixed(2) + "deg"); el.style.setProperty("--rx", ((0.5 - y) * 8).toFixed(2) + "deg"); el.style.setProperty("--mx", (x * 100) + "%"); el.style.setProperty("--my", (y * 100) + "%"); },
  onPointerLeave: (e) => { const el = e.currentTarget; el.style.setProperty("--ry", "0deg"); el.style.setProperty("--rx", "0deg"); }
};

function Particles({ scene }) {
  const ref = useRef(null);
  useEffect(() => {
    if (REDUCED()) return;
    const c = ref.current, x = c.getContext("2d"); let raf, w, h, dpr = Math.min(2, window.devicePixelRatio || 1), parts = [];
    const kind = scene === "room" ? "ember" : scene === "library" ? "dust" : "star";
    const N = kind === "star" ? 70 : 46;
    const resize = () => { w = c.width = innerWidth * dpr; h = c.height = innerHeight * dpr; c.style.width = innerWidth + "px"; c.style.height = innerHeight + "px"; };
    const spawn = (init) => kind === "star" ? { x: Math.random() * w, y: Math.random() * h * 0.45, r: (Math.random() * 1.2 + 0.4) * dpr, p: Math.random() * 6.28, s: 0.01 + Math.random() * 0.03 }
      : { x: Math.random() * w, y: init ? Math.random() * h : h + 10, r: (kind === "ember" ? Math.random() * 1.8 + 0.8 : Math.random() * 1.4 + 0.5) * dpr, vy: (kind === "ember" ? 0.35 + Math.random() * 0.8 : 0.08 + Math.random() * 0.2) * dpr, p: Math.random() * 6.28, life: 1 };
    resize(); for (let i = 0; i < N; i++) parts.push(spawn(true));
    const col = kind === "ember" ? "255,170,80" : kind === "dust" ? "243,220,154" : "235,240,255";
    const loop = () => {
      x.clearRect(0, 0, w, h);
      parts.forEach((q, i) => {
        q.p += kind === "star" ? q.s : 0.02;
        let a;
        if (kind === "star") a = 0.35 + 0.45 * Math.sin(q.p);
        else { q.y -= q.vy; q.x += Math.sin(q.p) * 0.4 * dpr; a = Math.max(0, Math.min(1, q.y / h)) * (kind === "ember" ? 0.9 : 0.5); if (q.y < -10) parts[i] = spawn(false); }
        const g = x.createRadialGradient(q.x, q.y, 0, q.x, q.y, q.r * 4); g.addColorStop(0, `rgba(${col},${a})`); g.addColorStop(1, `rgba(${col},0)`);
        x.fillStyle = g; x.beginPath(); x.arc(q.x, q.y, q.r * 4, 0, 6.28); x.fill();
      });
      raf = requestAnimationFrame(loop);
    };
    const vis = () => { cancelAnimationFrame(raf); if (!document.hidden) loop(); };
    loop(); addEventListener("resize", resize); document.addEventListener("visibilitychange", vis);
    return () => { cancelAnimationFrame(raf); removeEventListener("resize", resize); document.removeEventListener("visibilitychange", vis); };
  }, [scene]);
  return html`<canvas className="bd-canvas" ref=${ref} aria-hidden="true"></canvas>`;
}

function DoorTransition({ info, done }) {
  useEffect(() => { if (REDUCED()) { done(); return; } const id = setTimeout(done, 2600); return () => clearTimeout(id); }, []);
  const h = HOUSE[info.house];
  return html`<div className="doors" style=${{ "--house": h.colour }} onClick=${done} role="status" aria-live="polite">
    <div className="door left" aria-hidden="true"></div><div className="door right" aria-hidden="true"></div>
    <div className="doorlight" aria-hidden="true"></div>
    <div className="doortext"><${Crest} house=${h.id} size=${80} /><p className="eyebrow">Welcome to the ${h.name} common room</p><p className="doorname">${info.name}</p></div>
  </div>`;
}

function StarBurst() {
  const ref = useRef(null);
  useEffect(() => {
    if (REDUCED()) return;
    const c = ref.current, x = c.getContext("2d"), dpr = Math.min(2, window.devicePixelRatio || 1);
    const W = c.width = c.offsetWidth * dpr, H = c.height = c.offsetHeight * dpr;
    const ps = Array.from({ length: 60 }, () => { const a = Math.random() * 6.28, v = (2 + Math.random() * 5) * dpr; return { x: W / 2, y: H * 0.3, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 2 * dpr, r: (2 + Math.random() * 3) * dpr, life: 1 }; });
    let raf, t = 0;
    const star = (cx, cy, r) => { x.beginPath(); for (let i = 0; i < 10; i++) { const rr = i % 2 ? r * 0.45 : r, a = -Math.PI / 2 + i * Math.PI / 5; x.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr); } x.closePath(); x.fill(); };
    const loop = () => { x.clearRect(0, 0, W, H); t++;
      ps.forEach(p => { p.x += p.vx; p.y += p.vy; p.vy += 0.12 * dpr; p.vx *= 0.985; p.life -= 0.012; if (p.life > 0) { x.fillStyle = `rgba(255,${200 + Math.random() * 40 | 0},110,${p.life})`; star(p.x, p.y, p.r); } });
      if (t < 110) raf = requestAnimationFrame(loop); else x.clearRect(0, 0, W, H); };
    loop(); return () => cancelAnimationFrame(raf);
  }, []);
  return html`<canvas className="burst" ref=${ref} aria-hidden="true"></canvas>`;
}

function CountUp({ from, to, ms = 1200 }) {
  const [v, setV] = useState(REDUCED() ? to : from);
  useEffect(() => { if (REDUCED()) return; let raf; const t0 = performance.now(); const step = (t) => { const k = Math.min(1, (t - t0) / ms); setV(Math.round(from + (to - from) * (1 - Math.pow(1 - k, 3)))); if (k < 1) raf = requestAnimationFrame(step); }; raf = requestAnimationFrame(step); return () => cancelAnimationFrame(raf); }, [from, to]);
  return html`<span>${v}</span>`;
}

class ErrorBoundary extends React.Component {
  constructor(p) { super(p); this.state = { err: null }; }
  static getDerivedStateFromError(err) { return { err }; }
  render() {
    if (!this.state.err) return this.props.children;
    return html`<div className="frame panel stack-s" role="alert" style=${{ maxWidth: "640px", margin: "40px auto" }}><h1>Something went wrong</h1>
      <p>The academy hit a problem and stopped this screen. Your saved writing is still on this device.</p>
      <p className="small muted">Details: ${String(this.state.err && this.state.err.message || this.state.err)}</p>
      <div className="row gap-s"><button className="btn gold" onClick=${() => this.setState({ err: null })}>Try again</button><button className="btn secondary" onClick=${() => location.reload()}>Reload the page</button></div></div>`;
  }
}

const NAV_ICON = {
  home: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M3,11 L12,4 L21,11 V20 H15 V14 H9 V20 H3 Z" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /></svg>`,
  quests: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M5,20 L18,5 C19,4 21,6 20,7 L7,21 Z M5,20 L4,22" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /></svg>`,
  calendar: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15" rx="2" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="M3.5,10 H20.5 M8,3 V7 M16,3 V7" stroke="currentColor" strokeWidth="1.6" /></svg>`,
  classes: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M3,9 L12,4 L21,9 L12,14 Z M7,11.5 V16 C9,18 15,18 17,16 V11.5 M21,9 V14" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /></svg>`,
  practice: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M4,5 Q8,3.5 12,5.5 Q16,3.5 20,5 V19 Q16,17.5 12,19.5 Q8,17.5 4,19 Z M12,5.5 V19.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /></svg>`,
  collection: html`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M7,4 H17 V8 C17,11 15,13 12,13 C9,13 7,11 7,8 Z M7,6 H4 C4,9 5.5,10 7.5,10 M17,6 H20 C20,9 18.5,10 16.5,10 M12,13 V17 M8,20 H16 M9,17 H15 V20 H9 Z" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" /></svg>`
};
/* ===== Academy screens: profiles, character, common room, quests, calendar, collection, profile, practice ===== */
function Who({ index, choose, create }) {
  return html`<div className="stack-l narrow center-col">
    <div className="stack-s center-text"><p className="eyebrow">Local profiles on this browser</p><h1 tabIndex="-1">Who is writing today?</h1>
      <p className="lead">Choose your profile to continue your quests. These profiles are saved only on this browser and device. They are not accounts and have no passwords.</p></div>
    ${index.profiles.length ? html`<ul className="whogrid">${index.profiles.map(p => html`<li key=${p.id}><button className="whocard frame" onClick=${() => choose(p.id)}>
      <${Portrait} id=${p.portrait} size="m" house=${p.house} alt="" /><span className="cardtitle">${p.name}</span><span className="small">${HOUSE[p.house].name} · Year ${p.year}</span></button></li>`)}</ul>` : null}
    <div className="center-text"><button className="btn gold big" onClick=${create}>${index.profiles.length ? "Add a new pupil" : "Create your wizard"}</button></div>
  </div>`;
}

function YearTome({ y, on }) {
  const roman = { 4: "IV", 5: "V", 6: "VI" }[y.id];
  const cols = { 4: ["#7A1E2B", "#4A0F18"], 5: ["#1E5B3E", "#0E3322"], 6: ["#1F3F7A", "#0F2148"] }[y.id];
  return html`<svg viewBox="0 0 120 150" className="tome" aria-hidden="true">
    <defs><linearGradient id=${"tg" + y.id} x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor=${cols[1]} /><stop offset=".18" stopColor=${cols[0]} /><stop offset="1" stopColor=${cols[1]} /></linearGradient></defs>
    <rect x="18" y="10" width="88" height="128" rx="6" fill="#E8D7AE" />
    <rect x="12" y="6" width="90" height="130" rx="6" fill=${`url(#tg${y.id})`} stroke=${on ? "#F3DC9A" : "#8C6A2E"} strokeWidth=${on ? 3 : 1.5} />
    <rect x="22" y="16" width="70" height="110" rx="3" fill="none" stroke="#D9B15F" strokeWidth="1.2" opacity=".8" />
    <path d="M57,30 l6,10 h-12 z M57,112 l6,-10 h-12 z" fill="#D9B15F" opacity=".8" />
    <text x="57" y="80" textAnchor="middle" fontFamily="Cinzel, Georgia, serif" fontSize="30" fontWeight="700" fill="#F3DC9A">${roman}</text>
    <rect x="12" y="6" width="10" height="130" fill="rgba(0,0,0,.25)" />
  </svg>`;
}

const CREATE_STEPS = [["portrait", "Portrait"], ["name", "Name"], ["house", "House"], ["year", "Year"]];
function Create({ initial, save, cancel, editing }) {
  const [f, setF] = useState(initial || { portrait: "", name: "", house: "", year: null });
  const [step, setStep] = useState(0);
  const [err, setErr] = useState("");
  const h = f.house ? HOUSE[f.house] : null;
  const filled = [!!f.portrait, !!f.name.trim(), !!f.house, !!f.year];
  const msgs = ["Choose a portrait to continue.", "Type a display name to continue.", "Choose a house to continue.", "Choose your school year to continue."];
  const stageRef = useRef(null);
  const goStep = (i) => { setErr(""); setStep(i); Sfx.play("page"); requestAnimationFrame(() => { const el = stageRef.current && stageRef.current.querySelector("h2"); el && el.focus({ preventScroll: true }); }); };
  const set = (k, v) => { setF({ ...f, [k]: v }); setErr(""); if (k !== "name") Sfx.play("select"); };
  const next = () => { if (!filled[step]) { setErr(msgs[step]); return; } goStep(step + 1); };
  const enter = () => {
    const miss = filled.findIndex(x => !x);
    if (miss >= 0) { setErr(msgs[miss]); setStep(miss); return; }
    save({ ...f, name: f.name.trim().slice(0, 24) });
  };
  return html`<div className="create-grid">
    <section className="frame panel stack create-stage" aria-labelledby="cw-h" ref=${stageRef}>
      <${Ribbon} id="cw-h" as="h1">${editing ? "Edit your wizard" : "Create your wizard"}<//>
      <p className="tagline-i center-text">${editing ? "Change how you appear. Your quests, stars and rewards stay the same." : "Your story begins here"}</p>
      <ol className="runes" aria-label="Character steps">${CREATE_STEPS.map(([id, l], i) => html`<li key=${id}>
        <button className=${"rune" + (i === step ? " now" : "") + (filled[i] ? " done" : "")} aria-current=${i === step ? "step" : undefined}
          onClick=${() => (editing || i <= step || filled.slice(0, i).every(Boolean)) ? goStep(i) : setErr(msgs[filled.findIndex(x => !x)])}>
          <span className="rn" aria-hidden="true">${filled[i] ? "✓" : i + 1}</span>${l}${filled[i] ? html`<span className="sr"> (chosen)</span>` : null}</button></li>`)}</ol>

      <div className="stepbody" key=${step}>
        ${step === 0 ? html`<fieldset><legend><h2 className="h3" tabIndex="-1">Choose your portrait</h2></legend>
          <div className="portraitgrid">${PORTRAITS.map(p => html`<label key=${p.id} className=${"pick" + (f.portrait === p.id ? " on" : "")} ...${tilt}>
            <input type="radio" name="portrait" className="sr" checked=${f.portrait === p.id} onChange=${() => set("portrait", p.id)} />
            <${Portrait} id=${p.id} size="m" alt=${p.alt} /><span className="glare" aria-hidden="true"></span>${f.portrait === p.id ? html`<span className="selmark"><${Check} /> Chosen</span>` : null}</label>`)}</div></fieldset>` : null}

        ${step === 1 ? html`<div className="stack-s"><h2 className="h3" tabIndex="-1"><label htmlFor="wname">Write your wizard name</label></h2>
          <div className="namescroll"><span className="quill" aria-hidden="true">✒</span>
            <input id="wname" className="namefield" maxLength="24" value=${f.name} autoComplete="off" onChange=${e => set("name", e.target.value)} onKeyDown=${e => { if (e.key === "Enter") next(); }} placeholder="A first name or nickname" /></div>
          <span className="small muted">Use a first name or nickname only. Do not use your full name. (${24 - f.name.length} letters left)</span></div>` : null}

        ${step === 2 ? html`<fieldset><legend><h2 className="h3" tabIndex="-1">Choose your house</h2></legend>
          <div className="housegrid">${HOUSES.map(x => html`<label key=${x.id} className=${"housepick" + (f.house === x.id ? " on" : "")} style=${{ "--hc": x.colour }}>
            <input type="radio" name="house" className="sr" checked=${f.house === x.id} onChange=${() => set("house", x.id)} />
            <span className="swing"><${Pennant} house=${x.id} selected=${f.house === x.id} /></span><span className="hname">${x.name}</span>
            <span className="small hmini">${x.motto}</span>${f.house === x.id ? html`<span className="selmark"><${Check} /> Chosen</span>` : null}</label>`)}</div>
          <p className="small muted">Your house is your team in the academy. Every house has the same quests.</p></fieldset>` : null}

        ${step === 3 ? html`<fieldset><legend><h2 className="h3" tabIndex="-1">Choose your school year</h2></legend>
          <div className="tomegrid">${YEARS.map(y => html`<label key=${y.id} className=${"tomepick" + (f.year === y.id ? " on" : "")} ...${tilt}>
            <input type="radio" name="year" className="sr" checked=${f.year === y.id} onChange=${() => set("year", y.id)} />
            <${YearTome} y=${y} on=${f.year === y.id} /><span className="hname">${y.label}</span><span className="small">${y.desc}</span>${f.year === y.id ? html`<span className="selmark"><${Check} /> Chosen</span>` : null}</label>`)}</div>
          <p className="small muted">Your year sets your activities. Your writing level grows as you complete quests.</p></fieldset>` : null}
      </div>

      <p className="errline" role="alert">${err}</p>
      <div className="row wrap gap-s between">
        <div className="row gap-s">${step > 0 ? html`<button type="button" className="btn secondary" onClick=${() => goStep(step - 1)}><${Arrow} left=${true} /> Back</button>` : null}
          ${cancel ? html`<button type="button" className="btn ghost" onClick=${cancel}>Cancel</button>` : null}</div>
        <div className="row gap-s">
          ${step < 3 ? html`<button type="button" className="btn gold" onClick=${next}>Next <${Arrow} /></button>` : null}
          ${step === 3 || editing ? html`<button type="button" className="btn gold big" onClick=${enter}>${editing ? "Save my wizard" : "Enter the academy"}</button>` : null}</div>
      </div>
    </section>
    <aside className="frame panel preview stack" aria-label="Preview of your wizard" style=${h ? { "--house": h.colour, "--house-deep": h.deep } : null}>
      <p className="eyebrow center-text">Your wizard</p>
      <div className="preview-card">
        <div className="pv-stage">
          ${h ? html`<span className="pv-banner" key=${"b" + h.id} aria-hidden="true"><${Pennant} house=${h.id} /></span>` : null}
          ${f.portrait ? html`<span className="pv-portrait" key=${f.portrait}><${Portrait} id=${f.portrait} size="l" house=${f.house} alt="" /></span>` : html`<span className="portrait l empty">Your portrait appears here</span>`}
          ${h ? html`<span className="pv-crest" key=${"c" + h.id}><${Crest} house=${h.id} size=${58} title=${h.name + " crest"} /></span>` : null}
        </div>
        <div className="stack-xs center-text"><span className="pname shimmer">${f.name.trim() || "Your name"}</span>
          <span>${h ? h.name : "Choose a house"} · ${f.year ? "Year " + f.year : "Choose a year"}</span></div>
        ${h ? html`<div className="stack-xs center-text"><span className="hmotto">“${h.motto}”</span><span className="small muted">${h.desc}</span>
          <span className="swatches center" aria-label=${"House colours: " + h.name}><i style=${{ background: h.colour }}></i><i style=${{ background: h.id === "honeystone" ? "#2B2A28" : h.metal }}></i></span></div>` : null}
      </div>
    </aside>
  </div>`;
}

function TopicStatus({ status }) {
  const m = { done: ["Completed", "st-done"], progress: ["In progress", "st-prog"], none: ["Not started", "st-none"] }[status];
  return html`<span className=${"status " + m[1]}><span aria-hidden="true">${status === "done" ? "✓" : status === "progress" ? "◐" : "○"}</span> ${m[0]}</span>`;
}
function topicStatus(attempts, topicId) {
  const list = Object.values(attempts).filter(a => a.topicId === topicId);
  if (list.some(a => a.completed)) return "done";
  if (list.some(a => hasContent(a))) return "progress";
  return "none";
}

function CommonRoom({ prof, progress, attempts, sched, go, startQuest, resume, today, classQuests }) {
  const h = HOUSE[prof.house], lv = levelInfo(progress.xp), st = streakInfo(progress.days, today);
  const todays = scheduleFor(sched, prof.year, today);
  let nextDay = null; if (!todays.topicId) for (let i = 1; i < 8; i++) { const d = addDays(today, i); if (scheduleFor(sched, prof.year, d).topicId) { nextDay = d; break; } }
  const qTopic = todays.topicId || (nextDay && scheduleFor(sched, prof.year, nextDay).topicId);
  const qDate = todays.topicId ? today : nextDay;
  const qAtt = Object.values(attempts).filter(a => a.topicId === qTopic && a.scheduledDate === qDate).sort((a, b) => b.updated - a.updated)[0];
  const unfinished = Object.values(attempts).filter(a => !a.completed && hasContent(a)).sort((a, b) => b.updated - a.updated)[0];
  const next = nextCollectible(progress.stars);
  const t = qTopic ? TOPIC[qTopic] : null;
  return html`<div className="stack-l">
    <section className="frame panel welcome" style=${{ "--house": h.colour, "--house-deep": h.deep }}>
      <div className="banner-hang" aria-hidden="true"><${Pennant} house=${h.id} /></div>
      <${Portrait} id=${prof.portrait} size="l" house=${prof.house} alt=${"Your portrait"} />
      <div className="stack-s grow">
        <p className="eyebrow">${h.name} common room</p>
        <h1 tabIndex="-1">Welcome back, ${prof.name}</h1>
        <div className="row wrap gap-s">
          <span className="pill">Year ${prof.year}</span>
          <span className="pill tip" tabIndex="0" aria-describedby="streak-tip">🔥 ${st.current}-day streak<span role="tooltip" id="streak-tip" className="tipbox">A writing day counts when you complete at least one writing quest. Days in a row build your streak. ${st.today ? "You have already written today." : "Complete a quest today to keep it going."} Longest: ${st.longest} days.</span></span>
          <span className="pill stars">★ ${progress.stars} stars</span>
          <span className="pill">Level ${lv.level} · ${lv.title}</span>
        </div>
        <${Bar} value=${lv.into} max=${100} label=${"XP to level " + (lv.level + 1)} sub=${lv.into + " of 100 XP"} />
        <p className="small muted">${st.current === 0 ? "Start a new streak by finishing a quest today." : st.today ? "Lovely work. Come back tomorrow to grow your streak." : "Finish a quest today to keep your streak growing."}</p>
      </div>
      <div className="archwin" aria-hidden="true" style=${{ backgroundImage: `url(${IMG.castle})` }}><span className="twinkle"></span></div>
      <span className="crestspot"><${Crest} house=${h.id} size=${84} title=${h.name + " crest"} /></span>
    </section>
    ${classQuests || null}
    <div className="room-grid">
      <section className="letter quest-today stack-s" aria-labelledby="tq-h">
        <span className="seal" aria-hidden="true"><${Crest} house=${h.id} size=${44} /></span>
        <p className="ornate" id="tq-h">${todays.topicId ? "Today's writing quest" : "Next writing quest"}</p>
        ${t ? html`<${React.Fragment}>
          <h2 className="questtitle">${t.title}</h2>
          <p>${t.goal}</p>
          <p className="small muted">${t.purpose} · ${qDate === today ? "Today" : fmtDS(qDate)} · ${todays.source === "sample" || !todays.topicId ? "Sample schedule" : "Set by your teacher"}</p>
          <ol className="steps-inline" aria-label="Quest steps">${["Explore", "Organise", "Write", "Review"].map((s, i) => html`<li key=${s}><span className="sn">${i + 1}</span>${s}</li>`)}</ol>
          <div className="row wrap gap-s center">${qAtt && qAtt.completed ? html`<button className="btn secondary" onClick=${() => resume(qAtt)}>View completed work</button>`
            : qAtt ? html`<button className="btn gold big" onClick=${() => resume(qAtt)}>Continue quest</button>`
            : html`<button className="btn gold big" onClick=${() => startQuest(qTopic, qDate)}>Start quest</button>`}</div>
          ${!todays.topicId ? html`<p className="small muted center-text">No quest is scheduled today. You can start the next one early, or choose any quest.</p>` : null}
        <//>` : html`<p>No quests are scheduled this week. Choose any quest from the library.</p>`}
      </section>
      <aside className="frame panel nextreward stack-s" aria-labelledby="nr-h">
        <p className="ornate" id="nr-h">Next reward</p>
        ${next ? html`<${React.Fragment}><${Collectible} c=${next} unlocked=${false} size="m" /><p className="cardtitle center-text">${next.name}</p>
          <${Bar} value=${progress.stars} max=${next.stars} label="Stars collected" sub=${progress.stars + " of " + next.stars + " stars"} /><//>`
          : html`<p>You have unlocked every collectible. Wonderful!</p>`}
        <button className="btn secondary small" onClick=${() => go("collection")}>Open my collection</button>
      </aside>
    </div>
    ${unfinished ? html`<section className="frame panel row wrap between gap-s" aria-label="Unfinished quest">
      <div className="stack-xs"><p className="eyebrow">Continue unfinished quest</p><p className="cardtitle">${TOPIC[unfinished.topicId].title}</p>
        <p className="small muted">Step: ${{ explore: "Explore", plan: "Organise", write: "Write", review: "Review" }[unfinished.step] || "Explore"} · Last saved ${fmtTime(unfinished.updated)}</p></div>
      <button className="btn gold" onClick=${() => resume(unfinished)}>Continue quest <${Arrow} /></button></section>` : null}
    <div className="tiles3">
      <button className="tilecard frame" ...${tilt} onClick=${() => go("quests")}><span className="glare" aria-hidden="true"></span><span className="tileart" aria-hidden="true" style=${{ backgroundImage: `url(${IMG.enchantedQuill}), radial-gradient(circle at 50% 50%, rgba(243,220,154,.15), #0A0E1B 70%)` }}></span><span className="cardtitle">Topic library</span><span className="small">Six Year ${prof.year} quests</span></button>
      <button className="tilecard frame" ...${tilt} onClick=${() => go("calendar")}><span className="glare" aria-hidden="true"></span><span className="miniweek" aria-hidden="true">${Array.from({ length: 5 }, (_, i) => { const ds = addDays(today, i - weekdayIdx(today) + (weekdayIdx(today) > 4 ? 7 : 0)); const s = scheduleFor(sched, prof.year, ds); return html`<span key=${ds} className=${ds === today ? "t" : ""}>${["Mon", "Tue", "Wed", "Thu", "Fri"][i]}<b>${+ds.slice(8)}</b>${s.topicId ? "✦" : ""}</span>`; })}</span><span className="cardtitle">Quest calendar</span><span className="small">See what is planned each day</span></button>
      <button className="tilecard frame" ...${tilt} onClick=${() => go("collection")}><span className="glare" aria-hidden="true"></span><span className="tileart" aria-hidden="true" style=${{ backgroundImage: `url(${IMG.goldCup}), radial-gradient(circle at 50% 50%, rgba(243,220,154,.18), #0A0E1B 70%)` }}></span><span className="cardtitle">My collection</span><span className="small">${Object.keys(progress.unlocked).length} of ${COLLECTIBLES.length} unlocked</span></button>
    </div>
  </div>`;
}

function Quests({ prof, attempts, progress, pick }) {
  const list = TOPICS.filter(t => t.year === prof.year);
  return html`<div className="stack-l">
    <div className="stack-s"><p className="eyebrow">Year ${prof.year} topic library</p><h1 tabIndex="-1">Choose your writing quest</h1>
      <p className="lead">Each quest is an everyday writing task. Your school year (Year ${prof.year}) sets which quests you see. You can change your year in Edit character.</p></div>
    <ul className="questgrid">${list.map(t => { const s = topicStatus(attempts, t.id); const times = Object.values(progress.ledger).filter(l => l.topicId === t.id).length; return html`<li key=${t.id}>
      <button className=${"questcard frame" + (s === "done" ? " is-done" : "")} ...${tilt} onClick=${() => { Sfx.play("select"); pick(t.id); }}><span className="glare" aria-hidden="true"></span>
        ${s === "done" ? html`<span className="waxseal" aria-hidden="true">✓</span>` : null}
        <span className="qframe"><${Scene} id=${t.scene} alt="" /></span>
        <span className="row between wrap gap-s"><span className="tag">${t.purpose}</span><${TopicStatus} status=${s} /></span>
        <span className="cardtitle">${t.title}</span>
        <span className="small"><strong>Objective:</strong> ${t.goal}</span>
        <span className="reward small">Completion reward: ★ 3 stars · 30 XP${times ? ` · earned ${times} time${times > 1 ? "s" : ""}` : ""}</span>
      </button></li>`; })}</ul>
    <p className="small muted">These topics are custom activities designed for Idea2Write. They are not textbook chapters.</p>
  </div>`;
}

function Support({ topicId, prof, level, setLevel, start, back, changing }) {
  const t = TOPIC[topicId];
  return html`<div className="stack-l">
    <div className="stack-s"><p className="eyebrow">Year ${prof.year} · ${t.title}</p><h1 tabIndex="-1">How much help would you like?</h1>
      <p className="lead">${t.task}</p><p>Choose a support option. You can change it at any time, and your work stays safe.</p></div>
    <div className="grid3">${LEVELS.map(l => html`<button key=${l.id} className=${"select-card frame" + (level === l.id ? " on" : "")} aria-pressed=${level === l.id} onClick=${() => setLevel(l.id)}>
      ${level === l.id ? html`<span className="selmark"><${Check} /> Selected</span>` : null}
      <span className="cardtitle">${l.name}</span><span className="sub">${l.sub}</span>
      <ul className="ticks">${l.gets.map(g => html`<li key=${g}>${g}</li>`)}</ul></button>`)}</div>
    <p className="note">Every option keeps the same writing goal for Year ${prof.year}: <strong>${yearOf(prof.year).goalText}</strong>. Only the amount of help changes.</p>
    <div className="navrow"><button className="btn secondary" onClick=${back}><${Arrow} left=${true} /> ${changing ? "Back to my quest" : "Back to quests"}</button>
      <div className="row gap-s">${!level ? html`<span className="hintnote">Choose an option to continue.</span>` : null}
      <button className="btn gold" disabled=${!level} onClick=${start}>${changing ? "Use this option" : "Begin the quest"} <${Arrow} /></button></div></div>
  </div>`;
}

function Calendar({ prof, attempts, sched, today, startQuest, resume, classDue = [], startAssignment }) {
  const [year, setYear] = useState(prof.year);
  const [ym, setYm] = useState(() => today.slice(0, 7));
  const [sel, setSel] = useState(today);
  const [y, m] = ym.split("-").map(Number);
  const first = `${ym}-01`, days = new Date(Date.UTC(y, m, 0)).getUTCDate(), lead = weekdayIdx(first);
  const cells = [...Array(lead).fill(null), ...Array.from({ length: days }, (_, i) => `${ym}-${String(i + 1).padStart(2, "0")}`)];
  while (cells.length % 7) cells.push(null);
  const shift = (n) => { const d = new Date(Date.UTC(y, m - 1 + n, 1)); setYm(toDS(d).slice(0, 7)); };
  const stat = (ds) => { const s = scheduleFor(sched, year, ds); if (!s.topicId) return null;
    const att = Object.values(attempts).filter(a => a.topicId === s.topicId && a.scheduledDate === ds).sort((a, b) => b.updated - a.updated);
    const st = att.some(a => a.completed) ? "done" : att.some(hasContent) ? "progress" : "none";
    return { ...s, st, att: att.find(a => a.completed) || att[0] }; };
  const dueOn = (ds) => classDue.filter(x => x.due_date === ds);
  const asgAttempt = (x) => Object.values(attempts).filter(a => a.assignmentId === x.id).sort((p, q) => q.updated - p.updated)[0];
  const selDue = dueOn(sel);
  const ss = stat(sel), monthName = parseDS(first).toLocaleDateString("en-GB", { month: "long", year: "numeric", timeZone: "UTC" });
  const own = year === prof.year;
  return html`<div className="stack-l">
    <section className="frame panel stack" aria-labelledby="cal-h">
      <${Ribbon} id="cal-h" as="h1">Quest calendar<//>
      <div className="row wrap between gap-s">
        <div className="row gap-s"><label htmlFor="cal-year">School year:</label>
          <select id="cal-year" className="field small sel" value=${year} onChange=${e => setYear(+e.target.value)}>${YEARS.map(x => html`<option key=${x.id} value=${x.id}>${x.label}</option>`)}</select></div>
        <div className="row gap-s"><button className="btn secondary small" onClick=${() => shift(-1)}><${Arrow} left=${true} /> Previous month</button>
          <strong className="monthname" aria-live="polite">${monthName}</strong>
          <button className="btn secondary small" onClick=${() => shift(1)}>Next month <${Arrow} /></button>
          <button className="btn ghost small" onClick=${() => { setYm(today.slice(0, 7)); setSel(today); }}>Today</button></div>
      </div>
      <p className="small muted">Sample schedule: quests rotate through the six Year ${year} topics on school days (Monday to Friday). Your teacher can change it. Dates use Malaysia time.</p>
      <div className="calwrap"><table className="cal" aria-label=${"Quest calendar for " + monthName}>
        <thead><tr>${["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map(d => html`<th key=${d} scope="col">${d}</th>`)}</tr></thead>
        <tbody>${Array.from({ length: cells.length / 7 }, (_, r) => html`<tr key=${r}>${cells.slice(r * 7, r * 7 + 7).map((ds, i) => { if (!ds) return html`<td key=${i} className="blank"></td>`;
          const s = stat(ds), isT = ds === today, isS = ds === sel;
          return html`<td key=${ds}><button className=${"day" + (isT ? " today" : "") + (isS ? " selected" : "") + (s ? " has" : "")} aria-pressed=${isS} onClick=${() => setSel(ds)}
            aria-label=${fmtDS(ds) + (isT ? ", today" : "") + (s ? ", " + TOPIC[s.topicId].title + ", " + { done: "completed", progress: "in progress", none: "not started" }[s.st] : ", no quest")}>
            <span className="dnum">${+ds.slice(8)}</span>${s ? html`<${React.Fragment}><span className=${"dmark m-" + s.st} aria-hidden="true">${s.st === "done" ? "✓" : s.st === "progress" ? "◐" : "○"}</span><span className="dtopic">${TOPIC[s.topicId].title}</span><//>` : null}${dueOn(ds).length ? html`<span className="dclass">📜 ${dueOn(ds).length} class quest${dueOn(ds).length > 1 ? "s" : ""} due</span>` : null}</button></td>`; })}</tr>`)}</tbody>
      </table></div>
      <ul className="legend" aria-label="Legend"><li><span className="dmark m-done">✓</span> Completed</li><li><span className="dmark m-progress">◐</span> In progress</li><li><span className="dmark m-none">○</span> Not started</li><li><span className="lg-today"></span> Today (gold outline)</li><li><span className="lg-sel"></span> Selected date (filled)</li>${classDue.length ? html`<li><span className="dclass">📜</span> Class quest due (set by your teacher, separate from the sample schedule)</li>` : null}</ul>
    </section>
    <section className="parchment-card" aria-live="polite" aria-labelledby="sel-h">
      <h2 id="sel-h" className="pdate">${fmtDS(sel)}${sel === today ? " · Today" : ""}</h2>
      ${ss ? html`<${React.Fragment}><p className="ptitle">${TOPIC[ss.topicId].title}</p>
        <p>${TOPIC[ss.topicId].purpose} · <${TopicStatus} status=${ss.st} /> · ${ss.source === "sample" ? "Sample schedule" : "Set by teacher"}</p>
        ${!own ? html`<p className="small">This is a Year ${year} quest. Your quests come from Year ${prof.year}.</p>` :
          html`<div className="row wrap gap-s">${ss.st === "done" ? html`<button className="btn gold" onClick=${() => resume(ss.att)}>View completed work</button>`
            : ss.st === "progress" ? html`<button className="btn gold" onClick=${() => resume(ss.att)}>Continue quest</button>`
            : html`<button className="btn gold" onClick=${() => startQuest(ss.topicId, sel)}>Start quest</button>`}</div>`}
        ${sel < today && ss.st === "none" ? html`<p className="small">Past quests stay available. You can still complete this one.</p>` : null}<//>`
        : html`<p>No quest is scheduled on this date.</p>`}
      ${selDue.length ? html`<div className="stack-s classdue"><p className="strong">Class quests due on this day</p>${selDue.map(x => { const at = asgAttempt(x); const t = TOPIC[x.topic_id]; return html`<div key=${x.id} className="row wrap between gap-s"><span><strong>${t.title}</strong> · ${x.cls.class_name} · <${WorkStatus} status=${workStatusFor(x, attempts)} /></span>
        <button className="btn gold small" onClick=${() => at ? resume(at) : startAssignment(x, x.cls)}>${at ? (at.completed ? "View my writing" : "Continue quest") : "Start quest"}</button></div>`; })}</div>` : null}
      <p className="small">Opening a date does not give stars or streak days. Rewards come only from completing a quest.</p>
    </section>
  </div>`;
}

function Cabinet({ progress, open }) {
  return html`<ul className="cabinet">${COLLECTIBLES.map(c => { const u = !!progress.unlocked[c.id]; return html`<li key=${c.id}>
    <button className=${"plinth" + (u ? " unlocked" : "")} ...${tilt} onClick=${() => { Sfx.play(u ? "unlock" : "page"); open(c); }} aria-label=${(u ? "Inspect " : "Locked: ") + c.name}>
      <${Collectible} c=${c} unlocked=${u} /><span className="cushion" aria-hidden="true"></span>
      <span className="plate">${c.name}</span>
      <span className=${"state " + (u ? "ok" : "")}>${u ? "✓ Unlocked" : "🔒 Unlock at " + c.stars + " stars"}</span></button></li>`; })}</ul>`;
}
function inspectDialog(c, progress) {
  const u = !!progress.unlocked[c.id];
  return { title: c.name, media: html`<div className="closeup"><${Collectible} c=${c} unlocked=${u} size="xl" /></div>`,
    body: u ? [c.desc, `Unlocked on ${fmtDS(progress.unlocked[c.id])} at ${c.stars} stars.`] : [`This item is still locked. It unlocks when you have ${c.stars} stars in total.`, `You have ${progress.stars} stars, so you need ${c.stars - progress.stars} more.`],
    actions: [{ label: "Close", kind: "gold" }] };
}

function CollectionPage({ progress, setDialog }) {
  const next = nextCollectible(progress.stars);
  return html`<div className="stack-l">
    <section className="frame panel stack" aria-labelledby="col-h">
      <${Ribbon} id="col-h" as="h1">My collection<//>
      <div className="row wrap between"><span className="pill stars big">★ ${progress.stars} stars earned</span>
        ${next ? html`<span className="small">Next: <strong>${next.name}</strong> at ${next.stars} stars (${next.stars - progress.stars} to go)</span>` : html`<span>Every item is unlocked.</span>`}</div>
      <${Cabinet} progress=${progress} open=${c => setDialog(inspectDialog(c, progress))} />
      <p className="small muted">Stars are earned by completing writing quests and are never spent or taken away. Choose any item to look closer.</p>
    </section>
  </div>`;
}

function Profile({ prof, progress, today, go, setDialog, editChar }) {
  const h = HOUSE[prof.house], lv = levelInfo(progress.xp), st = streakInfo(progress.days, today);
  const yTopics = TOPICS.filter(t => t.year === prof.year);
  const bars = PRACTICE_CATS.map(c => ({ ...c, done: yTopics.filter(t => progress.practice[t.id + ":" + c.id]).length, total: yTopics.length }));
  const [shown, setShown] = useState(false);
  useEffect(() => { const id = requestAnimationFrame(() => setShown(true)); return () => cancelAnimationFrame(id); }, []);
  return html`<div className="stack-l">
    <div className="profile-grid">
      <section className="frame panel char" style=${{ "--house": h.colour, "--house-deep": h.deep }} aria-label="Character">
        <${Portrait} id=${prof.portrait} size="xl" house=${prof.house} alt="Your portrait" />
        <h1 tabIndex="-1" className="pname">${prof.name}</h1>
        <p>${h.name} · Year ${prof.year}</p>
        <${Crest} house=${h.id} size=${60} title=${h.name + " crest"} />
        <button className="btn secondary small" onClick=${editChar}>Edit character</button>
      </section>
      <section className="frame panel stack" aria-labelledby="stats-h">
        <h2 id="stats-h" className="sr">Progress</h2>
        <div className="row wrap gap-s"><span className="pill gold-pill">Level ${lv.level} · ${lv.title}</span><span className="pill">🔥 ${st.current}-day streak</span><span className="pill">Longest streak: ${st.longest}</span><span className="pill stars">★ ${progress.stars} stars</span><span className="pill">Quests completed: ${Object.keys(progress.ledger).length}</span></div>
        <${Bar} value=${lv.into} max=${100} label=${"Writing level " + lv.level + " → " + (lv.level + 1)} sub=${`${lv.into} of 100 XP · ${progress.xp} XP total`} />
        <div className=${"skillbars" + (shown ? " shown" : "")}>
          ${bars.map(b => html`<${Bar} key=${b.id} value=${shown ? b.done : 0} max=${b.total} label=${b.name} sub=${`${b.done} of ${b.total} activities completed`} />`)}
        </div>
        <p className="small muted center-text"><em>Practice completed, not a proficiency score.</em> These bars count the Year ${prof.year} practice activities you have finished. They do not measure how well you know grammar or vocabulary.</p>
        <button className="btn secondary small align-start" onClick=${() => go("practice")}>Go to practice</button>
      </section>
    </div>
    <div className="profile-grid b">
      <section className="frame panel stack" aria-labelledby="cab-h">
        <div className="row wrap between"><${Ribbon} id="cab-h">My collection<//><span className="pill stars">★ ${progress.stars} stars earned</span></div>
        <${Cabinet} progress=${progress} open=${c => setDialog(inspectDialog(c, progress))} />
      </section>
      <section className="frame panel stack-s" aria-labelledby="ach-h">
        <${Ribbon} id="ach-h">Achievements<//>
        <ul className="achs">${ACHIEVEMENTS.map(a => { const d = progress.achievements[a.id]; return html`<li key=${a.id} className=${d ? "got" : ""}><span aria-hidden="true">${d ? "◆" : "◇"}</span>
          <span><strong>${a.name}</strong><br /><span className="small">${d ? "Earned " + fmtDS(d) : a.desc}</span></span></li>`; })}</ul>
      </section>
    </div>
  </div>`;
}

function PracticeHall({ prof, progress, run }) {
  const yTopics = TOPICS.filter(t => t.year === prof.year);
  return html`<div className="stack-l">
    <div className="stack-s"><p className="eyebrow">Practice hall · Year ${prof.year}</p><h1 tabIndex="-1">Short practice activities</h1>
      <p className="lead">Each activity uses words and sentences from one of your quests. Check your answers and read the explanation. Finished activities fill your profile bars.</p></div>
    <div className="grid3">${PRACTICE_CATS.map(c => { const done = yTopics.filter(t => progress.practice[t.id + ":" + c.id]).length; return html`<section key=${c.id} className="frame panel stack-s" aria-labelledby=${"pc-" + c.id}>
      <h2 id=${"pc-" + c.id} className="h3">${c.name}</h2>
      <${Bar} value=${done} max=${yTopics.length} label="Completed" sub=${`${done} of ${yTopics.length} activities completed`} />
      <ul className="plist">${yTopics.map(t => { const r = progress.practice[t.id + ":" + c.id]; return html`<li key=${t.id}><button className="plink" onClick=${() => run(t.id, c.id)}>
        <span>${t.title}</span><span className=${"status " + (r ? "st-done" : "st-none")}>${r ? "✓ Done" : "○ Start"}</span></button></li>`; })}</ul>
    </section>`; })}</div>
    <p className="note">Practice progress shows activities you have finished. It is not a test score and does not show mastery.</p>
  </div>`;
}

function OrderQuestion({ q, qid, onResult, done }) {
  const tokens = useMemo(() => shuffle(q.sentence.split(" "), qid).map(([w, i]) => ({ w, i })), [qid]);
  const [picked, setPicked] = useState([]);
  const left = tokens.filter(t => !picked.includes(t));
  const answer = picked.map(t => t.w).join(" ");
  return html`<div className="stack-s">
    <div className="tiles built" aria-label="Your sentence" aria-live="polite">${picked.length ? picked.map((t, k) => html`<button key=${k} className="wtile on" disabled=${done} onClick=${() => setPicked(picked.filter(x => x !== t))} aria-label=${"Remove " + t.w}>${t.w}</button>`) : html`<span className="small muted">Choose the words below in order.</span>`}</div>
    <div className="tiles">${left.map((t, k) => html`<button key=${k} className="wtile" disabled=${done} onClick=${() => setPicked([...picked, t])}>${t.w}</button>`)}</div>
    <div className="row gap-s wrap"><button className="btn secondary small" disabled=${done || !picked.length} onClick=${() => setPicked([])}>Clear</button>
      <button className="btn gold small" disabled=${done || left.length > 0} onClick=${() => onResult(answer === q.sentence)}>Check</button></div>
  </div>`;
}

function PracticeRun({ topicId, cat, progress, setProgress, back }) {
  const t = TOPIC[topicId], qs = useMemo(() => practiceActivity(topicId, cat), [topicId, cat]);
  const catName = PRACTICE_CATS.find(c => c.id === cat).name;
  const [res, setRes] = useState({}); /* index -> {ok, tries} */
  const [chosen, setChosen] = useState({});
  const [msg, setMsg] = useState(""), [justDone, setJustDone] = useState(false);
  const key = topicId + ":" + cat, already = progress.practice[key];
  const allOk = qs.every((_, i) => res[i] && res[i].ok);
  useEffect(() => {
    if (allOk && !already) {
      const today = klDate(); setJustDone(true);
      const firstTry = qs.filter((_, i) => res[i].tries === 1).length;
      setProgress(p => { const n = JSON.parse(JSON.stringify(p)); n.practice[key] = { date: today, firstTry, total: qs.length }; const got = awardAchievements(n, today); if (got.length) setMsg("New achievement: " + got.map(a => a.name).join(", ") + "."); return n; });
    }
  }, [allOk]);
  const answer = (i, ok) => setRes(r => ({ ...r, [i]: { ok, tries: ((r[i] && r[i].tries) || 0) + 1 } }));
  return html`<div className="stack-l narrow">
    <div className="stack-s"><p className="eyebrow">${catName} · ${t.title}</p><h1 tabIndex="-1">${catName}</h1>
      <p className="lead">Answer each question, then check it. You can try again if it is not right yet.</p>
      ${already ? html`<p className="note">You completed this activity on ${fmtDS(already.date)}. You can practise again; it is already counted.</p>` : null}</div>
    <ol className="qrun">${qs.map((q, i) => { const r = res[i], opts = q.type === "mc" ? shuffle(q.options, topicId + cat + i) : null; return html`<li key=${i} className="frame panel stack-s">
      <p className="qprompt">${q.prompt}</p>
      ${q.type === "mc" ? html`<${React.Fragment}><fieldset><legend className="sr">${q.prompt}</legend><div className="stack-xs">${opts.map(([o, oi]) => html`<label key=${oi} className=${"optrow" + (chosen[i] === oi ? " on" : "")}>
          <input type="radio" name=${"q" + i} checked=${chosen[i] === oi} disabled=${r && r.ok} onChange=${() => setChosen({ ...chosen, [i]: oi })} /> ${o}</label>`)}</div></fieldset>
        <button className="btn gold small align-start" disabled=${chosen[i] === undefined || (r && r.ok)} onClick=${() => answer(i, chosen[i] === q.answer)}>Check answer</button><//>`
      : html`<${OrderQuestion} q=${q} qid=${topicId + cat + i} done=${r && r.ok} onResult=${ok => answer(i, ok)} />`}
      ${r ? html`<div className=${"feedback " + (r.ok ? "good" : "again")} role="status"><strong>${r.ok ? "Correct." : "Not yet. Try again."}</strong> ${r.ok ? q.why : q.type === "order" ? "Look at the capital letter and the full stop to find the first and last words." : "Read the sentence aloud with your choice, then check the rule: " + q.why}</div>` : null}
    </li>`; })}</ol>
    ${allOk ? html`<p className="note" role="status">Activity complete. ${justDone ? "It now counts in your practice progress." : "It was already counted in your progress."} ${msg}</p>` : null}
    <div className="navrow"><button className="btn secondary" onClick=${back}><${Arrow} left=${true} /> Back to practice hall</button></div>
  </div>`;
}

function Journal({ attempts, progress, resume, del, go }) {
  const list = Object.values(attempts).sort((x, y) => y.updated - x.updated);
  const [confirm, setConfirm] = useState(null);
  return html`<div className="stack-l">
    <div className="stack-s"><h1 tabIndex="-1">My quest journal</h1><p className="lead">All your writing for this profile, saved on this browser and device only.</p></div>
    ${!CAN_STORE ? html`<p className="note">Saving is unavailable in this browser, so nothing is kept after you close the page.</p>` : null}
    ${list.length === 0 ? html`<div className="frame panel stack-s center-text"><p>No quests yet.</p><div><button className="btn gold" onClick=${() => go("quests")}>Choose a quest</button></div></div>` :
    html`<ul className="drafts">${list.map(d => { const t = TOPIC[d.topicId]; if (!t) return null; const rw = progress.ledger[d.id]; return html`<li key=${d.id} className="frame panel draftcard">
      <span className="qframe mini"><${Scene} id=${t.scene} alt="" /></span>
      <div className="stack-xs grow"><h2 className="h3">${t.title}</h2>
        <p className="small">Year ${d.year} · ${levelOf(d.level).name} · ${d.completed ? html`<span className="status st-done">✓ Completed</span>` : html`<span className="status st-prog">◐ In progress</span>`}${rw ? " · ★ 3 stars earned" : ""}${d.imported ? " · imported from earlier version" : ""}</p>
        <p className="small muted">Last updated ${fmtTime(d.updated)} · ${words(d.draft)} words${d.scheduledDate ? " · scheduled " + fmtDS(d.scheduledDate, { day: "numeric", month: "short" }) : ""}</p></div>
      ${confirm === d.id ? html`<div className="row wrap gap-s confirm" role="alert"><span className="small">Delete this writing? This cannot be undone. Stars already earned are kept.</span>
          <button className="btn small danger-btn" onClick=${() => { del(d.id); setConfirm(null); }}>Yes, delete</button><button className="btn small secondary" onClick=${() => setConfirm(null)}>Keep it</button></div>`
        : html`<div className="row wrap gap-s"><button className="btn gold small" onClick=${() => resume(d)}>${d.completed ? "View" : "Resume"}</button><button className="btn ghost small danger" onClick=${() => setConfirm(d.id)} aria-label=${"Delete " + t.title}>Delete</button></div>`}
    </li>`; })}</ul>`}
  </div>`;
}
/* ===== Writing quest screens: Explore → Organise → Write → Review → reward ===== */
const STEPS = [["explore", "Explore"], ["plan", "Organise"], ["write", "Write"], ["review", "Review"]];

function ActivityBar({ attempt, step, setLevel, goStep, changeTopic, save }) {
  const t = TOPIC[attempt.topicId], idx = STEPS.findIndex(s => s[0] === step);
  return html`<div className="actbar frame">
    <div className="row wrap between gap-s">
      <div className="row gap-s wrap"><span className="scroll-ic" aria-hidden="true">✒</span><span className="acttitle">${t.title}</span>
        <span className="pill">Year ${attempt.year}</span><span className="pill">${t.purpose}</span></div>
      <div className="row wrap gap-s"><${SaveStatus} save=${save} /><button className="btn ghost small" onClick=${changeTopic}>Change quest</button></div>
    </div>
    <div className="row wrap between gap-s">
      <ol className="progress" aria-label="Quest steps">
        ${STEPS.map(([id, label], i) => html`<li key=${id}>
          <button className=${"pstep" + (i === idx ? " now" : i < idx ? " done" : "")} aria-current=${i === idx ? "step" : undefined} onClick=${() => goStep(id)}>
            <span className="num" aria-hidden="true">${i < idx ? "✓" : i + 1}</span>${label}${i < idx ? html`<span className="sr"> (visited)</span>` : null}</button></li>`)}
      </ol>
      <div className="levelswitch" role="group" aria-label="Support option">
        ${LEVELS.map(l => html`<button key=${l.id} aria-pressed=${attempt.level === l.id} onClick=${() => setLevel(l.id)}>${attempt.level === l.id ? "✓ " : ""}${l.name}</button>`)}
      </div>
    </div>
  </div>`;
}

function NavRow({ back, backLabel = "Back", next, nextLabel = "Continue", note }) {
  return html`<div className="navrow">
    ${back ? html`<button className="btn secondary" onClick=${back}><${Arrow} left=${true} /> ${backLabel}</button>` : html`<span />`}
    <div className="row wrap end gap-s">${note ? html`<span className="hintnote" role="status">${note}</span>` : null}
      ${next ? html`<button className="btn gold" onClick=${next}>${nextLabel} <${Arrow} /></button>` : null}</div>
  </div>`;
}

function Vocab({ list, open, selectedWord, onSelect }) {
  const [sel, setSel] = useState(null);
  const current = onSelect ? selectedWord : sel;
  const item = list.find(v => v[0] === current);
  return html`<details className="panel frame" open=${open}>
    <summary>Word bank <span className="muted small">(optional · ${list.length} words)</span></summary>
    <p className="small muted">Choose a word to see what it means.</p>
    <div className="chiprow">${list.map(([w]) => html`<button key=${w} className=${"wordchip" + (current === w ? " on" : "")} aria-pressed=${current === w} onClick=${() => onSelect ? onSelect(current === w ? null : w) : setSel(sel === w ? null : w)}>${w}</button>`)}</div>
    <div className="meaning" aria-live="polite">${item ? html`<span><strong>${item[0]}</strong>: ${item[1]}</span>` : html`<span className="muted">No word chosen yet.</span>`}</div>
  </details>`;
}

function IdeaItem({ c, update, remove }) {
  const [edit, setEdit] = useState(false), [val, setVal] = useState(c.text);
  if (edit) return html`<li className="idea editing"><label className="sr" htmlFor=${"ed-" + c.id}>Edit idea</label>
    <input id=${"ed-" + c.id} className="field" value=${val} onChange=${e => setVal(e.target.value)} onKeyDown=${e => { if (e.key === "Enter" && val.trim()) { update(val.trim()); setEdit(false); } if (e.key === "Escape") setEdit(false); }} autoFocus />
    <button className="btn small gold" onClick=${() => { if (val.trim()) { update(val.trim()); setEdit(false); } }}>Save</button>
    <button className="btn small ghost" onClick=${() => { setVal(c.text); setEdit(false); }}>Cancel</button></li>`;
  return html`<li className="idea"><span className="ideatext">${c.text}</span>
    <button className="btn small ghost" onClick=${() => { setVal(c.text); setEdit(true); }} aria-label=${"Edit idea: " + c.text}>Edit</button>
    <button className="btn small ghost danger" onClick=${remove} aria-label=${"Remove idea: " + c.text}>Remove</button></li>`;
}

/* Extra Guide-me support: noticing prompts and picture words beside the picture */
function LookClosely({ t, addIdea, word, setWord }) {
  const [own, setOwn] = useState(""), [msg, setMsg] = useState("");
  const pictured = pictureWords(t);
  const prompts = ["What can you see in the picture?", "Who is in the picture, and what are they doing?", "Which word below matches something in the picture?"];
  const it = pictured.find(v => v[0] === word);
  return html`<section className="frame panel stack-s lookclosely" aria-labelledby="lc-h">
    <h2 id="lc-h" className="h3">Look closely <span className="small muted">(Guide me)</span></h2>
    <ol className="small lc-prompts">${prompts.map(p => html`<li key=${p}>${p}</li>`)}</ol>
    <p className="small"><strong>Picture words:</strong> choose one to see its meaning.</p>
    <div className="chiprow">${pictured.map(([w]) => html`<button key=${w} className=${"wordchip" + (word === w ? " on" : "")} aria-pressed=${word === w} onClick=${() => setWord(word === w ? null : w)}>${w}</button>`)}</div>
    <div className="meaning" aria-live="polite">${it ? html`<span><strong>${it[0]}</strong>: ${it[1]}</span>` : html`<span className="muted">No word chosen yet.</span>`}</div>
    <label htmlFor="lc-own" className="small strong">Write what you notice, in your own words</label>
    <div className="row gap-s addrow"><input id="lc-own" className="field" value=${own} placeholder=${"I can see…"} onChange=${e => { setOwn(e.target.value); setMsg(""); }} onKeyDown=${e => { if (e.key === "Enter" && own.trim()) { addIdea(own.trim()); setOwn(""); setMsg("Added to your ideas."); } }} />
      <button className="btn secondary small" onClick=${() => { if (!own.trim()) { setMsg("Type what you notice first."); return; } addIdea(own.trim()); setOwn(""); setMsg("Added to your ideas."); }}>Add to my ideas</button></div>
    <p className="small hintnote" role="status">${msg}</p>
  </section>`;
}

function Explore({ a, update, next, back }) {
  const t = TOPIC[a.topicId], lv = a.level;
  const [pictureWord, setPictureWord] = useState(null);
  useEffect(() => setPictureWord(null), [a.topicId]);
  const [text, setText] = useState(""), [msg, setMsg] = useState(""), [moreQ, setMoreQ] = useState(lv === "easy");
  const shown = lv === "easy" || moreQ ? t.questions : lv === "medium" ? t.questions.slice(0, 4) : [];
  const answerCard = (i) => a.cards.find(c => c.q === i);
  const setAnswer = (i, v) => update(x => {
    const ex = x.cards.find(c => c.q === i);
    if (!v.trim()) return { ...x, cards: x.cards.filter(c => c.q !== i) };
    if (ex) return { ...x, cards: x.cards.map(c => c.q === i ? { ...c, text: v } : c) };
    return { ...x, cards: [...x.cards, { id: uid("c"), text: v, section: null, q: i }] };
  });
  const add = () => { const v = text.trim(); if (!v) { setMsg("Type a short idea first, then choose Add idea."); return; } update(x => ({ ...x, cards: [...x.cards, { id: uid("c"), text: v, section: null }] })); setText(""); setMsg("Idea added."); };
  const free = a.cards.filter(c => c.q === undefined);
  return html`<div className="stack-l">
    <div className="stack-s"><h1 tabIndex="-1">Explore your ideas</h1><p className="lead">${t.task}</p></div>
    ${a.assignment ? html`<${AssignmentNote} as=${a.assignment} />` : null}
    <div className="explore-grid">
      <div className="stack">
        <figure className="frame panel picture"><figcaption className="tagline">Picture prompt</figcaption><span className="qframe big"><${Scene} id=${t.scene} alt=${t.alt} interactive=${true} selectedWord=${pictureWord} onSelect=${setPictureWord} /></span><p className="small muted">${t.alt}</p><p className="small muted">Hover over an object or action to see its name. On a touch screen, tap it; with a keyboard, Tab to it and press Enter.</p>${lv === "easy" ? html`<${PictureActions} t=${t} selectedWord=${pictureWord} onSelect=${setPictureWord} />` : null}</figure>
        ${lv === "easy" ? html`<${LookClosely} t=${t} word=${pictureWord} setWord=${setPictureWord} addIdea=${v => update(x => ({ ...x, cards: [...x.cards, { id: uid("c"), text: v, section: null }] }))} />` : null}
      </div>
      <div className="stack">
        ${lv === "hard" ? html`<div className="frame panel stack-s"><h2 className="h3">Your writing goal</h2><p>${t.goal}</p><p className="small">Year ${a.year} goal: <strong>${yearOf(a.year).goalText}</strong>.</p>
          ${!moreQ ? html`<button className="btn secondary small align-start" onClick=${() => setMoreQ(true)}>Need a hint? Show guiding questions</button>` : null}</div>` : null}
        ${shown.length ? html`<div className="frame panel stack-s"><h2 className="h3">Think about… <span className="small muted">(your answers become idea cards)</span></h2>
          <ol className="qanswers">${shown.map((q, i) => { const c = answerCard(i); return html`<li key=${q}><label htmlFor=${"qa-" + i}>${q}</label>
            <input id=${"qa-" + i} className="field" value=${c ? c.text : ""} onChange=${e => setAnswer(i, e.target.value)} placeholder="Type your own answer" /></li>`; })}</ol>
          ${lv === "medium" && !moreQ ? html`<button className="linkbtn small align-start" onClick=${() => setMoreQ(true)}>Show more questions</button>` : null}</div>` : null}
        <div className="frame panel stack-s">
          <label htmlFor="idea-input" className="h3">Add another idea</label>
          <div className="row gap-s addrow"><input id="idea-input" className="field" value=${text} placeholder="A few words or a short sentence" onChange=${e => { setText(e.target.value); setMsg(""); }} onKeyDown=${e => { if (e.key === "Enter") add(); }} />
            <button className="btn gold" onClick=${add}>Add idea</button></div>
          <p className="small hintnote" role="status">${msg}</p>
        </div>
        ${lv === "hard" ? html`<details className="panel frame"><summary>Word ideas (optional)</summary><p className="small">${t.vocab.slice(0, 6).map(v => v[0]).join(", ")}</p></details>`
          : html`<${Vocab} list=${lv === "easy" ? t.vocab : t.vocab.slice(0, 6)} open=${lv === "easy"} selectedWord=${pictureWord} onSelect=${lv === "easy" ? setPictureWord : null} />`}
        ${lv !== "hard" ? html`<details className="panel frame" open=${lv === "easy"}><summary>Sentence starters <span className="muted small">(optional, for later)</span></summary>
          <p className="small muted">You can use these when you write. You finish each sentence in your own words.</p><ul className="small">${t.starters.map(s => html`<li key=${s}>${s}</li>`)}</ul></details>` : null}
      </div>
    </div>
    ${free.length ? html`<section className="frame panel stack-s" aria-labelledby="mine"><h2 id="mine" className="h3">My other ideas (${free.length})</h2>
      <ul className="ideas">${free.map(c => html`<${IdeaItem} key=${c.id} c=${c} update=${v => update(x => ({ ...x, cards: x.cards.map(k => k.id === c.id ? { ...k, text: v } : k) }))} remove=${() => update(x => ({ ...x, cards: x.cards.filter(k => k.id !== c.id) }))} />`)}</ul></section>` : null}
    <${NavRow} back=${back} backLabel="Support options" next=${next} nextLabel="Next: Organise" note=${a.cards.length ? a.cards.length + " idea(s) ready to organise" : "Answer a question or add an idea first. It helps your plan."} />
  </div>`;
}

function AssignmentNote({ as }) {
  return html`<div className="parchment-card stack-xs asg-note"><p className="eyebrow ink">Class quest · ${as.className} · ${as.teacherName}${as.due ? " · due " + fmtDS(as.due) : ""}</p>
    ${as.instructions ? html`<p><strong>Teacher's instructions:</strong> ${as.instructions}</p>` : html`<p>Your teacher set this quest for your class.</p>`}
    <p className="small">Your drafts stay private. Your teacher sees your writing only after you submit it.</p></div>`;
}

/* ---- Organise ---- */
function PlanCard({ c, a, moveTo, moveBy, edit, remove, first, last, picked, pick, onDragState }) {
  const [editing, setEditing] = useState(false), [val, setVal] = useState(c.text);
  const opts = [{ id: "", label: "Idea tray" }, ...a.sections.map(s => ({ id: s.id, label: s.label }))];
  return html`<li className=${"pcard" + (picked ? " picked" : "")} draggable=${!editing} onDragStart=${e => { e.dataTransfer.setData("text/plain", c.id); e.dataTransfer.effectAllowed = "move"; onDragState && onDragState(c.id); }} onDragEnd=${() => onDragState && onDragState(null)} data-card=${c.id}>
    ${editing ? html`<div className="row gap-s"><label className="sr" htmlFor=${"pe-" + c.id}>Edit card</label><input id=${"pe-" + c.id} className="field" value=${val} onChange=${e => setVal(e.target.value)} autoFocus onKeyDown=${e => { if (e.key === "Enter" && val.trim()) { edit(val.trim()); setEditing(false); } if (e.key === "Escape") setEditing(false); }} />
      <button className="btn small gold" onClick=${() => { if (val.trim()) { edit(val.trim()); setEditing(false); } }}>Save</button></div>`
    : html`<p className="pctext"><span className="grip" aria-hidden="true">⋮⋮</span>${c.text}</p>`}
    <div className="pcactions">
      <label className="sr" htmlFor=${"mv-" + c.id}>Move “${c.text}” to</label>
      <select id=${"mv-" + c.id} className="mini-select" value=${c.section || ""} onChange=${e => moveTo(e.target.value || null)}>
        ${opts.map(o => html`<option key=${o.id} value=${o.id}>${o.id === (c.section || "") ? "In: " : "Move to: "}${o.label}</option>`)}
      </select>
      <button className="iconbtn" onClick=${pick} aria-pressed=${picked} aria-label=${(picked ? "Put down: " : "Pick up to move: ") + c.text} title=${picked ? "Put down" : "Pick up, then choose Place here"}>${picked ? "✋" : "☝"}</button>
      <button className="iconbtn" onClick=${() => moveBy(-1)} disabled=${first} aria-label=${"Move up: " + c.text} title="Move up">↑</button>
      <button className="iconbtn" onClick=${() => moveBy(1)} disabled=${last} aria-label=${"Move down: " + c.text} title="Move down">↓</button>
      <button className="iconbtn" onClick=${() => { setVal(c.text); setEditing(true); }} aria-label=${"Edit: " + c.text} title="Edit">✎</button>
      <button className="iconbtn danger" onClick=${remove} aria-label=${"Delete: " + c.text} title="Delete">✕</button>
    </div></li>`;
}

function AddCard({ onAdd, label }) {
  const [v, setV] = useState(""); const id = useMemo(() => uid("ac"), []);
  return html`<div className="addcard"><label className="sr" htmlFor=${id}>${label}</label>
    <input id=${id} className="field small" placeholder="Add a detail" value=${v} onChange=${e => setV(e.target.value)} onKeyDown=${e => { if (e.key === "Enter" && v.trim()) { onAdd(v.trim()); setV(""); } }} />
    <button className="btn small secondary" onClick=${() => { if (v.trim()) { onAdd(v.trim()); setV(""); } }}>+ Add</button></div>`;
}

function SectionHead({ s, a, update, level }) {
  const [ren, setRen] = useState(false), [val, setVal] = useState(s.label), [hint, setHint] = useState(false);
  const saveName = () => { if (val.trim()) update(x => ({ ...x, sections: x.sections.map(k => k.id === s.id ? { ...k, label: val.trim() } : k) })); setRen(false); };
  return html`<div className="sechead">
    ${ren ? html`<div className="row gap-s"><label className="sr" htmlFor=${"rn-" + s.id}>Section name</label><input id=${"rn-" + s.id} className="field small" value=${val} onChange=${e => setVal(e.target.value)} autoFocus onKeyDown=${e => { if (e.key === "Enter") saveName(); }} />
      <button className="btn small gold" onClick=${saveName}>Save</button></div>`
      : html`<div className="row between gap-s"><h3>${s.label}</h3><button className="linkbtn small" onClick=${() => { setVal(s.label); setRen(true); }} aria-label=${"Rename section " + s.label}>Rename</button></div>`}
    ${level === "easy" && s.hint ? html`<p className="small muted">${s.hint}</p>` : null}
    ${level !== "easy" && s.hint ? html`<${React.Fragment}><button className="linkbtn small" aria-expanded=${hint} onClick=${() => setHint(!hint)}>${hint ? "Hide hint" : "Need a hint?"}</button>${hint ? html`<p className="small muted">${s.hint}</p>` : null}<//>` : null}
    ${a.year > 4 ? html`<div className="row gap-s small"><label htmlFor=${"pa-" + s.id}>Paragraph</label>
      <select id=${"pa-" + s.id} className="mini-select" value=${s.para} onChange=${e => update(x => ({ ...x, sections: x.sections.map(k => k.id === s.id ? { ...k, para: +e.target.value } : k) }))}>
        ${Array.from({ length: a.maxPara }, (_, i) => html`<option key=${i} value=${i + 1}>${i + 1}</option>`)}</select></div>` : null}
  </div>`;
}

function Plan({ a, update, next, back }) {
  const t = TOPIC[a.topicId];
  const [over, setOver] = useState(null), [live, setLive] = useState(""), [picked, setPicked] = useState(null), [dragging, setDragging] = useState(null);
  /* While a card is dragged, scroll the page when the pointer nears the top or bottom edge */
  useEffect(() => {
    if (!dragging) return;
    let y = null, raf = 0;
    const onOver = (e) => { y = e.clientY; };
    const tick = () => { if (y !== null) { const edge = 110, h = window.innerHeight; if (y < edge) window.scrollBy(0, -Math.ceil((edge - y) / 5)); else if (y > h - edge - 70) window.scrollBy(0, Math.ceil((y - (h - edge - 70)) / 5)); } raf = requestAnimationFrame(tick); };
    document.addEventListener("dragover", onOver); raf = requestAnimationFrame(tick);
    return () => { document.removeEventListener("dragover", onOver); cancelAnimationFrame(raf); };
  }, [dragging]);
  const cardsIn = (sid) => a.cards.filter(c => (c.section || null) === sid);
  const label = (sid) => sid ? (a.sections.find(s => s.id === sid) || {}).label : "Idea tray";
  const moveTo = (id, sid) => { Sfx.play("place"); update(x => { const c = x.cards.find(k => k.id === id); const rest = x.cards.filter(k => k.id !== id); return { ...x, cards: [...rest, { ...c, section: sid }] }; }); setLive("Card moved to " + label(sid) + "."); setPicked(null); };
  const moveBefore = (id, targetId) => update(x => { if (id === targetId) return x; const c = x.cards.find(k => k.id === id); const tgt = x.cards.find(k => k.id === targetId); const rest = x.cards.filter(k => k.id !== id); const i = rest.findIndex(k => k.id === targetId); rest.splice(i, 0, { ...c, section: tgt.section }); return { ...x, cards: rest }; });
  const moveBy = (id, dir) => { update(x => { const c = x.cards.find(k => k.id === id); const same = x.cards.filter(k => (k.section || null) === (c.section || null)); const j = same.findIndex(k => k.id === id) + dir; if (j < 0 || j >= same.length) return x; const other = same[j]; const arr = [...x.cards]; const ia = arr.findIndex(k => k.id === id), ib = arr.findIndex(k => k.id === other.id); [arr[ia], arr[ib]] = [arr[ib], arr[ia]]; return { ...x, cards: arr }; }); setLive("Card moved " + (dir < 0 ? "up." : "down.")); };
  const zone = (sid) => ({
    onDragOver: e => { e.preventDefault(); setOver(sid || "tray"); },
    onDragLeave: () => setOver(null),
    onDrop: e => { e.preventDefault(); setOver(null); setDragging(null); const id = e.dataTransfer.getData("text/plain"); if (!id) return; const tc = e.target.closest && e.target.closest("[data-card]"); if (tc && tc.dataset.card !== id) { moveBefore(id, tc.dataset.card); setLive("Card moved."); } else moveTo(id, sid); }
  });
  const place = (sid) => picked ? html`<button className="btn small gold placebtn" onClick=${() => moveTo(picked, sid)}>Place here</button>` : null;
  const list = (sid) => { const cs = cardsIn(sid); return html`<ul className="pcards">${cs.map((c, i) => html`<${PlanCard} key=${c.id} c=${c} a=${a} first=${i === 0} last=${i === cs.length - 1}
      onDragState=${setDragging} picked=${picked === c.id} pick=${() => { setPicked(picked === c.id ? null : c.id); setLive(picked === c.id ? "Card put down." : "Card picked up. Choose Place here on a section."); }}
      moveTo=${s => moveTo(c.id, s)} moveBy=${d => moveBy(c.id, d)}
      edit=${v => update(x => ({ ...x, cards: x.cards.map(k => k.id === c.id ? { ...k, text: v } : k) }))}
      remove=${() => { update(x => ({ ...x, cards: x.cards.filter(k => k.id !== c.id) })); setLive("Card deleted."); }} />`)}</ul>`; };
  const addSection = (para) => update(x => ({ ...x, sections: [...x.sections, { id: uid("s"), label: "New section", hint: "", para: para || x.maxPara }] }));
  const removeSection = (sid) => update(x => ({ ...x, sections: x.sections.filter(s => s.id !== sid), cards: x.cards.map(c => c.section === sid ? { ...c, section: null } : c) }));
  const missingSuggested = a.level !== "hard" && t.sections.some(([id]) => !a.sections.find(s => s.id === id));
  const groups = Array.from({ length: a.year === 4 ? 1 : a.maxPara }, (_, i) => i + 1);
  return html`<div className="stack-l">
    <div className="stack-s"><h1 tabIndex="-1">Give your ideas a home</h1>
      <p className="lead">Move your idea cards into the planner and put them in order. Drag a card, tap ☝ then “Place here”, or use the Move menu and ↑ ↓.</p></div>
    ${a.level === "easy" ? html`<div className="frame panel guidebox"><span className="qframe mini"><${Scene} id=${t.scene} alt=${t.alt} /></span>
      <div className="stack-xs"><p className="h3">How to organise (Guide me)</p><ol className="small"><li>Read each box's name and hint.</li><li>Move each idea card into the box where it fits best.</li><li>Use ↑ ↓ to put the cards in the order you will write them.</li></ol></div></div>` : null}
    <p className="sr" role="status" aria-live="polite">${live}</p>
    <section className=${"frame panel tray" + (over === "tray" ? " over" : "")} aria-labelledby="tray-h" ...${zone(null)}>
      <div className="row between wrap"><h2 id="tray-h" className="h3">Idea tray (${cardsIn(null).length})</h2>${place(null)}</div>
      ${cardsIn(null).length ? list(null) : html`<p className="muted small">The tray is empty. All your ideas are in the planner.</p>`}
      <${AddCard} label="Add a new idea to the tray" onAdd=${v => update(x => ({ ...x, cards: [...x.cards, { id: uid("c"), text: v, section: null }] }))} />
    </section>
    ${missingSuggested ? html`<div className="note row wrap between"><span>This planner has open sections. You can add the suggested sections for this quest.</span>
      <button className="btn small secondary" onClick=${() => update(x => ({ ...x, sections: [...x.sections, ...t.sections.filter(([id]) => !x.sections.find(s => s.id === id)).map(([id, label, hint, para]) => ({ id, label, hint, para: Math.min(para, x.maxPara) }))] }))}>Add suggested sections</button></div>` : null}
    ${groups.map(g => { const secs = a.sections.filter(s => (a.year === 4 ? true : s.para === g)); return html`<section key=${g} className="pgroup" aria-label=${a.year === 4 ? "Planner" : "Paragraph " + g}>
      ${a.year > 4 ? html`<h2 className="h3 grouph">Paragraph ${g}</h2>` : null}
      <div className="sections">${secs.map(s => html`<div key=${s.id} className=${"section frame c" + (a.sections.indexOf(s) % 4) + (over === s.id ? " over" : "")} ...${zone(s.id)}>
        <${SectionHead} s=${s} a=${a} update=${update} level=${a.level} />
        ${place(s.id)}
        ${cardsIn(s.id).length ? list(s.id) : html`<p className="empty">Drop a card here, or use “Move to”.</p>`}
        <${AddCard} label=${"Add a detail to " + s.label} onAdd=${v => update(x => ({ ...x, cards: [...x.cards, { id: uid("c"), text: v, section: s.id }] }))} />
        ${a.sections.length > 1 ? html`<button className="linkbtn small danger" onClick=${() => removeSection(s.id)} aria-label=${"Remove section " + s.label + " (its cards go back to the tray)"}>Remove section</button>` : null}
      </div>`)}
      ${secs.length === 0 ? html`<p className="empty">No sections in this paragraph yet.</p>` : null}
      </div>
      <button className="btn small ghost" onClick=${() => addSection(a.year === 4 ? 1 : g)}>+ Add a section${a.year > 4 ? " to paragraph " + g : ""}</button>
    </section>`; })}
    ${a.year === 5 && a.maxPara < 2 ? html`<button className="btn secondary" onClick=${() => update(x => ({ ...x, maxPara: 2 }))}>+ Add paragraph 2</button>` : null}
    ${a.year === 5 && a.maxPara === 2 && !a.sections.some(s => s.para === 2) ? html`<button className="btn ghost small" onClick=${() => update(x => ({ ...x, maxPara: 1 }))}>Plan only one paragraph</button>` : null}
    ${a.year === 6 && a.maxPara < 6 ? html`<button className="btn secondary" onClick=${() => update(x => ({ ...x, maxPara: x.maxPara + 1 }))}>+ Add a paragraph group</button>` : null}
    ${a.year === 6 && a.maxPara > 2 && !a.sections.some(s => s.para === a.maxPara) ? html`<button className="btn ghost small" onClick=${() => update(x => ({ ...x, maxPara: x.maxPara - 1 }))}>Remove empty paragraph ${a.maxPara}</button>` : null}
    <${NavRow} back=${back} backLabel="Back to Explore" next=${next} nextLabel="Next: Write" />
    ${dragging ? ReactDOM.createPortal(html`<div className="dropdock" aria-hidden="true">
      <span className="dockhint">Drop on a box below, or keep dragging towards the bottom of the screen to scroll</span>
      <div className="dockzones">${[{ id: null, label: "Idea tray" }, ...a.sections.map(s => ({ id: s.id, label: s.label }))].map(z => html`<div key=${z.id || "tray"} className=${"dockzone" + (over === (z.id || "tray") ? " over" : "")} ...${zone(z.id)}>${z.label}</div>`)}</div>
    </div>`, document.body) : null}
  </div>`;
}

/* ---- Write ---- */
function PlanSummary({ a }) {
  const groups = a.year === 4 ? [1] : Array.from({ length: a.maxPara }, (_, i) => i + 1);
  const any = a.cards.some(c => c.section);
  return html`<div className="plansum">${!any ? html`<p className="small muted">Your plan is empty. You can still write, or go back to organise.</p>` : null}
    ${groups.map(g => { const secs = a.sections.filter(s => a.year === 4 || s.para === g); return html`<div key=${g} className="stack-xs">
      ${a.year > 4 && secs.length ? html`<p className="eyebrow">Paragraph ${g}</p>` : null}
      ${secs.map(s => { const cs = a.cards.filter(c => c.section === s.id); return html`<div key=${s.id} className="psum"><h4>${s.label}</h4>
        ${cs.length ? html`<ul>${cs.map(c => html`<li key=${c.id}>${c.text}</li>`)}</ul>` : html`<p className="small muted">No cards yet.</p>`}</div>`; })}</div>`; })}
  </div>`;
}

const SIZES = [1, 1.15, 1.32, 1.5];
function Write({ a, update, toPlan, toReview, saveNow, save, prefs, setPrefs, setLevel }) {
  const t = TOPIC[a.topicId], y = yearOf(a.year), lv = a.level;
  const ref = useRef(null);
  const wide = useMemo(() => window.matchMedia("(min-width: 1000px)").matches, []);
  const [more, setMore] = useState(false), [hint, setHint] = useState(lv === "easy"), [ins, setIns] = useState("");
  const [focus, setFocus] = useState(false), [speaking, setSpeaking] = useState(false);
  const canSpeak = "speechSynthesis" in window && typeof SpeechSynthesisUtterance !== "undefined";
  const size = prefs.textSize || 0;
  useEffect(() => { if (!focus) return; const k = (e) => { if (e.key === "Escape") setFocus(false); }; document.addEventListener("keydown", k); return () => document.removeEventListener("keydown", k); }, [focus]);
  useEffect(() => () => { if (canSpeak) speechSynthesis.cancel(); }, []);
  const speak = () => {
    if (!canSpeak) return;
    if (speaking) { speechSynthesis.cancel(); setSpeaking(false); return; }
    const text = [a.title, a.draft].filter(s => s && s.trim()).join(". ");
    if (!text.trim()) { setIns("There is no writing to read aloud yet."); return; }
    const u = new SpeechSynthesisUtterance(text); u.lang = "en-GB"; u.rate = 0.92;
    const v = speechSynthesis.getVoices().find(v => /en-GB/i.test(v.lang)); if (v) u.voice = v;
    u.onend = () => setSpeaking(false); u.onerror = () => { setSpeaking(false); setIns("Read aloud stopped. Your browser may not support it here."); };
    speechSynthesis.speak(u); setSpeaking(true);
  };
  const insert = (str) => {
    const el = ref.current, v = a.draft, s = el ? el.selectionStart : v.length;
    const before = v.slice(0, s), after = v.slice(s);
    let piece = str.replace(/…$/, "");
    if (before && !/\s$/.test(before)) piece = " " + piece;
    if (!/\s$/.test(piece) && !/^\s/.test(after)) piece = piece + " ";
    update(x => ({ ...x, draft: before + piece + after }));
    setIns(`Added “${str.replace(/…$/, "")}” where your cursor was.`);
    requestAnimationFrame(() => { if (el) { el.focus(); const p = s + piece.length; el.setSelectionRange(p, p); } });
  };
  const wc = words(a.draft), pc = paras(a.draft);
  const showStarters = lv === "easy" || (lv === "medium" && more);
  const chipList = (arr) => html`<div className="chiprow">${arr.map(w => html`<button key=${w} className="wordchip" onClick=${() => insert(w)} aria-label=${"Add " + w + " at the cursor"}>${w}</button>`)}</div>`;
  return html`<div className=${"stack" + (focus ? " focusmode" : "")}>
    ${!focus ? html`<div className="stack-s"><h1 tabIndex="-1">Turn your ideas into writing</h1><p className="task"><strong>Task:</strong> ${t.task}</p></div>` : html`<h1 tabIndex="-1" className="sr">Focus mode: writing</h1>`}
    <div className="write-grid">
      ${!focus ? html`<details className="side frame plan-side" open=${wide}><summary>My plan</summary>
        ${lv === "easy" ? html`<span className="qframe side-pic"><${Scene} id=${t.scene} alt=${t.alt} /></span>` : null}
        <${PlanSummary} a=${a} /></details>` : null}
      <div className="parchment" style=${{ "--fs": SIZES[size] }}>
        <div className="ptools row wrap gap-s end">
          <span className="small strong ink">${wc} word${wc === 1 ? "" : "s"} · ${pc} paragraph${pc === 1 ? "" : "s"} (goal: ${y.goalText}) <span className="sr">(word count is for information only)</span></span>
          <div className="row gap-s" role="group" aria-label="Text size">
            <button className="ptool" onClick=${() => setPrefs({ ...prefs, textSize: Math.max(0, size - 1) })} disabled=${size === 0} aria-label="Smaller text">A−</button>
            <button className="ptool" onClick=${() => setPrefs({ ...prefs, textSize: Math.min(SIZES.length - 1, size + 1) })} disabled=${size === SIZES.length - 1} aria-label="Larger text">A+</button></div>
          ${canSpeak ? html`<button className="ptool" onClick=${speak} aria-pressed=${speaking}>${speaking ? "■ Stop reading" : "🔊 Read aloud"}</button>` : null}
          <button className="ptool" onClick=${() => setFocus(!focus)} aria-pressed=${focus}>${focus ? "Exit focus mode" : "⛶ Focus mode"}</button>
        </div>
        <label htmlFor="title-input" className="sr">Title</label>
        <input id="title-input" className="ptitle-input" value=${a.title} onChange=${e => update(x => ({ ...x, title: e.target.value }))} />
        <label htmlFor="draft" className="small ink strong">My writing <span className="ink-muted">(press Enter to start a new paragraph)</span></label>
        <textarea id="draft" ref=${ref} className="draft" value=${a.draft} spellCheck="true" lang="en-GB" onChange=${e => update(x => ({ ...x, draft: e.target.value }))} placeholder="Start writing in your own words…"></textarea>
        <p className="small ink hintnote" role="status">${ins}</p>
        <div className="hintbar">
          <button className="hinttoggle" aria-expanded=${hint} onClick=${() => setHint(!hint)}>? ${hint ? "Hide hints" : "Need a hint?"} <span aria-hidden="true">${hint ? "▴" : "▾"}</span></button>
          ${hint ? html`<div className="hintbody stack-s">
            ${lv === "hard" ? html`<${React.Fragment}><p className="small"><strong>Goal:</strong> ${t.goal}</p><p className="small"><strong>Challenge (optional):</strong> ${t.challenges.join(" ")}</p>
              <h4>Linking words</h4>${chipList(t.linking)}<h4>Think about</h4><ul className="small">${t.questions.slice(2, 5).map(q => html`<li key=${q}>${q}</li>`)}</ul><//>`
            : html`<${React.Fragment}><h4>Linking words</h4><p className="small">Choose one to add it where your cursor is.</p>${chipList(t.linking)}
              ${showStarters ? html`<${React.Fragment}><h4>Sentence starters (optional)</h4><p className="small">These start a sentence. You finish it in your own words.</p>
                <div className="chiprow">${t.starters.map(s => html`<button key=${s} className="wordchip starter" onClick=${() => insert(s)} aria-label=${"Add starter: " + s}>${s}</button>`)}</div><//>`
                : html`<button className="btn small secondary align-start" onClick=${() => setMore(true)}>Show sentence starters</button>`}
              <p className="small"><strong>Challenge (optional):</strong> ${t.challenges[0]}</p><//>`}
          </div>` : null}
          <div className="supportrow" role="group" aria-label="Support option">${LEVELS.map(l => html`<button key=${l.id} className="supbtn" aria-pressed=${lv === l.id} onClick=${() => setLevel(l.id)}>${lv === l.id ? "✓ " : ""}${l.name}</button>`)}</div>
        </div>
      </div>
    </div>
    <div className="navrow">
      <button className="btn secondary" onClick=${toPlan}><${Arrow} left=${true} /> Back to plan</button>
      <div className="row wrap gap-s end"><${SaveStatus} save=${save} /><button className="btn secondary" onClick=${saveNow}>Save draft</button>
        <button className="btn gold" onClick=${toReview}>Review my writing <${Arrow} /></button></div>
    </div>
  </div>`;
}

/* ---- Review ---- */
function Review({ a, update, toWrite, finish, rewarded, who, notify }) {
  const t = TOPIC[a.topicId];
  const list = checklistFor(t, a.level);
  const qc = useMemo(() => quickChecks(a.draft, a.year, t), [a.draft]);
  const el = eligibility(a);
  const ticked = list.filter(([id]) => a.checks[id]).length;
  const [msg, setMsg] = useState("");
  const base = `idea2write-year${a.year}-${slug(t.title)}`;
  const dl = async () => setMsg((await saveFile(base + ".txt", exportText(a, who))).msg);
  const pr = async () => { if (!IN_FRAME) { window.print(); return; } const r = await saveFile(base + "-print.html", printableHTML(a, who)); setMsg(r.ok ? r.msg + " Open it and choose Print to print or save as PDF." : r.msg); };
  const reqs = [[el.planned, "Organise: at least 2 idea cards placed in your planner"], [el.drafted, "Write: at least 20 words of your own writing"], [el.ticked, "Review: tick at least one checklist item"], [el.reflected, "Review: record one improvement you made"]];
  return html`<div className="stack-l">
    <div className="stack-s"><h1 tabIndex="-1">Look how far you have come!</h1><p className="lead">Read your writing again. Tick each item when you have checked it. You do not need every tick.</p></div>
    <div className="review-grid">
      <section className="parchment small-p stack-s" aria-labelledby="dr-h"><div className="row between wrap"><h2 id="dr-h" className="ink-title">${a.title || t.title}</h2><button className="btn small secondary" onClick=${toWrite}>Edit my writing</button></div>
        <div className="draftview">${a.draft.trim() ? a.draft.split(/\n+/).filter(l => l.trim()).map((p, i) => html`<p key=${i}>${p}</p>`) : html`<p className="ink-muted">You have not written anything yet.</p>`}</div>
        <p className="small ink-muted">${words(a.draft)} words · ${paras(a.draft)} paragraph(s)</p>
        <div className="row wrap gap-s"><button className="btn small secondary" onClick=${dl}>Download (.txt)</button><button className="btn small secondary" onClick=${pr}>${IN_FRAME ? "Print version (.html)" : "Print"}</button></div>
        <p className="small ink hintnote" role="status">${msg}</p>
      </section>
      <div className="stack">
        <fieldset className="frame panel checklist"><legend className="h3">My checklist (${ticked} of ${list.length})</legend>
          ${list.map(([id, label]) => html`<div key=${id} className="checkrow"><input type="checkbox" id=${"ck-" + id} checked=${!!a.checks[id]} onChange=${e => update(x => ({ ...x, checks: { ...x.checks, [id]: e.target.checked } }))} />
            <label htmlFor=${"ck-" + id}>${label}</label></div>`)}
        </fieldset>
        <details className="panel frame"><summary>Quick checks</summary>
          <p className="small muted">These are simple rules, not marking. They can miss mistakes or point to something that is fine.</p>
          <ul className="qc">${qc.map((q, i) => html`<li key=${i} className=${q.ok ? "ok" : "look"}><span aria-hidden="true">${q.ok ? "✓" : "•"}</span><span><span className="sr">${q.ok ? "Looks fine: " : "To check: "}</span>${q.msg}</span></li>`)}</ul>
        </details>
        <div className="frame panel stack-s"><label htmlFor="reflect" className="h3">One improvement I made</label>
          <p className="small muted">For example: “I added a reason” or “I fixed my capital letters.”</p>
          <textarea id="reflect" className="field" rows="3" value=${a.reflection} onChange=${e => update(x => ({ ...x, reflection: e.target.value }))}></textarea></div>
        <div className="frame panel stack-s"><h2 className="h3">To complete this quest</h2>
          <ul className="reqs">${reqs.map(([ok, l]) => html`<li key=${l} className=${ok ? "ok" : ""}><span aria-hidden="true">${ok ? "✓" : "○"}</span> ${l}<span className="sr">${ok ? " (done)" : " (not yet)"}</span></li>`)}</ul>
          ${a.assignmentId ? html`<p className="small">This is a class quest. After you complete it, you can submit it to your teacher.</p>` : null}
          ${rewarded ? html`<p className="small">You already earned the reward for this quest on ${fmtDS(rewarded.date)}. Finishing again saves your changes but gives no new stars.</p>` : html`<p className="small muted">Completing earns 3 stars and 30 XP. This rewards finishing the writing process, not a mark for writing quality.</p>`}
        </div>
      </div>
    </div>
    <div className="navrow"><button className="btn secondary" onClick=${toWrite}><${Arrow} left=${true} /> Keep improving</button>
      <div className="row wrap end gap-s">${!el.ok ? html`<span className="hintnote" role="status">Finish the steps above to complete the quest.</span>` : null}
      <button className="btn gold" onClick=${finish} disabled=${!el.ok}>${rewarded ? "Save and finish" : "Complete the quest"} <${Arrow} /></button></div></div>
  </div>`;
}

function Done({ a, reveal, rewardRec, editAgain, another, go, who, progress, submitPanel }) {
  const t = TOPIC[a.topicId], lv = levelOf(a.level);
  const [msg, setMsg] = useState("");
  const base = `idea2write-year${a.year}-${slug(t.title)}`;
  const dl = async () => setMsg((await saveFile(base + ".txt", exportText(a, who))).msg);
  const pr = async () => { if (!IN_FRAME) { window.print(); return; } const r = await saveFile(base + "-print.html", printableHTML(a, who)); setMsg(r.ok ? r.msg + " Open it and choose Print to print or save as PDF." : r.msg); };
  const r = reveal && reveal.attemptId === a.id ? reveal.result : null;
  const item = r && r.kind === "new" && r.items[r.items.length - 1];
  return html`<div className="done-grid">
    <article className="parchment stack-s printsheet" id="print-area" aria-labelledby="fin-h">
      <p className="ink-muted small noprint">Year ${a.year} · ${t.title} · Support: ${lv.name}</p>
      <h1 id="fin-h" tabIndex="-1" className="ink-title">${a.title || t.title}</h1>
      <p className="printonly">${who} · Year ${a.year} · ${t.title}</p>
      <div className="draftview">${a.draft.split(/\n+/).filter(l => l.trim()).map((p, i) => html`<p key=${i}>${p}</p>`)}</div>
      <div className="improve"><strong>One improvement I made:</strong> ${a.reflection.trim() || "Not recorded."}</div>
      <div className="row wrap gap-s noprint">
        <button className="btn secondary small" onClick=${editAgain}>Edit again</button>
        <button className="btn secondary small" onClick=${dl}>Download writing (.txt)</button>
        <button className="btn secondary small" onClick=${pr}>${IN_FRAME ? "Print version (.html)" : "Print"}</button>
      </div>
      <p className="small ink hintnote noprint" role="status">${msg}</p>
    </article>
    ${submitPanel ? html`<div className="noprint submit-wrap">${submitPanel}</div>` : null}
    <aside className="frame panel reward stack-s noprint" aria-labelledby="qc-h">
      <${Ribbon} id="qc-h">Quest complete<//>
      <p className="center-text bigline">You turned your ideas into writing!</p>
      ${r && r.kind === "new" ? html`<div className="reveal stack-s center-text">
          <${StarBurst} />
          <div className="starburst" aria-hidden="true">★</div>
          <p className="plus">+3 stars</p><p className="countline"><span className="sr">${r.before.stars} to ${r.after.stars} stars</span><span aria-hidden="true">${r.before.stars} → <strong><${CountUp} from=${r.before.stars} to=${r.after.stars} /></strong> stars · +<${CountUp} from=${0} to=${30} /> XP</span></p>
          ${r.after.level > r.before.level ? html`<p className="note">You reached writing level ${r.after.level}: ${levelTitle(r.after.level)}!</p>` : html`<p className="small">Level ${r.after.level}: ${levelInfo(r.after.xp).into} of 100 XP</p>`}
          ${item ? html`<${React.Fragment}><div className="unlock"><${Collectible} c=${item} unlocked=${true} size="l" /><span className="cushion" aria-hidden="true"></span><p className="plate">${item.name} unlocked</p></div>
            <button className="btn gold" onClick=${() => go("collection")}>View in my collection <${Arrow} /></button><//>` : null}
          ${r.ach.length ? html`<p className="small">New achievement: ${r.ach.map(x => x.name).join(", ")}</p>` : null}
        </div>` : r && r.kind === "duplicate" ? html`<p className="note">This writing matches a quest you already completed, so no new stars were given. Write something new to earn stars.</p>`
        : rewardRec ? html`<p className="center-text">★ 3 stars and 30 XP were earned for this quest on ${fmtDS(rewardRec.date)}.</p>` : html`<p className="small center-text">Your writing is saved.</p>`}
      <p className="small muted center-text"><em>Rewards are for completing the writing process, not marks for writing quality.</em></p>
      <button className="btn secondary" onClick=${another}>Choose another quest</button>
      <button className="btn ghost" onClick=${() => go("home")}>Back to the common room</button>
    </aside>
  </div>`;
}
/* ===== Guide, teacher section, credits, feedback ===== */
function Guide() {
  const steps = [["Create your wizard", "Choose a portrait, a display name (a nickname is fine), a house and your school year. You can edit this later and keep your progress."],
    ["Pick a quest", "Open Quests or the Calendar. Your school year decides which six quests you see."],
    ["Choose your support", "Guide me gives the most help, A little help gives some, and On my own is for independent writing. Change it any time; your work stays."],
    ["Explore", "Look at the picture, answer the guiding questions in your own words and add more ideas. Choose a word in the word bank to see its meaning."],
    ["Organise", "Move your idea cards from the tray into the planner and put them in order."],
    ["Write", "Use your plan on the parchment. Hints, linking words and sentence starters are optional and only appear where your cursor is when you choose them."],
    ["Review", "Tick the checklist, look at the Quick checks and record one improvement. Then complete the quest."],
    ["Collect rewards", "Each completed quest earns 3 stars and 30 XP. Stars unlock items in your collection and never go away."]];
  return html`<div className="stack-l prose">
    <h1 tabIndex="-1">User Guide</h1>
    <ol className="guide">${steps.map(([h, p]) => html`<li key=${h} className="frame"><h2 className="h3">${h}</h2><p>${p}</p></li>`)}</ol>
    <section className="frame panel stack-s"><h2 className="h3">Moving cards without dragging</h2><p>Every card has a <strong>Move to</strong> menu, a <strong>☝ pick up</strong> button (then choose <strong>Place here</strong>) and <strong>↑ ↓</strong> buttons. They all work with a keyboard (Tab, then Enter or Space) and with touch.</p></section>
    <section className="frame panel stack-s"><h2 className="h3">Streaks and rewards</h2><p>A writing day counts when you complete at least one quest. Several quests on the same day count as one day. Days in a row (Malaysia time) build your streak. Missing a day starts the streak again, but your longest streak, stars and collectibles are kept. Opening the app or a calendar date does not count.</p>
      <p>Each quest attempt earns its reward once. Refreshing, reopening or finishing the same quest again does not add more stars. A new attempt that copies earlier writing word for word does not earn stars.</p></section>
    <section className="frame panel stack-s"><h2 className="h3">Practice bars</h2><p>The bars on your profile count the short practice activities you have finished. They show practice, not how good you are at grammar or vocabulary.</p></section>
    <section className="frame panel stack-s"><h2 className="h3">Sharing a device</h2><p>Profiles are local profiles on this browser and device. They are not secure accounts and have no passwords, so anyone using this browser can open them. Clearing browsing data deletes them. Download your writing to keep a copy.</p></section>
  </div>`;
}

function ScheduleEditor({ sched, setSched }) {
  const [year, setYear] = useState(4), [ym, setYm] = useState(klDate().slice(0, 7)), [sel, setSel] = useState(null), [msg, setMsg] = useState("");
  const [y, m] = ym.split("-").map(Number), first = `${ym}-01`, n = new Date(Date.UTC(y, m, 0)).getUTCDate(), lead = weekdayIdx(first);
  const cells = [...Array(lead).fill(null), ...Array.from({ length: n }, (_, i) => `${ym}-${String(i + 1).padStart(2, "0")}`)]; while (cells.length % 7) cells.push(null);
  const shift = (k) => setYm(toDS(new Date(Date.UTC(y, m - 1 + k, 1))).slice(0, 7));
  const setDay = (ds, v) => { const next = JSON.parse(JSON.stringify(sched)); next[year] = next[year] || {}; if (v === "sample") delete next[year][ds]; else next[year][ds] = v; setMsg(setSched(next) ? "Schedule saved on this device." : "Saving is unavailable, so this change lasts only until the page closes."); };
  const resetMonth = () => { const next = JSON.parse(JSON.stringify(sched)); Object.keys(next[year] || {}).forEach(ds => { if (ds.startsWith(ym)) delete next[year][ds]; }); setSched(next); setMsg("This month now follows the sample schedule again."); };
  const list = TOPICS.filter(t => t.year === year);
  return html`<div className="stack">
    <p>Choose a date to set its quest. Dates you have not changed follow the sample schedule, which rotates the six topics for that year on school days. Pupils see changes in their Quest calendar on this device.</p>
    <div className="row wrap gap-s"><label htmlFor="se-year">School year</label><select id="se-year" className="field small sel" value=${year} onChange=${e => { setYear(+e.target.value); setSel(null); }}>${YEARS.map(x => html`<option key=${x.id} value=${x.id}>${x.label}</option>`)}</select>
      <button className="btn secondary small" onClick=${() => shift(-1)}>Previous month</button><strong>${parseDS(first).toLocaleDateString("en-GB", { month: "long", year: "numeric", timeZone: "UTC" })}</strong><button className="btn secondary small" onClick=${() => shift(1)}>Next month</button>
      <button className="btn ghost small" onClick=${resetMonth}>Reset month to sample</button></div>
    <div className="calwrap"><table className="cal small-cal"><thead><tr>${["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map(d => html`<th key=${d} scope="col">${d}</th>`)}</tr></thead>
      <tbody>${Array.from({ length: cells.length / 7 }, (_, r) => html`<tr key=${r}>${cells.slice(r * 7, r * 7 + 7).map((ds, i) => { if (!ds) return html`<td key=${i} className="blank"></td>`; const s = scheduleFor(sched, year, ds);
        return html`<td key=${ds}><button className=${"day has" + (sel === ds ? " selected" : "")} aria-pressed=${sel === ds} onClick=${() => setSel(ds)}><span className="dnum">${+ds.slice(8)}</span><span className="dtopic">${s.topicId ? TOPIC[s.topicId].title : "No quest"}</span>${s.source === "teacher" ? html`<span className="tset">set</span>` : null}</button></td>`; })}</tr>`)}</tbody></table></div>
    ${sel ? html`<div className="parchment-card row wrap gap-s"><label htmlFor="se-topic" className="strong">${fmtDS(sel)}</label>
      <select id="se-topic" className="field small sel" value=${(sched[year] && sched[year][sel]) || "sample"} onChange=${e => setDay(sel, e.target.value)}>
        <option value="sample">Use sample schedule (${(sampleTopic(year, sel) && TOPIC[sampleTopic(year, sel)].title) || "no quest"})</option>
        <option value="none">No quest on this day</option>
        ${list.map(t => html`<option key=${t.id} value=${t.id}>${t.title}</option>`)}</select></div>` : null}
    <p className="hintnote" role="status">${msg}</p>
  </div>`;
}

function ArtworkEditor({ art, setArt }) {
  const [msg, setMsg] = useState("");
  const onFile = (e) => {
    const f = e.target.files && e.target.files[0]; if (!f) return;
    if (!/^image\//.test(f.type)) { setMsg("Please choose an image file (JPEG or PNG)."); return; }
    const r = new FileReader();
    r.onload = () => { const img = new Image(); img.onload = () => {
      const scale = Math.min(1, 1600 / img.width), c = document.createElement("canvas"); c.width = Math.round(img.width * scale); c.height = Math.round(img.height * scale);
      c.getContext("2d").drawImage(img, 0, 0, c.width, c.height); const url = c.toDataURL("image/jpeg", 0.8);
      setMsg(setArt(url) ? "Background saved on this device." : "This image is too large to save in this browser. It shows until the page closes.");
    }; img.onerror = () => setMsg("That image could not be opened."); img.src = r.result; };
    r.readAsDataURL(f);
  };
  return html`<div className="stack-s">
    <p>The castle backdrop uses artwork cropped from the site author's design boards. You can replace it with your own higher-resolution image. It is resized and saved only in this browser.</p>
    <div className="row wrap gap-s"><label className="btn secondary small" htmlFor="art-file">Choose background image</label><input id="art-file" type="file" accept="image/*" className="sr" onChange=${onFile} />
      ${art ? html`<button className="btn ghost small" onClick=${() => { setArt(null); setMsg("Default backdrop restored."); }}>Use default backdrop</button>` : null}</div>
    <p className="hintnote" role="status">${msg}</p>
  </div>`;
}

const DEV_CHECKS = ["Character creation, house changes and editing a character without losing progress",
  "Separate year, house and writing-level state", "Content present for all 18 topics at all three support options (54 paths)",
  "A complete writing journey for Year 4, Year 5 and Year 6", "Profile isolation and draft persistence after refresh",
  "Practice-bar counts", "Stars, XP, level thresholds and collectible unlocks", "Duplicate-reward prevention on refresh, re-finishing and copied text",
  "Streak boundaries, including same-day completions and missed days", "Calendar weekday alignment, month navigation and scheduled-quest buttons",
  "Phone-width layout, keyboard navigation, text download and the print version", "Behaviour when browser storage is blocked"];

function Teacher({ sched, setSched, art, setArt, index, removeProfile }) {
  const tabs = [["about", "About & UDL"], ["curriculum", "Curriculum"], ["schedule", "Schedule"], ["manual", "User manual"], ["testing", "Testing & feedback"], ["ack", "Acknowledgements"], ["manage", "Profiles & artwork"]];
  const [tab, setTab] = useState("about");
  const fb = loadJSON(K.feedback, []);
  const [imp, setImp] = useState(() => loadJSON(K.improve, [])), [impText, setImpText] = useState(""), [confirm, setConfirm] = useState(null);
  const shots = [["shot_create", "Creating a wizard in four steps: portrait, name, house and year, with a live preview."], ["shot_home", "The common room shows today's quest, streak, stars, level and the next reward."], ["shot_quests", "Quest cards show the objective, task type, status and completion reward."], ["shot_explore", "Explore: answer guiding questions, use the word bank and add ideas."], ["shot_plan", "Organise: move cards with drag, pick-up, the Move menu or ↑ ↓ buttons."], ["shot_write", "Write: the parchment editor with the plan alongside, text size, read aloud and focus mode."], ["shot_done", "Completing a quest reveals the stars, XP and any newly unlocked collectible."], ["shot_profile", "The profile shows level, streaks, practice bars, achievements and the collection cabinet."], ["shot_calendar", "The quest calendar with today and the selected date marked, and a legend."]];
  return html`<div className="stack-l">
    <div className="stack-s"><p className="eyebrow">For teachers</p><h1 tabIndex="-1">Teacher Information</h1></div>
    <div className="tabs" role="tablist" aria-label="Teacher sections">${tabs.map(([id, l]) => html`<button key=${id} role="tab" id=${"tab-" + id} aria-selected=${tab === id} aria-controls=${"tp-" + id} className=${"tab" + (tab === id ? " on" : "")} onClick=${() => setTab(id)}>${l}</button>`)}</div>
    <section className="frame panel stack prose" role="tabpanel" id=${"tp-" + tab} aria-labelledby=${"tab-" + tab}>
      ${tab === "about" ? html`<${React.Fragment}>
        <h2>Innovation purpose</h2><p>Idea2Write turns a process approach to writing (Explore, Organise, Write, Review) into a castle-academy quest. Pupils still write ordinary curriculum tasks in their own words; the fantasy setting, stars and collectibles aim to make starting and finishing a piece of writing feel inviting. The site never writes answers for pupils.</p>
        <h2>Target users</h2><p>Malaysian Sekolah Kebangsaan pupils in Years 4, 5 and 6 who are learning English as a second language, and their teachers.</p>
        <h2>UDL-informed features</h2>
        <ul><li><strong>Multiple means of engagement:</strong> pupils choose a character and house, pick their support option and see completion rewards and streaks. Houses are team identities only and never change the tasks.</li>
          <li><strong>Multiple means of representation:</strong> each quest has a picture prompt with descriptive alternative text, a word bank with meanings, guiding questions and optional read aloud of the pupil's own writing.</li>
          <li><strong>Multiple means of action and expression:</strong> three support options (Guide me, A little help, On my own), movable idea cards with drag, touch and keyboard controls, adjustable text size and focus mode.</li>
          <li><strong>Self-regulation:</strong> the review checklist, Quick checks prompts and the “one improvement I made” reflection.</li>
          <li><strong>Access:</strong> keyboard operation, visible focus, reduced-motion support, sound only when switched on, and layouts for phones, tablets and laptops.</li></ul>
        <h2>Classroom use</h2><ul><li>Individual writing at each pupil's chosen support option.</li><li>Paired work: pupils discuss Explore and Organise together, then each writes their own draft.</li><li>Guided writing: model one quest with the class, then let pupils write independently.</li></ul>
        <p className="note">Stars, XP, levels and practice bars reward completing steps. They are not grades, and they do not show mastery of any learning standard. Teacher judgement is still needed for assessment.</p><//>` : null}
      ${tab === "curriculum" ? html`<${React.Fragment}>
        <h2>Curriculum mapping</h2>
        <p>The standard codes below were supplied by the site author for each activity. They refer to the SK English DSKP for each year. They have not been checked against the DSKP documents inside this website, so please confirm the exact wording in the DSKP before citing them. No other codes have been added.</p>
        <div className="tablewrap"><table><thead><tr><th scope="col">Year</th><th scope="col">Activity</th><th scope="col">Purpose</th><th scope="col">Main standard (as supplied)</th><th scope="col">Supporting standards (as supplied)</th><th scope="col">Paragraph goal</th></tr></thead><tbody>
          ${TOPICS.map(t => html`<tr key=${t.id}><td>${t.year}</td><td><strong>${t.title}</strong><br /><span className="small">${t.task}</span></td><td>${t.purpose}</td><td>${t.std.join(", ")}</td><td>${SUPPORT_STD.join(", ")}</td><td>${yearOf(t.year).goalText}</td></tr>`)}
        </tbody></table></div>
        <h3 className="h3">What each code is used for in this site (summary, not DSKP wording)</h3><ul className="small">${Object.entries(STD_NOTES).map(([k, v]) => html`<li key=${k}><strong>${k}</strong>: ${v}</li>`)}</ul>
        <h3 className="h3">How support differs</h3>
        <div className="tablewrap"><table><thead><tr><th scope="col">Support</th><th scope="col">Guide me</th><th scope="col">A little help</th><th scope="col">On my own</th></tr></thead><tbody>
          <tr><th scope="row">Guiding questions</th><td>All shown with answer boxes</td><td>Four shown, more on request</td><td>Writing goal; questions on request</td></tr>
          <tr><th scope="row">Word bank</th><td>10 words with meanings</td><td>6 words, optional</td><td>A short word list, optional</td></tr>
          <tr><th scope="row">Planner</th><td>Topic sections with hints</td><td>Topic sections, hints on request</td><td>Open paragraph groups</td></tr>
          <tr><th scope="row">Sentence starters</th><td>Shown in hints, optional</td><td>On request</td><td>Not offered</td></tr>
          <tr><th scope="row">Checklist</th><td>General and topic checks</td><td>Adds linking words</td><td>Clarity, organisation, detail and language</td></tr></tbody></table></div><//>` : null}
      ${tab === "schedule" ? html`<${React.Fragment}><h2>Edit the quest schedule</h2><${ScheduleEditor} sched=${sched} setSched=${setSched} /><//>` : null}
      ${tab === "manual" ? html`<${React.Fragment}><h2>Illustrated user manual</h2><p>These screenshots were captured from this website during development, using a test profile. Fonts in the screenshots may look slightly different from your screen.</p>
        <ol className="manual">${shots.map(([k, cap], i) => html`<li key=${k} className="frame panel stack-s">${IMG[k] ? html`<img src=${IMG[k]} alt=${"Screenshot: " + cap} />` : html`<p className="muted">Screenshot not available.</p>`}<p><strong>${i + 1}.</strong> ${cap}</p></li>`)}</ol><//>` : null}
      ${tab === "testing" ? html`<${React.Fragment}>
        <h2>Feedback collected on this device</h2>
        ${fb.length ? html`<p>${fb.length} response${fb.length > 1 ? "s" : ""} saved here. Ease of use: ${["Easy to use", "Quite easy", "Hard to use"].map(e => `${e} ${fb.filter(f => f.ease === e).length}`).join(" · ")}.</p>
          <ul className="small">${fb.filter(f => f.improve).slice(-8).map((f, i) => html`<li key=${i}>“${f.improve}” <span className="muted">(${f.role || "no role given"}, ${f.date.slice(0, 10)})</span></li>`)}</ul>`
          : html`<p>No feedback has been saved on this device yet. Pupils and teachers can use the Feedback page. Results appear here after real testing.</p>`}
        <h2>Improvements made after testing</h2>
        <p className="small muted">Record real changes you made in response to feedback. Saved only on this device.</p>
        ${imp.length ? html`<ul>${imp.map((x, i) => html`<li key=${i}>${x.text} <span className="small muted">(${x.date})</span> <button className="linkbtn small danger" onClick=${() => { const n = imp.filter((_, j) => j !== i); setImp(n); saveJSON(K.improve, n); }}>Remove</button></li>`)}</ul>` : html`<p className="muted">None recorded yet.</p>`}
        <div className="row gap-s addrow"><label htmlFor="imp-in" className="sr">Improvement</label><input id="imp-in" className="field" value=${impText} onChange=${e => setImpText(e.target.value)} placeholder="For example: made the word bank open by default" />
          <button className="btn gold small" onClick=${() => { if (!impText.trim()) return; const n = [...imp, { text: impText.trim(), date: klDate() }]; setImp(n); saveJSON(K.improve, n); setImpText(""); }}>Add</button></div>
        <h2>Developer checks</h2><p>These behaviours were checked with an automated browser script during development on 4 November 2026. They are functional checks of the website, not research results or learning outcomes.</p>
        <ul className="small">${DEV_CHECKS.map(c => html`<li key=${c}>${c}</li>`)}</ul><//>` : null}
      ${tab === "ack" ? html`<${React.Fragment}><h2>Acknowledgements</h2>
        <ul><li><strong>Artwork:</strong> the pupil portraits, castle skyline, fireplace, candles, windows and collectible photographs are cropped from design boards supplied by the site author. The four houses, crests and the academy are original to Idea2Write and are not connected to any book or film series.</li>
          <li><strong>Illustrations:</strong> the quest picture prompts, crests, banners and icons were drawn in code for this website.</li>
          <li><strong>Sound:</strong> the optional fireside ambience is generated in the browser; no audio recordings are used.</li>
          <li><strong>Fonts:</strong> Cinzel, Cormorant Garamond and Source Sans 3 from Google Fonts (SIL Open Font License).</li>
          <li><strong>Software:</strong> React (MIT License) and htm (Apache License 2.0).</li>
          <li><strong>AI tool:</strong> the website code and written activity content were produced with help from Claude, an AI assistant made by Anthropic, under the site author's direction.</li>
          <li><strong>Curriculum:</strong> standard codes refer to the KSSR English Language DSKP for SK Year 4, Year 5 and Year 6 (Ministry of Education Malaysia), as supplied by the site author.</li></ul><//>` : null}
      ${tab === "manage" ? html`<${React.Fragment}><h2>Local profiles on this browser</h2><p>Profiles are not accounts. They have no passwords and exist only in this browser.</p>
        ${index.profiles.length ? html`<ul className="drafts">${index.profiles.map(p => html`<li key=${p.id} className="row wrap between gap-s"><span className="row gap-s"><${Portrait} id=${p.portrait} size="xs" house=${p.house} alt="" /> ${p.name} · ${HOUSE[p.house].name} · Year ${p.year}</span>
          ${confirm === p.id ? html`<span className="row gap-s confirm"><span className="small">Delete ${p.name} and all their writing and rewards?</span><button className="btn small danger-btn" onClick=${() => { removeProfile(p.id); setConfirm(null); }}>Yes, delete</button><button className="btn small secondary" onClick=${() => setConfirm(null)}>Keep</button></span>`
            : html`<button className="btn ghost small danger" onClick=${() => setConfirm(p.id)}>Delete profile</button>`}</li>`)}</ul>` : html`<p className="muted">No profiles yet.</p>`}
        <h2>Academy artwork</h2><${ArtworkEditor} art=${art} setArt=${setArt} /><//>` : null}
    </section>
  </div>`;
}

function Credits() {
  return html`<div className="stack-l prose"><h1 tabIndex="-1">Credits</h1>
    <section className="frame panel stack-s"><h2 className="h3">Artwork</h2><p>Portraits, the castle skyline, fireplace, candles, windows and collectible photographs come from design boards supplied by the site author. Quest pictures, crests and icons were drawn in code. The academy and its four houses are original.</p></section>
    <section className="frame panel stack-s"><h2 className="h3">Curriculum</h2><p>Standard codes refer to the SK English DSKP for Year 4, Year 5 and Year 6 (Ministry of Education Malaysia), as supplied by the site author. The activities are original.</p></section>
    <section className="frame panel stack-s"><h2 className="h3">Fonts, software and tools</h2><ul><li>Cinzel, Cormorant Garamond and Source Sans 3 (Google Fonts, SIL Open Font License).</li><li>React (MIT) and htm (Apache 2.0).</li><li>Built with help from Claude, an AI assistant by Anthropic.</li></ul></section>
  </div>`;
}

function Feedback() {
  const [list, setList] = useState(() => loadJSON(K.feedback, []));
  const [f, setF] = useState({ role: "", ease: "", helpful: [], improve: "" });
  const [msg, setMsg] = useState(""), [confirm, setConfirm] = useState(false);
  const feats = ["Character and houses", "Pictures", "Word bank", "Guiding questions", "Idea cards", "Hints", "Read aloud", "Checklist", "Stars and collection", "Calendar", "Practice"];
  const submit = () => {
    if (!f.ease && !f.helpful.length && !f.improve.trim()) { setMsg("Please answer at least one question before saving."); return; }
    const next = [...list, { ...f, improve: f.improve.trim(), date: new Date().toISOString() }];
    setList(next);
    setMsg(saveJSON(K.feedback, next) ? "Thank you. Your feedback is saved on this device. It has not been sent to anyone." : "Saving is unavailable in this browser, so this feedback is kept only until you close the page. You can still export it now.");
    setF({ role: "", ease: "", helpful: [], improve: "" });
  };
  const exportCsv = async () => {
    const q = (s) => '"' + String(s).replace(/"/g, '""') + '"';
    const rows = [["Date", "Role", "Ease of use", "Helpful features", "Suggested improvements"], ...list.map(r => [r.date, r.role, r.ease, r.helpful.join("; "), r.improve])];
    setMsg((await saveFile("idea2write-feedback.csv", rows.map(r => r.map(q).join(",")).join("\r\n"))).msg);
  };
  return html`<div className="stack-l prose"><h1 tabIndex="-1">Feedback</h1>
    <p className="note">Feedback is optional. It is saved only on this device and is <strong>not</strong> sent to a teacher or a server. Do not write your name or contact details.</p>
    <div className="frame panel stack" role="form" aria-label="Feedback form">
      <fieldset><legend className="h3">I am a… (optional)</legend><div className="row wrap gap-s">${["Pupil", "Teacher", "Other"].map(r => html`<label key=${r} className="opt"><input type="radio" name="role" id=${"role-" + r} checked=${f.role === r} onChange=${() => setF({ ...f, role: r })} /> ${r}</label>`)}</div></fieldset>
      <fieldset><legend className="h3">How easy was Idea2Write to use?</legend><div className="row wrap gap-s">${["Easy to use", "Quite easy", "Hard to use"].map(r => html`<label key=${r} className="opt"><input type="radio" name="ease" id=${"ease-" + slug(r)} checked=${f.ease === r} onChange=${() => setF({ ...f, ease: r })} /> ${r}</label>`)}</div></fieldset>
      <fieldset><legend className="h3">Which features helped you?</legend><div className="row wrap gap-s">${feats.map(r => html`<label key=${r} className="opt"><input type="checkbox" id=${"feat-" + slug(r)} checked=${f.helpful.includes(r)} onChange=${e => setF({ ...f, helpful: e.target.checked ? [...f.helpful, r] : f.helpful.filter(x => x !== r) })} /> ${r}</label>`)}</div></fieldset>
      <div className="stack-xs"><label htmlFor="fb-improve" className="h3">What could be better?</label><textarea id="fb-improve" className="field" rows="4" value=${f.improve} onChange=${e => setF({ ...f, improve: e.target.value })}></textarea></div>
      <div><button type="button" className="btn gold" onClick=${submit}>Save feedback on this device</button></div>
      <p className="hintnote" role="status">${msg}</p>
    </div>
    <section className="frame panel stack-s"><h2 className="h3">Saved feedback on this device: ${list.length}</h2>
      <div className="row wrap gap-s"><button className="btn secondary" onClick=${exportCsv} disabled=${!list.length}>Export feedback (.csv)</button>
        ${confirm ? html`<span className="small">Delete all saved feedback?</span><button className="btn small danger-btn" onClick=${() => { setList([]); saveJSON(K.feedback, []); setConfirm(false); setMsg("All saved feedback was deleted from this device."); }}>Yes, delete all</button><button className="btn small secondary" onClick=${() => setConfirm(false)}>Keep it</button>`
        : html`<button className="btn ghost danger" onClick=${() => setConfirm(true)} disabled=${!list.length}>Delete all feedback</button>`}</div></section>
  </div>`;
}
/* ===== Online accounts: Supabase connection and data layer =====
   The browser only ever holds the public "anon" key. Every privileged action
   (joining a class, saving drafts, rewards, submitting, feedback) runs in a
   database function that checks the signed-in user and role on the server. */
const CLOUD_CFG = (window.IDEA2WRITE_CONFIG && window.IDEA2WRITE_CONFIG.supabaseUrl && window.IDEA2WRITE_CONFIG.supabaseAnonKey) ? window.IDEA2WRITE_CONFIG : null;

/* Thin adapter: the rest of the app talks to `db` and `authApi`, never to supabase-js directly. */
function makeSupabaseBackend(cfg) {
  if (!window.supabase || !window.supabase.createClient) return null;
  const sb = window.supabase.createClient(cfg.supabaseUrl, cfg.supabaseAnonKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true, storageKey: "i2w-auth" } });
  const wrap = async (p) => { const { data, error } = await p; if (error) throw normaliseError(error); return data; };
  const applyEq = (q, eq) => { Object.entries(eq || {}).forEach(([k, v]) => { q = v === null ? q.is(k, null) : q.eq(k, v); }); return q; };
  const db = {
    rpc: (name, args) => wrap(sb.rpc(name, args || {})),
    select: (table, opts = {}) => { let q = applyEq(sb.from(table).select(opts.cols || "*"), opts.eq); if (opts.in) Object.entries(opts.in).forEach(([k, v]) => { q = q.in(k, v); }); if (opts.order) q = q.order(opts.order, { ascending: !opts.desc }); return wrap(opts.single ? q.maybeSingle() : q); },
    insert: (table, row) => wrap(sb.from(table).insert(row).select().single()),
    update: (table, patch, eq) => wrap(applyEq(sb.from(table).update(patch), eq).select()),
    upsert: (table, row) => wrap(sb.from(table).upsert(row).select().single()),
    remove: (table, eq) => wrap(applyEq(sb.from(table).delete(), eq))
  };
  const authApi = {
    getSession: async () => (await sb.auth.getSession()).data.session,
    onChange: (fn) => sb.auth.onAuthStateChange((event, session) => fn(event, session)).data.subscription,
    signIn: (email, password) => wrap(sb.auth.signInWithPassword({ email, password })),
    signUp: (email, password, meta) => wrap(sb.auth.signUp({ email, password, options: { data: meta, emailRedirectTo: cfg.siteUrl || location.origin + location.pathname } })),
    signOut: () => sb.auth.signOut(),
    resetPassword: (email) => wrap(sb.auth.resetPasswordForEmail(email, { redirectTo: cfg.siteUrl || location.origin + location.pathname })),
    updatePassword: (password) => wrap(sb.auth.updateUser({ password }))
  };
  return { db, authApi };
}
function normaliseError(e) {
  const msg = (e && (e.message || e.error_description || e.msg)) || String(e);
  const err = new Error(msg); err.code = e && e.code; err.status = e && e.status;
  err.network = /Failed to fetch|NetworkError|Load failed|fetch failed|network/i.test(msg) || e.status === 0;
  return err;
}
const BACKEND = (() => { try { if (window.__I2W_TEST_BACKEND) return window.__I2W_TEST_BACKEND; return CLOUD_CFG ? makeSupabaseBackend(CLOUD_CFG) : null; } catch (e) { return null; } })();

function friendlyAuthError(e) {
  const m = (e && e.message) || "";
  if (/invalid login credentials/i.test(m)) return "That email and password do not match an account. Check them and try again.";
  if (/email not confirmed/i.test(m)) return "Please confirm your email first. Open the link we sent to your inbox.";
  if (/teacher_code_invalid|Database error saving new user/i.test(m)) return "The teacher registration code is not correct. Ask your school's site administrator for it.";
  if (/already registered|already exists/i.test(m)) return "An account with this email already exists. Try signing in, or reset your password.";
  if (/password.*(6|characters|short)/i.test(m)) return "Please use a longer password (at least 8 characters).";
  if (/rate limit|too many/i.test(m)) return "Too many attempts. Please wait a few minutes and try again.";
  if (e && e.network) return "Cannot reach the academy server. Check your internet connection and try again.";
  return "Something went wrong: " + m;
}

/* ---------- Student data layer: drafts with conflict detection and local recovery ---------- */
function makeStudentCloud(uid, onStatus) {
  const db = BACKEND.db;
  const recKey = `i2w.cloud.${uid}.recovery`;
  const versions = {};        // client_id -> last server version this device knows
  const inflight = {}, queued = {};
  const readRec = () => loadJSON(recKey, {});
  const writeRec = (r) => saveJSON(recKey, r);
  const strip = (a) => { const { _local, ...rest } = a; return rest; };
  let retryTimer = null;

  async function loadAll() {
    const [wiz, drafts, progress, classes, subs] = await Promise.all([
      db.select("wizard_profiles", { eq: { user_id: uid }, single: true }),
      db.select("drafts", { cols: "client_id,data,version,updated_at,assignment_id,imported,completed", eq: { student_id: uid } }),
      db.rpc("my_progress"), db.rpc("my_classes"),
      db.select("submissions", { cols: "id,assignment_id,revision,title,writing,plan,reflection,submitted_at,activity_title,school_year,feedback(id,comments,strengths,next_steps,decision,rubric,created_at)", eq: { student_id: uid }, order: "submitted_at" })
    ]);
    const attempts = {};
    (drafts || []).forEach(d => { versions[d.client_id] = d.version; attempts[d.client_id] = { ...d.data, id: d.client_id, assignmentId: d.assignment_id || null, imported: d.imported || d.data.imported || false, updated: d.data.updated || Date.parse(d.updated_at) }; });
    return { wizard: wiz, attempts, progress: { ...emptyProgress(), ...progress }, classes: classes || [], submissions: subs || [], recovery: pendingRecovery(attempts) };
  }
  /* Unsynced copies kept on this device from an earlier session */
  function pendingRecovery(attempts) {
    const rec = readRec(), out = [];
    Object.entries(rec).forEach(([id, r]) => {
      if (r.synced) return;
      const server = attempts[id];
      const serverV = versions[id] || 0;
      out.push({ id, local: r.data, base: r.base, serverVersion: serverV, server, sameBase: r.base === serverV });
    });
    return out;
  }
  async function saveNow(a) {
    const id = a.id, base = versions[id] || 0;
    const rec = readRec(); rec[id] = { data: strip(a), base, savedAt: Date.now(), synced: false };
    const localOk = writeRec(rec);
    try {
      const r = await db.rpc("save_draft", { p_client_id: id, p_base_version: base, p_topic: a.topicId, p_assignment: a.assignmentId || null, p_data: strip(a) });
      if (r.status === "saved") { versions[id] = r.version; const rr = readRec(); delete rr[id]; writeRec(rr); return { state: "online", version: r.version }; }
      if (r.status === "conflict") return { state: "conflict", server: { data: r.data, version: r.version, updated_at: r.updated_at } };
      if (r.status === "missing") return { state: "missing" };
      return { state: "error", message: r.error };
    } catch (e) {
      if (e.network) { scheduleRetry(); return { state: localOk ? "local" : "error", message: e.message }; }
      return { state: "error", message: e.message };
    }
  }
  /* One save at a time per attempt; the latest state wins the next turn */
  function save(a) {
    const id = a.id;
    if (inflight[id]) { queued[id] = a; return inflight[id]; }
    const run = async (x) => {
      onStatus && onStatus({ state: "saving" });
      const r = await saveNow(x);
      onStatus && onStatus(r);
      if (queued[id] && r.state === "online") { const nx = queued[id]; delete queued[id]; return run(nx); }
      delete queued[id];
      return r;
    };
    inflight[id] = run(a).finally(() => { delete inflight[id]; });
    return inflight[id];
  }
  async function flush(a) { if (inflight[a.id]) { queued[a.id] = a; await inflight[a.id]; } return save(a); }
  function scheduleRetry() {
    if (retryTimer) return;
    retryTimer = setTimeout(async () => { retryTimer = null; const rec = readRec(); for (const [id, r] of Object.entries(rec)) { if (!r.synced && r.base === (versions[id] || 0)) await save({ ...r.data, id }); } }, 15000);
  }
  window.addEventListener("online", () => { const rec = readRec(); Object.entries(rec).forEach(([id, r]) => { if (!r.synced && r.base === (versions[id] || 0)) save({ ...r.data, id }); }); });

  return {
    loadAll, save, flush,
    hasUnsynced: () => Object.values(readRec()).some(r => !r.synced),
    discardRecovery: (id) => { const r = readRec(); delete r[id]; writeRec(r); },
    clearRecovery: () => { try { localStorage.removeItem(recKey); } catch (e) { } },
    acceptServerVersion: (id, version) => { versions[id] = version; const r = readRec(); delete r[id]; writeRec(r); },
    setVersion: (id, v) => { versions[id] = v; },
    deleteDraft: (id) => db.remove("drafts", { student_id: uid, client_id: id }).then(() => { delete versions[id]; const r = readRec(); delete r[id]; writeRec(r); }),
    saveWizard: (f, prefs) => db.upsert("wizard_profiles", { user_id: uid, portrait: f.portrait, wizard_name: f.name, house: f.house, school_year: f.year, prefs: prefs || {} }),
    savePrefs: (prefs) => db.update("wizard_profiles", { prefs }, { user_id: uid }),
    completeQuest: (id) => db.rpc("complete_quest", { p_client_id: id }),
    recordPractice: (key, firstTry, total) => db.rpc("record_practice", { p_key: key, p_first_try: firstTry, p_total: total }),
    progress: () => db.rpc("my_progress"),
    classes: () => db.rpc("my_classes"),
    submissions: () => db.select("submissions", { cols: "id,assignment_id,revision,title,writing,plan,reflection,submitted_at,activity_title,school_year,feedback(id,comments,strengths,next_steps,decision,rubric,created_at)", eq: { student_id: uid }, order: "submitted_at" }),
    previewClass: (code) => db.rpc("preview_class", { p_code: code }),
    joinClass: (code) => db.rpc("join_class", { p_code: code }),
    submit: (id) => db.rpc("submit_assignment", { p_client_id: id }),
    imports: () => db.select("local_imports", { eq: { student_id: uid }, order: "imported_at" }),
    importLocal: (localId, wizard, drafts, summary) => db.rpc("import_local_profile", { p_local_id: localId, p_wizard: wizard, p_drafts: drafts, p_summary: summary })
  };
}

/* ---------- Teacher data layer ---------- */
function makeTeacherApi(uid) {
  const db = BACKEND.db;
  return {
    summary: () => db.rpc("teacher_summary"),
    classes: () => db.select("classes", { eq: { teacher_id: uid }, order: "created_at" }),
    createClass: (name, year) => db.insert("classes", { teacher_id: uid, name, school_year: year }),
    updateClass: (id, patch) => db.update("classes", patch, { id }),
    deleteClass: (id) => db.remove("classes", { id }),
    regenerateCode: (id) => db.rpc("regenerate_class_code", { p_class: id }),
    overview: (id) => db.rpc("class_overview", { p_class: id }),
    setMembership: (mid, status) => db.rpc("set_membership_status", { p_membership: mid, p_status: status }),
    assignments: (classId) => db.select("assignments", { eq: { class_id: classId }, order: "created_at", desc: true }),
    createAssignment: (classId, topicId, instructions, due) => db.insert("assignments", { class_id: classId, topic_id: topicId, instructions, due_date: due || null, created_by: uid }),
    updateAssignment: (id, patch) => db.update("assignments", patch, { id }),
    assignmentOverview: (id) => db.rpc("assignment_overview", { p_assignment: id }),
    submissionsFor: (assignmentId, studentId) => db.select("submissions", { cols: "*,feedback(*)", eq: { assignment_id: assignmentId, student_id: studentId }, order: "revision" }),
    giveFeedback: (subId, f) => db.rpc("give_feedback", { p_submission: subId, p_comments: f.comments, p_strengths: f.strengths, p_next_steps: f.next_steps, p_decision: f.decision, p_rubric: f.rubric }),
    profile: () => db.select("account_profiles", { eq: { id: uid }, single: true }),
    updateProfile: (patch) => db.update("account_profiles", patch, { id: uid })
  };
}

const WORK_LABEL = { not_started: "Not started", in_progress: "In progress", submitted: "Submitted", revision_requested: "Revision requested", resubmitted: "Resubmitted", reviewed: "Reviewed" };
const RUBRIC = [["vocabulary", "Vocabulary"], ["grammar", "Grammar"], ["organisation", "Organisation"], ["sentence_structure", "Sentence structure"]];
const RUBRIC_LEVELS = { 1: "Beginning", 2: "Developing", 3: "Secure", 4: "Strong" };
/* ===== Accounts: entrance gate, sign-in, registration, password recovery ===== */
function Gate({ onDemo, onAuth, configured, notice }) {
  return html`<div className="stack-l narrow">
    <div className="stack-s center-text"><p className="eyebrow">Idea2Write Writing Academy</p><h1 tabIndex="-1">Enter the academy</h1>
      <p className="lead">Sign in to save your writing online, join your class and receive your teacher's notes.</p></div>
    ${notice ? html`<p className="note" role="status">${notice}</p>` : null}
    ${!configured ? html`<p className="note">Online accounts are not connected on this copy of the website, so only demo mode is available here. A teacher or site owner can connect accounts by following the setup guide.</p>` : null}
    <div className="gate-grid">
      <section className="frame panel stack-s gatecard" aria-labelledby="g-pupil">
        <span className="gate-art" aria-hidden="true" style=${{ backgroundImage: `url(${IMG.castle})` }}></span>
        <h2 id="g-pupil" className="h3">I am a pupil</h2>
        <p className="small">Use the email account your school gave you (for example your DELIMa account) and your own password.</p>
        <div className="row wrap gap-s"><button className="btn gold" disabled=${!configured} onClick=${() => onAuth("student", "signin")}>Pupil sign in</button>
          <button className="btn secondary" disabled=${!configured} onClick=${() => onAuth("student", "signup")}>Create pupil account</button></div>
      </section>
      <section className="frame panel stack-s gatecard" aria-labelledby="g-teacher">
        <span className="gate-art" aria-hidden="true" style=${{ backgroundImage: `url(${IMG.candles})`, backgroundPosition: "center 30%" }}></span>
        <h2 id="g-teacher" className="h3">I am a teacher</h2>
        <p className="small">Open the Professor's Dashboard to create classes, assign quests and give feedback.</p>
        <div className="row wrap gap-s"><button className="btn gold" disabled=${!configured} onClick=${() => onAuth("teacher", "signin")}>Teacher sign in</button>
          <button className="btn secondary" disabled=${!configured} onClick=${() => onAuth("teacher", "signup")}>Create teacher account</button></div>
      </section>
    </div>
    <section className="frame panel stack-s center-text demo-card" aria-labelledby="g-demo">
      <h2 id="g-demo" className="h3">Demo mode</h2>
      <p className="small">Explore the full website without an account. Demo profiles are saved only on this device and are never sent online.</p>
      <div><button className="btn secondary" onClick=${onDemo}>Explore in demo mode</button></div>
    </section>
  </div>`;
}

function AuthScreen({ role, mode, setMode, back }) {
  const [f, setF] = useState({ email: "", password: "", password2: "", name: "", school: "", code: "" });
  const [busy, setBusy] = useState(false), [err, setErr] = useState(""), [ok, setOk] = useState("");
  const set = (k) => (e) => { setF({ ...f, [k]: e.target.value }); setErr(""); };
  const who = role === "teacher" ? "Teacher" : "Pupil";
  const run = async () => {
    setErr(""); setOk("");
    const email = f.email.trim();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { setErr("Please enter a valid email address."); return; }
    if (mode !== "forgot") {
      if (f.password.length < 8) { setErr("Please enter a password of at least 8 characters."); return; }
    }
    if (mode === "signup") {
      if (!f.name.trim()) { setErr(role === "teacher" ? "Please enter the name pupils will see, for example Cikgu Aminah." : "Please enter your name. Your teacher will see it."); return; }
      if (f.password !== f.password2) { setErr("The two passwords do not match."); return; }
    }
    setBusy(true);
    try {
      if (mode === "signin") { await BACKEND.authApi.signIn(email, f.password); setOk("Signed in. Opening the academy…"); }
      else if (mode === "signup") {
        const r = await BACKEND.authApi.signUp(email, f.password, { role, display_name: f.name.trim(), school_name: f.school.trim(), teacher_code: role === "teacher" ? f.code.trim() : undefined });
        if (!r.session) setOk("Account created. We sent a confirmation link to " + email + ". Open it, then sign in.");
        else setOk("Account created. Opening the academy…");
      } else { await BACKEND.authApi.resetPassword(email); setOk("If an account exists for " + email + ", a password reset link is on its way. Check your inbox and spam folder."); }
    } catch (e) { setErr(friendlyAuthError(e)); }
    setBusy(false);
  };
  const title = mode === "signin" ? `${who} sign in` : mode === "signup" ? `Create a ${who.toLowerCase()} account` : "Reset your password";
  return html`<div className="stack-l narrow">
    <section className="frame panel stack auth-panel" aria-labelledby="auth-h" onKeyDown=${e => { if (e.key === "Enter" && e.target.tagName === "INPUT") run(); }}>
      <${Ribbon} id="auth-h" as="h1">${title}<//>
      ${mode === "signup" && role === "student" ? html`<p className="small note">Use the email address your school gave you, such as your DELIMa (@moe-dl.edu.my) account. We will send a confirmation link to it. Your wizard name and portrait are chosen next, after you sign in.</p>` : null}
      ${mode === "signup" && role === "teacher" ? html`<p className="small note">Your teacher account opens the Professor's Dashboard. If the site owner has set a teacher registration code, you need it to register.</p>` : null}
      <div className="stack-xs"><label htmlFor="au-email" className="strong">Email</label><input id="au-email" className="field" type="email" autoComplete="email" value=${f.email} onChange=${set("email")} /></div>
      ${mode !== "forgot" ? html`<div className="stack-xs"><label htmlFor="au-pw" className="strong">Password</label><input id="au-pw" className="field" type="password" autoComplete=${mode === "signup" ? "new-password" : "current-password"} value=${f.password} onChange=${set("password")} />
        ${mode === "signup" ? html`<span className="small muted">At least 8 characters. Do not share it with classmates.</span>` : null}</div>` : null}
      ${mode === "signup" ? html`<${React.Fragment}>
        <div className="stack-xs"><label htmlFor="au-pw2" className="strong">Type the password again</label><input id="au-pw2" className="field" type="password" autoComplete="new-password" value=${f.password2} onChange=${set("password2")} /></div>
        <div className="stack-xs"><label htmlFor="au-name" className="strong">${role === "teacher" ? "Name shown to pupils" : "Your name (seen by your teacher)"}</label><input id="au-name" className="field" maxLength="60" value=${f.name} onChange=${set("name")} placeholder=${role === "teacher" ? "For example: Cikgu Aminah" : "First name and initial"} /></div>
        ${role === "teacher" ? html`<${React.Fragment}><div className="stack-xs"><label htmlFor="au-school" className="strong">School name (optional)</label><input id="au-school" className="field" maxLength="120" value=${f.school} onChange=${set("school")} /></div>
          <div className="stack-xs"><label htmlFor="au-code" className="strong">Teacher registration code (if your site has one)</label><input id="au-code" className="field" value=${f.code} onChange=${set("code")} autoComplete="off" /></div><//>` : null}<//>` : null}
      <p className="errline" role="alert">${err}</p>
      ${ok ? html`<p className="note" role="status">${ok}</p>` : null}
      <div className="row wrap gap-s between">
        <button type="button" className="btn ghost" onClick=${back}><${Arrow} left=${true} /> Back</button>
        <button type="button" className="btn gold" onClick=${run} disabled=${busy} aria-busy=${busy}>${busy ? "Please wait…" : mode === "signin" ? "Sign in" : mode === "signup" ? "Create account" : "Send reset link"}</button>
      </div>
      <div className="row wrap gap-s center small">
        ${mode !== "signin" ? html`<button className="linkbtn" onClick=${() => { setMode("signin"); setErr(""); setOk(""); }}>I already have an account</button>` : null}
        ${mode !== "signup" ? html`<button className="linkbtn" onClick=${() => { setMode("signup"); setErr(""); setOk(""); }}>Create an account</button>` : null}
        ${mode !== "forgot" ? html`<button className="linkbtn" onClick=${() => { setMode("forgot"); setErr(""); setOk(""); }}>Forgot password?</button>` : null}
      </div>
    </section>
  </div>`;
}

function SetNewPassword({ done }) {
  const [p1, setP1] = useState(""), [p2, setP2] = useState(""), [busy, setBusy] = useState(false), [err, setErr] = useState(""), [ok, setOk] = useState(false);
  const run = async () => {
    if (p1.length < 8) { setErr("Please use at least 8 characters."); return; }
    if (p1 !== p2) { setErr("The two passwords do not match."); return; }
    setBusy(true); setErr("");
    try { await BACKEND.authApi.updatePassword(p1); setOk(true); } catch (e) { setErr(friendlyAuthError(e)); }
    setBusy(false);
  };
  return html`<div className="stack-l narrow"><section className="frame panel stack" aria-labelledby="np-h">
    <${Ribbon} id="np-h" as="h1">Choose a new password<//>
    ${ok ? html`<${React.Fragment}><p className="note" role="status">Your password has been changed.</p><div><button className="btn gold" onClick=${done}>Continue to the academy</button></div><//>` : html`<${React.Fragment}>
      <div className="stack-xs"><label htmlFor="np1" className="strong">New password</label><input id="np1" className="field" type="password" autoComplete="new-password" value=${p1} onChange=${e => setP1(e.target.value)} /></div>
      <div className="stack-xs"><label htmlFor="np2" className="strong">Type it again</label><input id="np2" className="field" type="password" autoComplete="new-password" value=${p2} onChange=${e => setP2(e.target.value)} /></div>
      <p className="errline" role="alert">${err}</p>
      <div><button className="btn gold" onClick=${run} disabled=${busy}>${busy ? "Saving…" : "Save new password"}</button></div><//>`}
  </section></div>`;
}

function AccountBar({ account, mode, onSignOut, onExitDemo, onClasses }) {
  if (mode === "demo") return html`<div className="accountbar demo" role="note"><span><strong>Demo mode</strong> · saved only on this device, not online${BACKEND ? "" : " · online accounts are not connected on this copy"}</span><span className="acc-actions"><button className="linkbtn small" onClick=${onExitDemo}>${BACKEND ? "Sign in instead" : "Leave demo mode"}</button></span></div>`;
  if (!account) return null;
  return html`<div className="accountbar"><span>Signed in as <strong>${account.display_name}</strong> · ${account.role === "teacher" ? "Teacher account" : "Pupil account"} · saved online</span><span className="acc-actions">${account.role === "student" && onClasses ? html`<button className="linkbtn small" onClick=${onClasses}>Join a class / My classes</button>` : null}<button className="linkbtn small" onClick=${onSignOut}>Sign out</button></span></div>`;
}

/* ===== Pupil: My classes, assignments, submissions and professor's notes ===== */
function WorkStatus({ status }) {
  const s = status || "not_started";
  return html`<span className=${"status ws-" + s}>${WORK_LABEL[s]}</span>`;
}
function workStatusFor(asg, attempts) {
  if (asg.work_status) return asg.work_status;
  return Object.values(attempts).some(a => a.assignmentId === asg.id && hasContent(a)) ? "in_progress" : "not_started";
}

function ProfessorNotes({ subs }) {
  if (!subs.length) return null;
  return html`<div className="stack-s notes-list">${subs.slice().reverse().map(s => html`<details key=${s.id} className="profnote" open=${s === subs[subs.length - 1]}>
    <summary>Revision ${s.revision} · submitted ${fmtTime(s.submitted_at)}${s.feedback && s.feedback.length ? " · " + s.feedback.length + " note" + (s.feedback.length > 1 ? "s" : "") : " · no notes yet"}</summary>
    ${(s.feedback || []).slice().sort((a, b) => a.created_at < b.created_at ? -1 : 1).map(f => html`<div key=${f.id} className="parchment-note stack-xs">
      <p className="eyebrow ink">Professor's notes · ${fmtTime(f.created_at)} · ${f.decision === "revision_requested" ? "Revision requested" : f.decision === "reviewed" ? "Reviewed" : "Note"}</p>
      ${f.comments ? html`<p>${f.comments}</p>` : null}
      ${f.strengths ? html`<p><strong>Strengths:</strong> ${f.strengths}</p>` : null}
      ${f.next_steps ? html`<p><strong>Next steps:</strong> ${f.next_steps}</p>` : null}
      ${f.rubric && Object.values(f.rubric).some(v => v) ? html`<div className="small"><strong>Teacher assessment</strong> (given by your teacher, not by the computer):
        <ul>${RUBRIC.filter(([k]) => f.rubric[k]).map(([k, l]) => html`<li key=${k}>${l}: ${f.rubric[k]} of 4 (${RUBRIC_LEVELS[f.rubric[k]]})</li>`)}</ul></div>` : null}
    </div>`)}
    <details className="small"><summary>See what you submitted</summary><div className="draftview small-p">${String(s.writing).split(/\n+/).filter(Boolean).map((p, i) => html`<p key=${i}>${p}</p>`)}</div></details>
  </details>`)}</div>`;
}

function MyClasses({ data, cloud, attempts, startAssignment, resume, refresh, go, setDialog }) {
  const [code, setCode] = useState(""), [preview, setPreview] = useState(null), [msg, setMsg] = useState(""), [busy, setBusy] = useState(false);
  const lookupId = useRef(0);
  const normalCode = value => value.toUpperCase().replace(/[\s-]/g, "");
  useEffect(() => () => { lookupId.current++; }, []);
  const errMsg = { invalid_code: "That code does not match an open class. Check the letters and numbers with your teacher.", too_many_attempts: "Too many wrong codes. Please wait 15 minutes, then try again.",
    already_member: "You are already in this class.", membership_archived: "This class has been archived by your teacher.", removed_by_teacher: "Your teacher removed you from this class. Ask your teacher if this is a mistake." };
  const reload = async () => {
    setBusy(true); setMsg("");
    try { await refresh(); setMsg("Your class list is up to date."); }
    catch (e) { setMsg("Could not refresh classes. " + friendlyAuthError(e)); }
    finally { setBusy(false); }
  };
  const look = async () => {
    if (busy) return;
    const cleaned = normalCode(code);
    if (!/^[A-HJ-NP-Z2-9]{7}$/.test(cleaned)) { setMsg("Enter the 7-letter-and-number class code from your teacher. This is not the teacher registration code."); setPreview(null); return; }
    const requestId = ++lookupId.current;
    setCode(cleaned); setBusy(true); setMsg(""); setPreview(null);
    try {
      const result = await cloud.previewClass(cleaned);
      if (requestId !== lookupId.current) return;
      if (result.error) setMsg(errMsg[result.error] || result.error);
      else if (result.already_member) { await refresh(); setMsg("You are already in this class. It is listed below."); }
      else setPreview({ ...result, code: cleaned });
    } catch (e) { if (requestId === lookupId.current) setMsg(friendlyAuthError(e)); }
    finally { if (requestId === lookupId.current) setBusy(false); }
  };
  const join = async () => {
    if (busy || !preview) return;
    setBusy(true); setMsg("");
    try {
      const result = await cloud.joinClass(preview.code);
      if (result.error && result.error !== "already_member") { setMsg(errMsg[result.error] || result.error); return; }
      const joinedName = result.class_name || preview.class_name;
      setPreview(null); setCode(""); Sfx.play("success");
      try { await refresh(); setMsg("You joined " + joinedName + ". Your enrolment is saved online. Its quests are below."); }
      catch (e) { setMsg("Your enrolment was saved online, but the class list could not refresh. Choose Refresh classes to load it."); }
    } catch (e) { setMsg(friendlyAuthError(e)); }
    finally { setBusy(false); }
  };
  const subsFor = (aid) => data.submissions.filter(s => s.assignment_id === aid);
  return html`<div className="stack-l">
    <div className="stack-s"><p className="eyebrow">Your classes</p><h1 tabIndex="-1">My classes</h1>
      <p className="lead">Join a class with the code from your teacher. Your class quests, submissions and professor's notes appear here.</p><div><button className="btn secondary small" onClick=${reload} disabled=${busy}>Refresh classes</button></div></div>
    <section className="frame panel stack-s" aria-labelledby="join-h">
      <h2 id="join-h" className="h3">Join a class</h2>
      <label htmlFor="cls-code" className="small strong">Your teacher’s class code</label><p id="cls-code-help" className="small muted">Use the 7-character code shown in your teacher’s class. It is different from the teacher registration code.</p><div className="row wrap gap-s addrow">
        <input id="cls-code" className="field codefield" value=${code} maxLength="20" autoComplete="off" autoCapitalize="characters" spellCheck=${false} aria-describedby="cls-code-help" disabled=${busy} placeholder="Class code, for example K7QM2XT" onChange=${e => { lookupId.current++; setCode(e.target.value.toUpperCase()); setMsg(""); setPreview(null); }} onKeyDown=${e => { if (e.key === "Enter") look(); }} />
        <button className="btn secondary" onClick=${look} disabled=${busy}>Find class</button></div>
      ${preview ? html`<div className="parchment-card stack-xs" role="status"><p className="ptitle">${preview.class_name}</p><p>Teacher: <strong>${preview.teacher_name}</strong> · Year ${preview.school_year}</p>
        <p className="small">Joining lets this teacher see your quest progress, practice and stars, and read writing only after you submit it.</p>
        <div className="row gap-s"><button className="btn gold" onClick=${join} disabled=${busy}>Join this class</button><button className="btn secondary" onClick=${() => setPreview(null)}>Cancel</button></div></div>` : null}
      <p className="errline" role="status">${msg}</p>
    </section>
    ${data.classes.length === 0 ? html`<p className="note">You have not joined a class yet.</p>` : data.classes.map(c => html`<section key=${c.class_id} className="frame panel stack classroom" aria-labelledby=${"c-" + c.class_id}>
      <div className="row wrap between gap-s"><div><h2 id=${"c-" + c.class_id} className="h3">${c.class_name}</h2><p className="small">Year ${c.school_year} · Teacher: ${c.teacher_name}${c.school_name ? " · " + c.school_name : ""}</p></div>
        ${c.membership_status === "archived" ? html`<span className="pill">Archived class: read only</span>` : null}</div>
      ${c.assignments.length === 0 ? html`<p className="muted">No quests assigned yet.</p>` : html`<ul className="asg-list">${c.assignments.map(asg => {
        const t = TOPIC[asg.topic_id]; const st = workStatusFor(asg, attempts); const att = Object.values(attempts).filter(a => a.assignmentId === asg.id).sort((x, y) => y.updated - x.updated)[0];
        const subs = subsFor(asg.id); const canWork = c.membership_status === "active" && asg.status === "published";
        return html`<li key=${asg.id} className="asg-card">
          <span className="qframe mini"><${Scene} id=${t.scene} alt="" /></span>
          <div className="stack-xs grow"><div className="row wrap gap-s"><strong className="cardtitle">${t.title}</strong><${WorkStatus} status=${st} />${asg.status === "closed" ? html`<span className="pill">Closed</span>` : null}</div>
            <p className="small">${t.purpose} · ${asg.due_date ? "Due " + fmtDS(asg.due_date) : "No due date"}</p>
            ${asg.instructions ? html`<p className="small instr"><strong>Teacher's instructions:</strong> ${asg.instructions}</p>` : null}
            <${ProfessorNotes} subs=${subs} /></div>
          <div className="stack-xs asg-actions">
            ${canWork && !att ? html`<button className="btn gold small" onClick=${() => startAssignment(asg, c)}>Start quest</button>` : null}
            ${att ? html`<button className=${"btn small " + (st === "revision_requested" || st === "in_progress" ? "gold" : "secondary")} onClick=${() => resume(att)}>${st === "revision_requested" ? "Revise my writing" : att.completed ? "View my writing" : "Continue quest"}</button>` : null}
          </div></li>`; })}</ul>`}
    </section>`)}
    <${ImportPanel} cloud=${cloud} data=${data} refresh=${refresh} setDialog=${setDialog} />
  </div>`;
}

/* Submit panel shown on the completion screen for class quests */
function SubmitPanel({ a, data, onSubmit }) {
  const asg = data.classes.flatMap(c => c.assignments.map(x => ({ ...x, class_name: c.class_name, teacher_name: c.teacher_name, membership_status: c.membership_status }))).find(x => x.id === a.assignmentId);
  const [state, setState] = useState({ s: "idle" });
  if (!asg) return html`<p className="note">This quest belongs to a class you can no longer submit to.</p>`;
  const subs = data.submissions.filter(s => s.assignment_id === asg.id);
  const st = asg.work_status;
  const blocked = st === "submitted" || st === "resubmitted" ? "Your teacher has your latest version and has not reviewed it yet." : st === "reviewed" ? "Your teacher has reviewed this work. You can submit again only if they request a revision." : asg.status !== "published" ? "This quest is closed." : asg.membership_status !== "active" ? "You can no longer submit to this class." : null;
  const go = async () => { setState({ s: "busy" }); const r = await onSubmit(a); setState(r.ok ? { s: "ok", r } : { s: "err", msg: r.msg }); };
  return html`<section className="frame panel stack-s submit-panel" aria-labelledby="sub-h">
    <h2 id="sub-h" className="h3">Submit to teacher</h2>
    <p className="small">Class: ${asg.class_name} · Teacher: ${asg.teacher_name}${subs.length ? " · " + subs.length + " earlier submission" + (subs.length > 1 ? "s" : "") : ""}</p>
    <p className="small">Submitting shares this version of your writing and your plan with your class teacher. Your teacher cannot see your drafts until you submit. Later edits do not change what you have already sent.</p>
    ${state.s === "ok" ? html`<p className="note" role="status">Sent to ${asg.teacher_name}: revision ${state.r.revision}, ${fmtTime(state.r.submitted_at)}.</p>`
      : blocked ? html`<p className="note">${blocked}</p>`
      : html`<div><button className="btn gold" onClick=${go} disabled=${state.s === "busy"} aria-busy=${state.s === "busy"}>${state.s === "busy" ? "Submitting…" : st === "revision_requested" ? "Resubmit to teacher" : "Submit to teacher"}</button></div>`}
    ${state.s === "err" ? html`<p className="errline" role="alert">${state.msg} Your writing is still saved here. You can try again.</p>` : null}
  </section>`;
}

/* Optional import of a profile kept in this browser's demo mode */
function ImportPanel({ cloud, data, refresh, setDialog }) {
  const idx = loadJSON(K.index, { profiles: [] });
  const marks = loadJSON("i2w.v2.importedTo", {});
  const [past, setPast] = useState(null), [sel, setSel] = useState(null), [msg, setMsg] = useState(""), [busy, setBusy] = useState(false);
  useEffect(() => { cloud.imports().then(setPast).catch(() => setPast([])); }, []);
  if (!idx.profiles.length) return null;
  const done = new Set((past || []).map(p => p.local_profile_id));
  const p = sel && idx.profiles.find(x => x.id === sel);
  const localAtt = p ? Object.values(loadJSON(K.attempts(p.id), {})) : [];
  const localProg = p ? { ...emptyProgress(), ...loadJSON(K.progress(p.id), {}) } : null;
  const doImport = async () => {
    setBusy(true); setMsg("");
    try {
      const r = await cloud.importLocal(p.id, data.wizard ? null : { portrait: p.portrait, name: p.name, house: p.house, year: p.year },
        localAtt.map(a => ({ ...a, assignmentId: null })), { name: p.name, stars: localProg.stars, xp: localProg.xp, unlocked: Object.keys(localProg.unlocked), achievements: Object.keys(localProg.achievements), drafts: localAtt.length, from: "demo mode on this device" });
      if (r.error === "already_imported") setMsg("This local profile has already been imported to your account.");
      else { const m = { ...marks, [p.id]: true }; saveJSON("i2w.v2.importedTo", m); setMsg(`Imported ${r.imported_drafts} piece${r.imported_drafts === 1 ? "" : "s"} of writing. Your local profile is still on this device.`); setSel(null); await refresh(); setPast(await cloud.imports()); }
    } catch (e) { setMsg("Import failed. Nothing was changed. " + friendlyAuthError(e)); }
    setBusy(false);
  };
  return html`<section className="frame panel stack-s" aria-labelledby="imp-h">
    <h2 id="imp-h" className="h3">Bring in a profile from this device (optional)</h2>
    <p className="small">This browser has demo-mode profiles. You can copy one profile's writing into your account. Imported writing is marked as imported. It is not sent to a teacher, and local stars are shown only as an unverified note.</p>
    <ul className="importlist">${idx.profiles.map(x => html`<li key=${x.id}><label className=${"optrow" + (sel === x.id ? " on" : "")}>
      <input type="radio" name="impsel" checked=${sel === x.id} disabled=${done.has(x.id)} onChange=${() => setSel(x.id)} />
      <${Portrait} id=${x.portrait} size="xs" house=${x.house} alt="" /> ${x.name} · ${HOUSE[x.house].name} · Year ${x.year} ${done.has(x.id) ? html`<span className="pill">Already imported</span>` : null}</label></li>`)}</ul>
    ${p ? html`<div className="parchment-card stack-xs"><p className="ptitle">Preview: ${p.name}</p>
      <p>${localAtt.length} piece${localAtt.length === 1 ? "" : "s"} of writing (${localAtt.filter(a => a.completed).length} completed)</p>
      <p className="small">Local record (not verified): ${localProg.stars} stars, ${localProg.xp} XP. These do not change your account's stars.</p>
      ${data.wizard ? html`<p className="small">Your account already has a wizard, so only the writing is imported.</p>` : html`<p className="small">The portrait, name, house and year will become your wizard.</p>`}
      <div className="row gap-s"><button className="btn gold" onClick=${doImport} disabled=${busy}>${busy ? "Importing…" : "Import this profile"}</button><button className="btn secondary" onClick=${() => setSel(null)}>Cancel</button></div></div>` : null}
    ${past && past.length ? html`<ul className="small">${past.map(x => html`<li key=${x.id}>Imported “${x.summary.name || x.local_profile_id}” on ${fmtTime(x.imported_at)} · local record ${x.summary.stars || 0} stars (not verified)</li>`)}</ul>` : null}
    <p className="hintnote" role="status">${msg}</p>
  </section>`;
}

/* Class quests shown in the common room */
function ClassQuests({ data, attempts, startAssignment, resume, go }) {
  const list = data.classes.filter(c => c.membership_status === "active").flatMap(c => c.assignments.filter(a => a.status === "published").map(a => ({ ...a, cls: c })));
  const open = list.filter(a => !["submitted", "resubmitted", "reviewed"].includes(a.work_status));
  const notes = list.filter(a => a.work_status === "revision_requested" || a.work_status === "reviewed").length;
  if (!data.classes.length) return html`<section className="frame panel row wrap between gap-s"><div><p className="eyebrow">Class quests</p><p>Join your class to see quests from your teacher.</p></div><button className="btn secondary" onClick=${() => go("classes")}>Join a class</button></section>`;
  return html`<section className="frame panel stack-s" aria-labelledby="cq-h">
    <div className="row wrap between gap-s"><h2 id="cq-h" className="h3">Class quests from your teacher</h2><button className="btn secondary small" onClick=${() => go("classes")}>My classes${notes ? " · " + notes + " with notes" : ""}</button></div>
    ${open.length === 0 ? html`<p className="muted">No open class quests. Well done!</p>` : html`<ul className="asg-mini">${open.slice(0, 4).map(a => { const t = TOPIC[a.topic_id]; const att = Object.values(attempts).filter(x => x.assignmentId === a.id).sort((x, y) => y.updated - x.updated)[0]; const st = workStatusFor(a, attempts);
      return html`<li key=${a.id} className="row wrap between gap-s"><span><strong>${t.title}</strong> · ${a.cls.class_name} · ${a.due_date ? "due " + fmtDS(a.due_date, { day: "numeric", month: "short" }) : "no due date"} <${WorkStatus} status=${st} /></span>
        ${att ? html`<button className="btn gold small" onClick=${() => resume(att)}>${st === "revision_requested" ? "Revise" : "Continue"}</button>` : html`<button className="btn gold small" onClick=${() => startAssignment(a, a.cls)}>Start</button>`}</li>`; })}</ul>`}
  </section>`;
}
/* ===== Professor's Dashboard (teacher accounts) =====
   Every list here comes from the database. The server decides what a teacher may see:
   drafts are never readable, and submissions only for classes the teacher owns. */
const STATUS_ORDER = ["not_started", "in_progress", "submitted", "revision_requested", "resubmitted", "reviewed"];

function useLoad(fn, deps) {
  const [s, setS] = useState({ loading: true, data: null, error: null });
  const run = useCallback(async () => { setS(x => ({ ...x, loading: true, error: null })); try { setS({ loading: false, data: await fn(), error: null }); } catch (e) { setS({ loading: false, data: null, error: e }); } }, deps);
  useEffect(() => { run(); }, [run]);
  return [s, run];
}
function Loading({ label = "Opening the records…" }) { return html`<div className="loadingbox" role="status"><span className="spinner" aria-hidden="true"></span><p>${label}</p></div>`; }
function LoadError({ error, retry }) { return html`<div className="note" role="alert"><p><strong>Could not load this page.</strong> ${friendlyAuthError(error)}</p><button className="btn secondary small" onClick=${retry}>Try again</button></div>`; }

async function copyText(text, setMsg) {
  try { await navigator.clipboard.writeText(text); setMsg("Copied " + text + "."); }
  catch (e) { setMsg("Copying is blocked here. Select the code and copy it: " + text); }
}

function TeacherApp({ account, api, accountBar }) {
  const [route, setRoute] = useState({ name: "dash" });
  const [dialog, setDialog] = useState(null);
  const [acct, setAcct] = useState(account);
  const go = (name, params = {}) => { setRoute({ name, ...params }); window.scrollTo(0, 0); };
  const first = useRef(true);
  useEffect(() => { if (first.current) { first.current = false; return; } const h = document.querySelector("main h1"); h && h.focus({ preventScroll: true }); }, [route]);
  let screen;
  switch (route.name) {
    case "class": screen = html`<${ClassRoom} api=${api} classId=${route.id} tab=${route.tab || "roster"} go=${go} setDialog=${setDialog} />`; break;
    case "assignment": screen = html`<${AssignmentView} api=${api} asg=${route.asg} cls=${route.cls} go=${go} />`; break;
    case "submission": screen = html`<${SubmissionView} api=${api} asg=${route.asg} cls=${route.cls} pupil=${route.pupil} go=${go} />`; break;
    case "profile": screen = html`<${TeacherProfile} api=${api} acct=${acct} setAcct=${setAcct} go=${go} />`; break;
    case "guide": screen = html`<${AccountsGuide} role="teacher" />`; break;
    case "info": screen = html`<${Teacher} sched=${loadJSON(K.schedule, {})} setSched=${(n) => saveJSON(K.schedule, n)} art=${loadJSON(K.art, null)} setArt=${(u) => u ? saveJSON(K.art, u) : true} index=${{ profiles: [] }} removeProfile=${() => { }} />`; break;
    default: screen = html`<${ProfessorDashboard} api=${api} acct=${acct} go=${go} setDialog=${setDialog} />`;
  }
  return html`<div className="app house-teacher" style=${{ "--house": "#5A3A1A", "--house-deep": "#2A190C" }}>
    <${Backdrop} scene="library" house="honeystone" art=${loadJSON(K.art, null)} />
    <a className="skip" href="#main">Skip to content</a>
    ${accountBar}
    <header className="topbar frame">
      <button className="brand" onClick=${() => go("dash")} aria-label="Professor's Dashboard">
        <svg viewBox="0 0 40 40" width="38" height="38" aria-hidden="true"><path d="M8,34 L30,6 C33,4 36,7 34,10 L12,36 Z" fill="#D9B15F" /><path d="M12,36 L8,34 L6,39 Z" fill="#F3E0A8" /></svg>
        <span className="brandtext"><b>Idea2Write</b><small>Professor's study</small></span></button>
      <nav aria-label="Teacher"><ul>
        ${[["dash", "Professor's Dashboard"], ["guide", "Teacher guide"], ["info", "Curriculum & UDL"], ["profile", "My profile"]].map(([r, l]) => html`<li key=${r}><button className=${"navlink" + (route.name === r || (r === "dash" && ["class", "assignment", "submission"].includes(route.name)) ? " on" : "")} onClick=${() => go(r)}>${l}</button></li>`)}
      </ul></nav>
    </header>
    <main id="main" key=${route.name + (route.id || "")} className="scene-in">${screen}</main>
    <footer className="foot"><span>Idea2Write Writing Academy · Professor's Dashboard</span></footer>
    ${dialog ? html`<${Dialog} d=${dialog} close=${() => setDialog(null)} />` : null}
  </div>`;
}

function ProfessorDashboard({ api, acct, go, setDialog }) {
  const [sum, reloadSum] = useLoad(() => api.summary(), []);
  const [cls, reloadCls] = useLoad(() => api.classes(), []);
  const [f, setF] = useState({ name: "", year: "" }), [msg, setMsg] = useState(""), [busy, setBusy] = useState(false), [showArchived, setShowArchived] = useState(false);
  const create = async () => {
    if (!f.name.trim()) { setMsg("Give the class a name, for example 5 Bestari."); return; }
    if (!f.year) { setMsg("Choose the school year for this class."); return; }
    setBusy(true); setMsg("");
    try { const c = await api.createClass(f.name.trim(), +f.year); setMsg(`Class “${c.name}” created. Its code is ${c.code}.`); setF({ name: "", year: "" }); Sfx.play("success"); reloadCls(); reloadSum(); }
    catch (e) { setMsg("The class was not created. " + friendlyAuthError(e)); }
    setBusy(false);
  };
  const s = sum.data || {};
  const list = (cls.data || []).filter(c => showArchived || !c.archived);
  return html`<div className="stack-l">
    <section className="frame panel study stack-s">
      <p className="eyebrow">Teacher dashboard</p>
      <h1 tabIndex="-1">Professor's Dashboard</h1>
      <p className="lead">Welcome, ${acct.display_name}${acct.school_name ? " · " + acct.school_name : ""}. Create classes, assign writing quests and read submitted work.</p>
    </section>
    ${sum.error ? html`<${LoadError} error=${sum.error} retry=${reloadSum} />` : html`<div className="sumtiles" aria-label="Summary">
      ${[["classes", "Active classes"], ["pupils", "Enrolled pupils"], ["assignments", "Published quests"], ["submissions", "Submissions received"], ["awaiting_review", "Awaiting your review"]].map(([k, l]) => html`<div key=${k} className="frame sumtile"><b>${sum.loading ? "…" : s[k]}</b><span className="small">${l}</span></div>`)}
    </div>`}
    <section className="frame panel stack-s" aria-labelledby="nc-h">
      <h2 id="nc-h" className="h3">Create a class</h2>
      <div className="row wrap gap-s">
        <label htmlFor="nc-name" className="sr">Class name</label><input id="nc-name" className="field" style=${{ maxWidth: "320px" }} maxLength="80" placeholder="Class name, for example 5 Bestari" value=${f.name} onChange=${e => setF({ ...f, name: e.target.value })} />
        <label htmlFor="nc-year" className="sr">School year</label>
        <select id="nc-year" className="field small sel" value=${f.year} onChange=${e => setF({ ...f, year: e.target.value })}><option value="">School year…</option>${YEARS.map(y => html`<option key=${y.id} value=${y.id}>${y.label}</option>`)}</select>
        <button className="btn gold" onClick=${create} disabled=${busy}>${busy ? "Creating…" : "Create class"}</button></div>
      <p className="hintnote" role="status">${msg}</p>
    </section>
    <section className="stack-s" aria-labelledby="cl-h">
      <div className="row wrap between gap-s"><h2 id="cl-h">My classrooms</h2><label className="opt small"><input type="checkbox" checked=${showArchived} onChange=${e => setShowArchived(e.target.checked)} /> Show archived classes</label></div>
      ${cls.loading ? html`<${Loading} />` : cls.error ? html`<${LoadError} error=${cls.error} retry=${reloadCls} />` : list.length === 0 ? html`<p className="note">No classes yet. Create your first class above.</p>` :
        html`<ul className="classgrid">${list.map(c => html`<li key=${c.id}><${ClassCard} c=${c} api=${api} go=${go} reload=${() => { reloadCls(); reloadSum(); }} setDialog=${setDialog} /></li>`)}</ul>`}
    </section>
  </div>`;
}

function ClassCard({ c, api, go, reload, setDialog }) {
  const [msg, setMsg] = useState(""), [code, setCode] = useState(c.code);
  const regen = () => setDialog({ title: "Make a new class code?", body: [`The old code ${code} will stop working straight away. Pupils already in the class stay in it.`], actions: [{ label: "Cancel" }, { label: "Make new code", kind: "gold", run: async () => { try { const n = await api.regenerateCode(c.id); setCode(n); setMsg("New code: " + n); } catch (e) { setMsg(friendlyAuthError(e)); } } }] });
  const toggle = async (patch, label) => { try { await api.updateClass(c.id, patch); setMsg(label); reload(); } catch (e) { setMsg(friendlyAuthError(e)); } };
  return html`<article className="frame classcard" aria-labelledby=${"cc-" + c.id}>
    <div className="row between wrap gap-s"><h3 id=${"cc-" + c.id} className="cardtitle">${c.name}</h3><span className="pill">Year ${c.school_year}</span></div>
    ${c.archived ? html`<p className="pill">Archived</p>` : null}
    <div className="codebox"><span className="small">Class code</span><code aria-label=${"Class code " + code.split("").join(" ")}>${code}</code>
      <button className="btn secondary small" onClick=${() => copyText(code, setMsg)}>Copy</button><button className="btn ghost small" onClick=${regen}>New code</button></div>
    <p className="small">${c.enrolment_open ? "Enrolment is open: pupils can join with this code." : "Enrolment is closed: the code does not work until you open it again."}</p>
    <div className="row wrap gap-s">
      <button className="btn gold small" onClick=${() => go("class", { id: c.id, tab: "roster" })}>Open classroom</button>
      <button className="btn secondary small" onClick=${() => go("class", { id: c.id, tab: "quests" })}>Assign quests</button>
      <button className="btn ghost small" onClick=${() => toggle({ enrolment_open: !c.enrolment_open }, c.enrolment_open ? "Enrolment closed." : "Enrolment opened.")}>${c.enrolment_open ? "Close enrolment" : "Open enrolment"}</button>
      <button className="btn ghost small" onClick=${() => setDialog({ title: c.archived ? "Restore this class?" : "Archive this class?", body: [c.archived ? "The class returns to your dashboard." : "The class is hidden from your dashboard and its code stops working. Pupils keep their submitted work and your notes. Nothing is deleted."], actions: [{ label: "Cancel" }, { label: c.archived ? "Restore" : "Archive", kind: "gold", run: () => toggle(c.archived ? { archived: false } : { archived: true, enrolment_open: false }, c.archived ? "Class restored." : "Class archived.") }] })}>${c.archived ? "Restore" : "Archive"}</button>
    </div>
    <p className="hintnote" role="status">${msg}</p>
  </article>`;
}

function ClassRoom({ api, classId, tab, go, setDialog }) {
  const [cls, reloadCls] = useLoad(async () => (await api.classes()).find(c => c.id === classId), [classId]);
  const [roster, reloadRoster] = useLoad(() => api.overview(classId), [classId]);
  const [asgs, reloadAsgs] = useLoad(() => api.assignments(classId), [classId]);
  const [t, setT] = useState(tab);
  const c = cls.data;
  if (cls.loading) return html`<${Loading} />`;
  if (cls.error || !c) return html`<${LoadError} error=${cls.error || new Error("Class not found")} retry=${reloadCls} />`;
  return html`<div className="stack-l">
    <div className="stack-s"><button className="linkbtn small align-start" onClick=${() => go("dash")}>← Professor's Dashboard</button>
      <p className="eyebrow">Classroom · Year ${c.school_year}</p><h1 tabIndex="-1">${c.name}</h1>
      <p className="small">Class code <strong className="codefield">${c.code}</strong> · ${c.enrolment_open ? "enrolment open" : "enrolment closed"}</p></div>
    <div className="tabs" role="tablist" aria-label="Classroom sections">
      ${[["roster", "Pupils & progress"], ["quests", "Writing quests"]].map(([id, l]) => html`<button key=${id} role="tab" aria-selected=${t === id} className=${"tab" + (t === id ? " on" : "")} onClick=${() => setT(id)}>${l}</button>`)}</div>
    ${t === "roster" ? html`<${Roster} state=${roster} reload=${reloadRoster} api=${api} setDialog=${setDialog} />` : html`<${ClassQuestsAdmin} c=${c} api=${api} asgs=${asgs} reload=${reloadAsgs} go=${go} />`}
  </div>`;
}

function Roster({ state, reload, api, setDialog }) {
  if (state.loading) return html`<${Loading} />`;
  if (state.error) return html`<${LoadError} error=${state.error} retry=${reload} />`;
  const rows = state.data || [];
  const change = (m, status) => {
    const text = { removed: ["Remove this pupil from the class?", "They lose access to this class, its quests and your notes. You will no longer see their progress or submissions here. Their own writing and rewards stay in their account. You can add them back later."],
      archived: ["Archive this membership?", "The pupil keeps read-only access to their past class work and your notes, but cannot start or submit class quests. You still see their record."],
      active: ["Make this pupil active again?", "They can work on and submit class quests again."] }[status];
    setDialog({ title: text[0], body: [text[1]], actions: [{ label: "Cancel" }, { label: "Confirm", kind: "gold", run: async () => { try { await api.setMembership(m.membership_id, status); reload(); } catch (e) { setDialog({ title: "Not changed", body: [friendlyAuthError(e)], actions: [{ label: "OK" }] }); } } }] });
  };
  if (!rows.length) return html`<p className="note">No pupils have joined yet. Share the class code with your pupils. They sign in, open My classes and enter the code.</p>`;
  return html`<section className="frame panel stack-s" aria-label="Pupils and progress">
    <p className="small muted">Stars, XP and levels are completion rewards. Practice counts show activities finished, not proficiency. Teacher assessments appear only inside submissions you have reviewed.</p>
    <div className="tablewrap"><table className="roster"><thead><tr><th scope="col">Pupil</th><th scope="col">Membership</th><th scope="col">Class quests done</th><th scope="col">Submissions</th><th scope="col">Practice (V / G / S)</th><th scope="col">Stars · XP · Level</th><th scope="col">Achievements</th><th scope="col">Last activity</th><th scope="col">Actions</th></tr></thead>
      <tbody>${rows.map(r => { const lv = levelInfo(r.xp || 0); return html`<tr key=${r.student_id}>
        <td><span className="row gap-s">${r.portrait ? html`<${Portrait} id=${r.portrait} size="xs" house=${r.house} alt="" />` : null}<span><strong>${r.wizard_name}</strong><br /><span className="small muted">${r.display_name}</span></span></span></td>
        <td>${{ active: "Active", archived: "Archived", removed: "Removed" }[r.membership_status]}</td>
        <td>${r.assignments_done} of ${r.assignments_total}</td><td>${r.submissions}</td>
        <td>${r.practice_vocab} / ${r.practice_grammar} / ${r.practice_sentence}</td>
        <td>★ ${r.stars} · ${r.xp} XP · L${lv.level}</td><td className="wrap small">${(r.achievements || []).length ? r.achievements.map(a => (ACHIEVEMENTS.find(x => x.id === a) || { name: a }).name).join(", ") : "None yet"}</td>
        <td>${r.last_activity ? fmtTime(r.last_activity) : "No activity yet"}</td>
        <td className="wrap">${r.membership_status === "active" ? html`<button className="linkbtn small" onClick=${() => change(r, "archived")}>Archive</button> <button className="linkbtn small danger" onClick=${() => change(r, "removed")}>Remove</button>` : html`<button className="linkbtn small" onClick=${() => change(r, "active")}>Make active</button>`}</td>
      </tr>`; })}</tbody></table></div>
  </section>`;
}

function ClassQuestsAdmin({ c, api, asgs, reload, go }) {
  const [f, setF] = useState({ topic: "", instructions: "", due: "" }), [allYears, setAllYears] = useState(false), [msg, setMsg] = useState(""), [busy, setBusy] = useState(false);
  const topics = TOPICS.filter(t => allYears || t.year === c.school_year);
  const publish = async () => {
    if (!f.topic) { setMsg("Choose a writing quest to assign."); return; }
    setBusy(true); setMsg("");
    try { await api.createAssignment(c.id, f.topic, f.instructions.trim(), f.due || null); setMsg(`Published “${TOPIC[f.topic].title}” to ${c.name}.`); setF({ topic: "", instructions: "", due: "" }); Sfx.play("success"); reload(); }
    catch (e) { setMsg("Not published. " + friendlyAuthError(e)); }
    setBusy(false);
  };
  const t = f.topic ? TOPIC[f.topic] : null;
  return html`<div className="stack-l">
    <section className="frame panel stack-s" aria-labelledby="as-h">
      <h2 id="as-h" className="h3">Assign a writing quest</h2>
      <div className="row wrap gap-s"><label htmlFor="as-topic" className="strong">Quest</label>
        <select id="as-topic" className="field small sel" value=${f.topic} onChange=${e => setF({ ...f, topic: e.target.value })}><option value="">Choose an activity…</option>
          ${topics.map(x => html`<option key=${x.id} value=${x.id}>Year ${x.year} · ${x.title} (${x.purpose})</option>`)}</select>
        <label className="opt small"><input type="checkbox" checked=${allYears} onChange=${e => setAllYears(e.target.checked)} /> Show other years</label></div>
      ${t ? html`<div className="row gap-s wrap"><span className="qframe mini"><${Scene} id=${t.scene} alt="" /></span><div className="stack-xs grow"><p><strong>Task:</strong> ${t.task}</p><p className="small">Standards as supplied for this activity: ${t.std.join(", ")} (supporting ${SUPPORT_STD.join(", ")}). Goal: ${yearOf(t.year).goalText}.</p></div></div>` : null}
      <label htmlFor="as-ins" className="strong">Instructions for pupils (optional)</label>
      <textarea id="as-ins" className="field" rows="3" maxLength="2000" value=${f.instructions} onChange=${e => setF({ ...f, instructions: e.target.value })} placeholder="For example: Write about a trip during the school holidays."></textarea>
      <div className="row wrap gap-s"><label htmlFor="as-due" className="strong">Due date (optional)</label><input id="as-due" type="date" className="field small sel" value=${f.due} onChange=${e => setF({ ...f, due: e.target.value })} />
        <button className="btn gold" onClick=${publish} disabled=${busy}>${busy ? "Publishing…" : "Publish to class"}</button></div>
      <p className="hintnote" role="status">${msg}</p>
    </section>
    <section className="stack-s" aria-labelledby="al-h"><h2 id="al-h" className="h3">Published quests</h2>
      ${asgs.loading ? html`<${Loading} />` : asgs.error ? html`<${LoadError} error=${asgs.error} retry=${reload} />` : !(asgs.data || []).length ? html`<p className="note">No quests assigned yet.</p>` :
      html`<ul className="asg-list">${asgs.data.map(a => { const tp = TOPIC[a.topic_id]; return html`<li key=${a.id} className="asg-card">
        <span className="qframe mini"><${Scene} id=${tp.scene} alt="" /></span>
        <div className="stack-xs grow"><strong className="cardtitle">${tp.title}</strong><p className="small">Year ${tp.year} · ${tp.purpose} · ${a.due_date ? "Due " + fmtDS(a.due_date) : "No due date"} · ${a.status === "published" ? "Open" : "Closed"}</p>
          ${a.instructions ? html`<p className="small instr">${a.instructions}</p>` : null}</div>
        <div className="stack-xs asg-actions"><button className="btn gold small" onClick=${() => go("assignment", { asg: a, cls: c })}>View work</button>
          <button className="btn ghost small" onClick=${async () => { try { await api.updateAssignment(a.id, { status: a.status === "published" ? "closed" : "published" }); reload(); } catch (e) { } }}>${a.status === "published" ? "Close quest" : "Reopen quest"}</button></div></li>`; })}</ul>`}
    </section>
  </div>`;
}

function AssignmentView({ api, asg, cls, go }) {
  const [ov, reload] = useLoad(() => api.assignmentOverview(asg.id), [asg.id]);
  const [filter, setFilter] = useState("all");
  const t = TOPIC[asg.topic_id];
  const rows = (ov.data || []).filter(r => filter === "all" || r.status === filter);
  const count = (s) => (ov.data || []).filter(r => r.status === s).length;
  return html`<div className="stack-l">
    <div className="stack-s"><button className="linkbtn small align-start" onClick=${() => go("class", { id: cls.id, tab: "quests" })}>← ${cls.name}</button>
      <p className="eyebrow">Writing quest · ${cls.name}</p><h1 tabIndex="-1">${t.title}</h1>
      <p className="small">${asg.due_date ? "Due " + fmtDS(asg.due_date) : "No due date"}${asg.instructions ? " · " + asg.instructions : ""}</p></div>
    <div className="filters" role="group" aria-label="Filter by status">
      <button className="filter" aria-pressed=${filter === "all"} onClick=${() => setFilter("all")}>All (${(ov.data || []).length})</button>
      ${STATUS_ORDER.map(s => html`<button key=${s} className="filter" aria-pressed=${filter === s} onClick=${() => setFilter(s)}>${WORK_LABEL[s]} (${count(s)})</button>`)}</div>
    <p className="small muted">You can read writing only after a pupil submits it. For unfinished work you see the status and the last time it was saved.</p>
    ${ov.loading ? html`<${Loading} />` : ov.error ? html`<${LoadError} error=${ov.error} retry=${reload} />` : !rows.length ? html`<p className="note">No pupils with this status.</p>` :
    html`<div className="tablewrap"><table className="roster"><thead><tr><th scope="col">Pupil</th><th scope="col">Status</th><th scope="col">Last saved</th><th scope="col">Submitted</th><th scope="col">Revision</th><th scope="col"></th></tr></thead>
      <tbody>${rows.map(r => html`<tr key=${r.student_id}><td><span className="row gap-s">${r.portrait ? html`<${Portrait} id=${r.portrait} size="xs" house=${r.house} alt="" />` : null}<span><strong>${r.wizard_name}</strong><br /><span className="small muted">${r.display_name}</span></span></span></td>
        <td><${WorkStatus} status=${r.status} /></td><td>${r.last_saved_at ? fmtTime(r.last_saved_at) : "—"}</td><td>${r.submitted_at ? fmtTime(r.submitted_at) : "—"}</td><td>${r.latest_revision || "—"}</td>
        <td>${r.latest_submission_id ? html`<button className="btn gold small" onClick=${() => go("submission", { asg, cls, pupil: r })}>Open submission</button>` : html`<span className="small muted">Nothing to read yet</span>`}</td></tr>`)}</tbody></table></div>`}
  </div>`;
}

function SubmissionView({ api, asg, cls, pupil, go }) {
  const [st, reload] = useLoad(() => api.submissionsFor(asg.id, pupil.student_id), [asg.id, pupil.student_id]);
  const [rev, setRev] = useState(null);
  const [f, setF] = useState({ comments: "", strengths: "", next_steps: "", rubric: {} }), [msg, setMsg] = useState(""), [busy, setBusy] = useState(false);
  const subs = st.data || [];
  const s = subs.find(x => x.revision === rev) || subs[subs.length - 1];
  const latest = subs[subs.length - 1];
  const send = async (decision) => {
    if (!f.comments.trim() && !f.strengths.trim() && !f.next_steps.trim() && decision === "note") { setMsg("Write a note before saving it."); return; }
    setBusy(true); setMsg("");
    const rubric = Object.fromEntries(RUBRIC.map(([k]) => [k, f.rubric[k] ? +f.rubric[k] : null]));
    try { const r = await api.giveFeedback(s.id, { ...f, decision, rubric: Object.values(rubric).some(Boolean) ? rubric : null });
      setMsg(decision === "revision_requested" ? "Revision requested. The pupil will see your notes." : decision === "reviewed" ? "Marked as reviewed. The pupil will see your notes." : "Note saved. The pupil will see it.");
      setF({ comments: "", strengths: "", next_steps: "", rubric: {} }); reload(); }
    catch (e) { setMsg("Not saved. " + friendlyAuthError(e)); }
    setBusy(false);
  };
  const t = TOPIC[asg.topic_id];
  return html`<div className="stack-l">
    <div className="stack-s"><button className="linkbtn small align-start" onClick=${() => go("assignment", { asg, cls })}>← ${t.title}</button>
      <p className="eyebrow">Submission · ${cls.name}</p><h1 tabIndex="-1">${pupil.wizard_name} <span className="small muted">(${pupil.display_name})</span></h1></div>
    ${st.loading ? html`<${Loading} />` : st.error ? html`<${LoadError} error=${st.error} retry=${reload} />` : !s ? html`<p className="note">No submissions yet.</p>` : html`<${React.Fragment}>
      <div className="revtabs" role="group" aria-label="Revisions">${subs.map(x => html`<button key=${x.id} className="filter" aria-pressed=${x.id === s.id} onClick=${() => setRev(x.revision)}>Revision ${x.revision} · ${fmtTime(x.submitted_at)}</button>`)}</div>
      <div className="sub-grid">
        <article className="parchment stack-s" aria-label=${"Revision " + s.revision}>
          <p className="ink-muted small">${s.activity_title} · Year ${s.school_year} · Support: ${(levelOf(s.support_level) || { name: "not recorded" }).name} · Revision ${s.revision} · ${fmtTime(s.submitted_at)}</p>
          <h2 className="ink-title">${s.title || s.activity_title}</h2>
          <div className="draftview">${String(s.writing).split(/\n+/).filter(Boolean).map((p, i) => html`<p key=${i}>${p}</p>`)}</div>
          <p className="small ink-muted">${words(s.writing)} words · ${paras(s.writing)} paragraph(s)</p>
          <div className="improve"><strong>Pupil's improvement note:</strong> ${s.reflection || "Not recorded."}</div>
          <details open><summary className="strong">Submitted plan</summary><div className="planview">${(s.plan.sections || []).map(sec => { const cs = (s.plan.cards || []).filter(c => c.section === sec.id); return html`<div key=${sec.id} className="psum"><h4>${sec.label}</h4>${cs.length ? html`<ul>${cs.map(c => html`<li key=${c.id}>${c.text}</li>`)}</ul>` : html`<p className="small">No cards.</p>`}</div>`; })}
            ${(s.plan.cards || []).filter(c => !c.section).length ? html`<div className="psum"><h4>Idea tray</h4><ul>${s.plan.cards.filter(c => !c.section).map(c => html`<li key=${c.id}>${c.text}</li>`)}</ul></div>` : null}</div></details>
        </article>
        <div className="stack">
          <section className="frame panel stack-s" aria-labelledby="pn-h"><h2 id="pn-h" className="h3">Professor's notes on this revision</h2>
            ${(s.feedback || []).length ? s.feedback.slice().sort((a, b) => a.created_at < b.created_at ? -1 : 1).map(fb => html`<div key=${fb.id} className="parchment-note stack-xs">
              <p className="eyebrow">${fmtTime(fb.created_at)} · ${fb.decision === "revision_requested" ? "Revision requested" : fb.decision === "reviewed" ? "Reviewed" : "Note"}</p>
              ${fb.comments ? html`<p>${fb.comments}</p>` : null}${fb.strengths ? html`<p><strong>Strengths:</strong> ${fb.strengths}</p>` : null}${fb.next_steps ? html`<p><strong>Next steps:</strong> ${fb.next_steps}</p>` : null}
              ${fb.rubric ? html`<p className="small"><strong>Teacher assessment:</strong> ${RUBRIC.filter(([k]) => fb.rubric[k]).map(([k, l]) => `${l} ${fb.rubric[k]}/4`).join(" · ") || "none"}</p>` : null}</div>`) : html`<p className="muted">No notes on this revision yet.</p>`}
          </section>
          ${s.id === latest.id ? html`<section className="frame panel stack-s" aria-labelledby="fb-h"><h2 id="fb-h" className="h3">Write professor's notes</h2>
            <p className="small muted">Your notes are kept separate from the pupil's writing. The pupil's text is never changed.</p>
            <label htmlFor="fb-c" className="strong">Comments</label><textarea id="fb-c" className="field" rows="3" value=${f.comments} onChange=${e => setF({ ...f, comments: e.target.value })}></textarea>
            <label htmlFor="fb-s" className="strong">Strengths</label><textarea id="fb-s" className="field" rows="2" value=${f.strengths} onChange=${e => setF({ ...f, strengths: e.target.value })}></textarea>
            <label htmlFor="fb-n" className="strong">Suggested next steps</label><textarea id="fb-n" className="field" rows="2" value=${f.next_steps} onChange=${e => setF({ ...f, next_steps: e.target.value })}></textarea>
            <details><summary className="strong">Optional teacher assessment (1–4)</summary>
              <p className="small muted">These ratings are your own judgement as the teacher. The website never scores writing automatically.</p>
              <div className="rubric">${RUBRIC.map(([k, l]) => html`<label key=${k} className="stack-xs small"><span>${l}</span><select className="mini-select" value=${f.rubric[k] || ""} onChange=${e => setF({ ...f, rubric: { ...f.rubric, [k]: e.target.value } })}>
                <option value="">Not rated</option>${[1, 2, 3, 4].map(n => html`<option key=${n} value=${n}>${n} · ${RUBRIC_LEVELS[n]}</option>`)}</select></label>`)}</div></details>
            <div className="row wrap gap-s"><button className="btn secondary small" disabled=${busy} onClick=${() => send("note")}>Save note only</button>
              <button className="btn secondary" disabled=${busy} onClick=${() => send("revision_requested")}>Request a revision</button>
              <button className="btn gold" disabled=${busy} onClick=${() => send("reviewed")}>Mark as reviewed</button></div>
            <p className="hintnote" role="status">${msg}</p></section>` : html`<p className="note">This is an earlier revision. Notes and decisions apply to the latest revision.</p>`}
        </div>
      </div><//>`}
  </div>`;
}

function TeacherProfile({ api, acct, setAcct, go }) {
  const [f, setF] = useState({ display_name: acct.display_name, school_name: acct.school_name || "" }), [msg, setMsg] = useState("");
  const save = async () => {
    if (!f.display_name.trim()) { setMsg("Please enter the name pupils will see."); return; }
    try { const r = await api.updateProfile({ display_name: f.display_name.trim(), school_name: f.school_name.trim() || null }); setAcct({ ...acct, ...(r && r[0]) }); setMsg("Profile saved."); } catch (e) { setMsg("Not saved. " + friendlyAuthError(e)); }
  };
  return html`<div className="stack-l narrow"><section className="frame panel stack" aria-labelledby="tp-h">
    <${Ribbon} id="tp-h" as="h1">Professor's profile<//>
    <div className="stack-xs"><label htmlFor="tp-n" className="strong">Name shown to pupils</label><input id="tp-n" className="field" maxLength="60" value=${f.display_name} onChange=${e => setF({ ...f, display_name: e.target.value })} /></div>
    <div className="stack-xs"><label htmlFor="tp-s" className="strong">School name (optional)</label><input id="tp-s" className="field" maxLength="120" value=${f.school_name} onChange=${e => setF({ ...f, school_name: e.target.value })} /></div>
    <div className="row gap-s"><button className="btn gold" onClick=${save}>Save profile</button><button className="btn ghost" onClick=${() => go("dash")}>Back to dashboard</button></div>
    <p className="hintnote" role="status">${msg}</p>
  </section></div>`;
}

function AccountsGuide({ role }) {
  const teacher = [["Create your teacher account", "Choose “I am a teacher”, then “Create teacher account”. Use your school email (for example your DELIMa account). Confirm the email link, then sign in."],
    ["Create a class", "In the Professor's Dashboard, type a class name, choose Year 4, 5 or 6 and select Create class. Each class gets a random 7-character code."],
    ["Share the class code", "Write the code on the board or copy it. Pupils sign in, open My classes and enter the code. They see your name and the class name before joining. Close enrolment when everyone has joined, or make a new code if it was shared by mistake."],
    ["Assign a writing quest", "Open the class, choose Writing quests, pick an existing activity, add instructions and an optional due date, then Publish to class."],
    ["Follow progress", "Pupils & progress shows each pupil's class quests, submissions, practice counts, stars and last activity. You never see unfinished drafts, only their status and last-saved time."],
    ["Read and give notes", "Open a quest, filter by status and open a submission. Write comments, strengths and next steps. Request a revision or mark it reviewed. Optional 1–4 ratings are your own teacher assessment."]];
  const pupil = [["Sign in", "Choose “I am a pupil”. Use the email address and password your teacher or school gave you. Forgot your password? Choose “Forgot password?” and open the email link."],
    ["Create your wizard", "The first time, choose your portrait, wizard name, house and year. Your teacher sees your wizard name and your account name."],
    ["Join your class", "Open My classes and type the class code. Check the class and teacher name, then choose Join this class."],
    ["Do your quest", "Class quests appear in My classes, the common room and the calendar. Work through Explore, Organise, Write and Review as usual. Your work saves online by itself."],
    ["Submit to your teacher", "After you complete the quest, choose Submit to teacher. Only the submitted version is shared."],
    ["Read professor's notes", "Notes appear under the quest in My classes. If your teacher asks for a revision, choose Revise my writing, improve it, complete it again and resubmit."]];
  const list = role === "teacher" ? teacher : pupil;
  return html`<div className="stack-l prose"><h1 tabIndex="-1">${role === "teacher" ? "Teacher guide" : "Pupil guide"}</h1>
    <ol className="guide">${list.map(([h, p]) => html`<li key=${h} className="frame"><h2 className="h3">${h}</h2><p>${p}</p></li>`)}</ol>
    <section className="frame panel stack-s"><h2 className="h3">Privacy</h2><p>Unfinished drafts are private to the pupil. Teachers read writing only after it is submitted, and only for their own classes. A class code lets a pupil join a class; it does not give access to anyone's work. Stars and practice counts are completion records, not grades.</p></section>
  </div>`;
}
Object.assign(IMG, {"shot_calendar": "data:image/jpeg;base64,", "shot_create": "data:image/jpeg;base64,", "shot_done": "data:image/jpeg;base64,", "shot_explore": "data:image/jpeg;base64,", "shot_home": "data:image/jpeg;base64,", "shot_plan": "data:image/jpeg;base64,", "shot_profile": "data:image/jpeg;base64,", "shot_quests": "data:image/jpeg;base64,", "shot_write": "data:image/jpeg;base64,"});
/* ===== App ===== */
function StorageBanner() {
  if (CAN_STORE) return null;
  return html`<div className="banner" role="status"><strong>Saving is unavailable in this browser.</strong> You can still play, but profiles, writing and rewards are lost when the page closes. Download your writing on the Review screen to keep a copy.</div>`;
}

function wizardToProf(account, w) { return w ? { id: account.id, name: w.wizard_name, portrait: w.portrait, house: w.house, year: w.school_year } : null; }

function App({ cloudBox, boot, account, accountBar }) {
  const online = !!cloudBox;
  const cloud = online ? cloudBox.cloud : null;
  const [index, setIndexS] = useState(() => online ? { profiles: [], active: null } : loadJSON(K.index, { profiles: [], active: null }));
  const [wiz, setWiz] = useState(online ? wizardToProf(account, boot.wizard) : null);
  const prof = online ? wiz : (index.profiles.find(p => p.id === index.active) || null);
  const [classData, setClassData] = useState(online ? { classes: boot.classes, submissions: boot.submissions, wizard: boot.wizard } : null);
  const [route, setRoute] = useState(prof ? "home" : online ? "create" : index.profiles.length ? "who" : "create");
  const [attempts, setAttempts] = useState(() => online ? boot.attempts : prof ? loadJSON(K.attempts(prof.id), {}) : {});
  const [progress, setProgressS] = useState(() => online ? boot.progress : prof ? { ...emptyProgress(), ...loadJSON(K.progress(prof.id), {}) } : emptyProgress());
  const [prefs, setPrefsS] = useState(() => online ? ((boot.wizard && boot.wizard.prefs) || {}) : prof ? loadJSON(K.prefs(prof.id), {}) : {});
  const [attempt, setAttempt] = useState(null);
  const [pending, setPending] = useState(null);
  const [save, setSave] = useState({ state: online ? "idle" : CAN_STORE ? "idle" : "off" });
  const [dialog, setDialog] = useState(null);
  const [reveal, setReveal] = useState(null);
  const [practice, setPractice] = useState(null);
  const [sched, setSchedS] = useState(() => loadJSON(K.schedule, {}));
  const [art, setArtS] = useState(() => loadJSON(K.art, null));
  const [sound, setSound] = useState(false);
  const [today, setToday] = useState(klDate());
  const [entering, setEntering] = useState(null);
  const dirty = useRef(false), attRef = useRef(attempts), profRef = useRef(prof);
  attRef.current = attempts; profRef.current = prof;
  useEffect(() => { const id = setInterval(() => setToday(klDate()), 60000); return () => clearInterval(id); }, []);
  /* Background retries (after going back online) report here */
  if (online) cloudBox.statusRef.current = (r) => { if (r.state === "online") setSave({ state: "online", at: Date.now() }); else if (r.state === "local") setSave({ state: "local" }); };
  useEffect(() => {
    if (!online || !boot.recovery || !boot.recovery.length) return;
    const r = boot.recovery[0], t = TOPIC[r.local.topicId];
    const local = { ...r.local, id: r.id };
    setDialog({ title: "Unsynced writing found on this device", body: [`This device kept a copy of “${t ? t.title : "a quest"}” that did not reach the server (${words(local.draft || "")} words).`,
      r.sameBase ? "The online copy has not changed since then, so it is safe to send this copy now." : "The online copy was changed somewhere else since then. Choose which version to keep."],
      actions: r.sameBase ? [{ label: "Discard this copy", kind: "secondary", run: () => cloud.discardRecovery(r.id) }, { label: "Send it to my account", kind: "gold", run: () => { attRef.current = { ...attRef.current, [r.id]: local }; setAttempts(attRef.current); cloud.save(local).then(x => handleSaveResult(local, x)); } }]
        : [{ label: "Keep the online version", kind: "secondary", run: () => cloud.discardRecovery(r.id) }, { label: "Keep both", kind: "secondary", run: () => { cloud.discardRecovery(r.id); const copy = { ...local, id: uid("att"), title: (local.title || "") + " (copy from this device)" }; attRef.current = { ...attRef.current, [copy.id]: copy }; setAttempts(attRef.current); cloud.save(copy).then(x => handleSaveResult(copy, x)); } },
          { label: "Use this device's copy", kind: "gold", run: () => { cloud.setVersion(r.id, r.serverVersion); attRef.current = { ...attRef.current, [r.id]: local }; setAttempts(attRef.current); cloud.save(local).then(x => handleSaveResult(local, x)); } }] });
  }, []);

  const setIndex = (n) => { setIndexS(n); saveJSON(K.index, n); };
  const refreshProgress = async () => { try { const p = await cloud.progress(); setProgressS({ ...emptyProgress(), ...p }); } catch (e) { } };
  const refreshClasses = async () => { try { const [classes, submissions] = await Promise.all([cloud.classes(), cloud.submissions()]); setClassData(d => ({ ...d, classes: classes || [], submissions: submissions || [] })); } catch (e) { } };
  const setProgress = (fn) => setProgressS(p => {
    const n = typeof fn === "function" ? fn(p) : fn;
    if (online) {
      /* Practice completions are recorded on the server, which also awards achievements */
      Object.keys(n.practice).filter(k => !p.practice[k]).forEach(k => { const r = n.practice[k]; cloud.recordPractice(k, r.firstTry, r.total).then(refreshProgress).catch(() => setSave({ state: "failed" })); });
      return n;
    }
    if (profRef.current && CAN_STORE && !saveJSON(K.progress(profRef.current.id), n)) setSave({ state: "error" }); return n; });
  const setPrefs = (n) => { setPrefsS(n); if (online) cloud.savePrefs(n).catch(() => { }); else prof && saveJSON(K.prefs(prof.id), n); };
  const setSched = (n) => { setSchedS(n); return saveJSON(K.schedule, n); };
  const setArt = (url) => { setArtS(url); if (!url) { try { localStorage.removeItem(K.art); } catch (e) { } return true; } return saveJSON(K.art, url); };

  const loadProfile = (pid) => {
    const at = pid ? loadJSON(K.attempts(pid), {}) : {};
    attRef.current = at; setAttempts(at);
    setProgressS(pid ? { ...emptyProgress(), ...loadJSON(K.progress(pid), {}) } : emptyProgress()); setPrefsS(pid ? loadJSON(K.prefs(pid), {}) : {});
    setAttempt(null); setPending(null); setReveal(null); setPractice(null);
  };
  const conflictOpen = useRef(false);
  const handleSaveResult = (a, r) => {
    if (!r) return;
    if (r.state === "online") setSave({ state: "online", at: Date.now() });
    else if (r.state === "local") setSave({ state: "local" });
    else if (r.state === "conflict") { setSave({ state: "conflict" }); showConflict(a, r.server); }
    else setSave({ state: "failed" });
  };
  const showConflict = (mine, server) => {
    if (conflictOpen.current) return; conflictOpen.current = true;
    const sv = { ...server.data, id: mine.id };
    const close = () => { conflictOpen.current = false; };
    setDialog({ title: "This writing was changed somewhere else", body: [`“${TOPIC[mine.topicId].title}” was saved from another tab or device at ${fmtTime(server.updated_at)}. To protect both versions, nothing has been overwritten.`,
      `Newer saved version: ${words(sv.draft || "")} words. This screen: ${words(mine.draft || "")} words.`, "Which version would you like to keep?"],
      actions: [
        { label: "Keep both (save mine as a copy)", kind: "secondary", run: () => { close(); cloud.acceptServerVersion(mine.id, server.version); const copy = { ...mine, id: uid("att"), title: (mine.title || "") + " (copy)", updated: Date.now() }; attRef.current = { ...attRef.current, [mine.id]: sv, [copy.id]: copy }; setAttempts(attRef.current); setAttempt(cur => cur && cur.id === mine.id ? copy : cur); cloud.save(copy).then(r => handleSaveResult(copy, r)); } },
        { label: "Use the newer saved version", kind: "secondary", run: () => { close(); cloud.acceptServerVersion(mine.id, server.version); attRef.current = { ...attRef.current, [mine.id]: sv }; setAttempts(attRef.current); setAttempt(cur => cur && cur.id === mine.id ? sv : cur); setSave({ state: "online" }); } },
        { label: "Keep this screen's version", kind: "gold", run: () => { close(); cloud.setVersion(mine.id, server.version); cloud.save(mine).then(r => handleSaveResult(mine, r)); } }] });
  };
  const persist = useCallback((a) => {
    const p = profRef.current; if (!p) return;
    const next = { ...attRef.current, [a.id]: a }; attRef.current = next; setAttempts(next);
    if (online) { dirty.current = false; return cloud.save(a).then(r => { handleSaveResult(a, r); return r; }); }
    if (!CAN_STORE) { setSave({ state: "off" }); return; }
    const ok = saveJSON(K.attempts(p.id), next);
    setSave(ok ? { state: "saved", at: Date.now() } : { state: "error" }); dirty.current = false;
  }, []);
  useEffect(() => {
    if (!attempt || !dirty.current) return;
    if (CAN_STORE || online) setSave(s => ({ ...s, state: "saving" }));
    const id = setTimeout(() => persist(attempt), online ? 1200 : 450);
    return () => clearTimeout(id);
  }, [attempt]);

  const update = (fn) => { dirty.current = true; setAttempt(a => ({ ...fn(a), updated: Date.now() })); };
  const go = (r) => { setRoute(r); window.scrollTo(0, 0); };
  const firstRender = useRef(true);
  useEffect(() => { if (firstRender.current) { firstRender.current = false; return; } const h = document.querySelector("main h1"); if (h) h.focus({ preventScroll: true }); }, [route, practice]);
  const goStep = (s) => { if (attempt) update(a => ({ ...a, step: s })); go(s); };

  const leave = (then) => {
    if (!attempt || !hasContent(attempt)) { setAttempt(null); then(); return; }
    if (CAN_STORE || online) { persist(attempt); setAttempt(null); then(); return; }
    setDialog({ title: "Your work cannot be saved here", body: ["Saving is unavailable in this browser. If you leave this quest, your current work will be lost when the page closes.", "Download it first if you want to keep it."],
      actions: [{ label: "Keep working", kind: "secondary" }, { label: "Download my writing", kind: "secondary", run: () => saveFile("idea2write-draft.txt", exportText(attempt, prof && prof.name)) }, { label: "Leave anyway", kind: "gold", run: () => { persist(attempt); setAttempt(null); then(); } }] });
  };
  const navGo = (r) => { if (attempt && ["explore", "plan", "write", "review"].includes(route)) persist(attempt); if (r === "who" && attempt) { leave(() => go(r)); return; } go(r); };

  const resume = (a) => { const doit = () => { setAttempt(a); setReveal(null); go(a.completed ? "done" : (a.step || "explore")); };
    if (attempt && attempt.id !== a.id && hasContent(attempt)) leave(doit); else doit(); };
  const startAssignment = (asg, cls) => {
    const existing = Object.values(attRef.current).filter(x => x.assignmentId === asg.id).sort((x, y) => y.updated - x.updated)[0];
    if (existing) { resume(existing); return; }
    leave(() => { setPending({ topicId: asg.topic_id, date: null, level: null, assignment: { id: asg.id, className: cls.class_name, teacherName: cls.teacher_name, instructions: asg.instructions || "", due: asg.due_date || null } }); go("support"); });
  };
  const startQuest = (topicId, date) => {
    const open = Object.values(attRef.current).filter(a => a.topicId === topicId && !a.assignmentId && !a.completed && hasContent(a) && (date ? a.scheduledDate === date : true)).sort((x, y) => y.updated - x.updated)[0];
    const begin = () => leave(() => { setPending({ topicId, date: date || null, level: null }); go("support"); });
    if (open) setDialog({ title: "You have unfinished writing", body: [`You started “${TOPIC[topicId].title}” before (last saved ${fmtTime(open.updated)}). Continue it, or start a separate new attempt?`],
      actions: [{ label: "Start a new attempt", kind: "secondary", run: begin }, { label: "Continue my writing", kind: "gold", run: () => resume(open) }] });
    else begin();
  };
  const changeQuest = () => leave(() => go("quests"));
  const finishOnline = async () => {
    const a = { ...attempt, completed: true, step: "done", updated: Date.now() };
    setAttempt(a); attRef.current = { ...attRef.current, [a.id]: a }; setAttempts(attRef.current); setSave({ state: "saving" });
    const s = await cloud.flush(a); handleSaveResult(a, s);
    if (!s || s.state !== "online") { setDialog({ title: "Not completed yet", body: ["Your writing could not be saved online, so the quest is not completed yet. Your work is still here.", "Check your connection and choose Complete the quest again."], actions: [{ label: "OK", kind: "gold" }] }); setAttempt({ ...a, completed: false, step: "review" }); return; }
    let r;
    try { r = await cloud.completeQuest(a.id); } catch (e) { setDialog({ title: "Not completed yet", body: ["The academy server could not complete this quest: " + friendlyAuthError(e), "Your writing is saved online. Please try again."], actions: [{ label: "OK", kind: "gold" }] }); return; }
    if (r.kind === "ineligible") { setDialog({ title: "A step is missing", body: ["The server checked your quest and a required step is not finished yet: 2 planned cards, 20 words, one checklist tick and one improvement."], actions: [{ label: "OK", kind: "gold" }] }); setAttempt({ ...a, completed: false, step: "review" }); go("review"); return; }
    let result = { kind: r.kind, date: r.date };
    if (r.kind === "new") result = { kind: "new", before: { ...r.before, level: levelInfo(r.before.xp).level }, after: { ...r.after, level: levelInfo(r.after.xp).level }, items: COLLECTIBLES.filter(c => (r.items || []).includes(c.id)), ach: ACHIEVEMENTS.filter(x => (r.ach || []).includes(x.id)) };
    await refreshProgress();
    if (result.kind === "new") { Sfx.play("success"); if (result.items.length) setTimeout(() => Sfx.play("unlock"), 700); }
    setReveal({ attemptId: a.id, result }); go("done");
  };
  const submitToTeacher = async (a) => {
    const s = await cloud.flush(a); handleSaveResult(a, s);
    if (!s || s.state !== "online") return { ok: false, msg: "Your latest changes could not be saved online, so nothing was sent." };
    try {
      const r = await cloud.submit(a.id);
      if (r.error) return { ok: false, msg: { ineligible: "A required step is not finished yet.", awaiting_review: "Your teacher has not reviewed your last submission yet.", already_reviewed: "Your teacher has already reviewed this work.", not_in_class: "You are no longer in this class.", assignment_closed: "This quest is closed.", draft_not_saved: "Your writing is not saved online yet." }[r.error] || r.error };
      Sfx.play("success"); await refreshClasses(); return { ok: true, ...r };
    } catch (e) { return { ok: false, msg: friendlyAuthError(e) }; }
  };
  const finish = () => {
    if (!eligibility(attempt).ok) return;
    if (online) { finishOnline(); return; }
    const a = { ...attempt, completed: true, step: "done", updated: Date.now() };
    setAttempt(a); persist(a);
    const { p, result } = applyCompletion(progress, a, klDate());
    if (result.kind !== "duplicate") setProgress(p);
    if (result.kind === "new") { Sfx.play("success"); if (result.items.length) setTimeout(() => Sfx.play("unlock"), 700); }
    setReveal({ attemptId: a.id, result }); go("done");
  };
  const del = (id) => { const next = { ...attRef.current }; delete next[id]; if (online) cloud.deleteDraft(id).catch(() => setDialog({ title: "Not deleted", body: ["The writing could not be deleted online. Please try again."], actions: [{ label: "OK", kind: "gold" }] })); else saveJSON(K.attempts(prof.id), next); attRef.current = next; setAttempts(next); if (attempt && attempt.id === id) setAttempt(null); };

  const saveCharacter = async (f) => {
    if (online) {
      try { await cloud.saveWizard(f, prefs); } catch (e) { setDialog({ title: "Your wizard was not saved", body: [friendlyAuthError(e), "Please try again."], actions: [{ label: "OK", kind: "gold" }] }); return; }
      const first = !wiz; setWiz({ id: account.id, ...f });
      if (first) { go("home"); setEntering({ house: f.house, name: f.name }); Sfx.play("success"); } else go("profile");
      return;
    }
    if (route === "edit" && prof) { setIndex({ ...index, profiles: index.profiles.map(p => p.id === prof.id ? { ...p, ...f } : p) }); go("profile"); return; }
    const id = uid("pupil"), p = { id, ...f, created: Date.now() };
    if (CAN_STORE && !loadJSON(K.migrated, false)) {
      const old = loadJSON(K.v1, {}); const keys = Object.keys(old);
      if (keys.length) { const conv = {}; keys.forEach(k => { const o = old[k]; if (TOPIC[o.topicId]) conv[k] = { answers: {}, scheduledDate: null, ...o, imported: true }; }); saveJSON(K.attempts(id), conv); }
      saveJSON(K.migrated, true);
    }
    setIndex({ profiles: [...index.profiles, p], active: id }); profRef.current = p; loadProfile(id); go("home");
    setEntering({ house: p.house, name: p.name }); Sfx.play("success");
  };
  const choose = (pid) => { setIndex({ ...index, active: pid }); profRef.current = index.profiles.find(p => p.id === pid); loadProfile(pid); go("home"); };
  const removeProfile = (pid) => {
    [K.attempts(pid), K.progress(pid), K.prefs(pid)].forEach(k => { try { localStorage.removeItem(k); } catch (e) { } });
    setIndex({ profiles: index.profiles.filter(p => p.id !== pid), active: index.active === pid ? null : index.active });
    if (index.active === pid) { profRef.current = null; loadProfile(null); }
  };
  const toggleSound = () => { if (sound) { Ambient.stop(); Sfx.on = false; setSound(false); } else if (Ambient.start()) { Sfx.on = true; setSound(true); } };

  const inAct = attempt && ["explore", "plan", "write", "review"].includes(route);
  const needProf = !["who", "create", "guide", "teacher", "credits", "feedback", ...(online ? ["classes"] : [])].includes(route);
  let screen = null;
  if (needProf && !prof) screen = html`<${Who} index=${index} choose=${choose} create=${() => go("create")} />`;
  else switch (route) {
    case "who": screen = html`<${Who} index=${index} choose=${choose} create=${() => go("create")} />`; break;
    case "create": screen = html`<${Create} save=${saveCharacter} cancel=${index.profiles.length ? () => go("who") : null} />`; break;
    case "edit": screen = html`<${Create} editing=${true} initial=${{ portrait: prof.portrait, name: prof.name, house: prof.house, year: prof.year }} save=${saveCharacter} cancel=${() => go("profile")} />`; break;
    case "home": screen = html`<${CommonRoom} prof=${prof} progress=${progress} attempts=${attempts} sched=${sched} go=${navGo} startQuest=${startQuest} resume=${resume} today=${today}
        classQuests=${online ? html`<${ClassQuests} data=${classData} attempts=${attempts} startAssignment=${startAssignment} resume=${resume} go=${navGo} />` : null} />`; break;
    case "classes": screen = online ? html`<${MyClasses} data=${classData} cloud=${cloud} attempts=${attempts} startAssignment=${startAssignment} resume=${resume} refresh=${async () => { const d = await cloud.loadAll(); setClassData({ classes: d.classes || [], submissions: d.submissions || [], wizard: d.wizard }); attRef.current = { ...d.attempts, ...attRef.current }; setAttempts(attRef.current); }} go=${navGo} setDialog=${setDialog} />` : null; break;
    case "quests": screen = html`<${Quests} prof=${prof} attempts=${attempts} progress=${progress} pick=${id => startQuest(id, null)} />`; break;
    case "support": {
      const changing = !!attempt;
      const topicId = changing ? attempt.topicId : pending && pending.topicId;
      const lvl = changing ? attempt.level : pending && pending.level;
      screen = topicId ? html`<${Support} topicId=${topicId} prof=${prof} level=${lvl} changing=${changing}
        setLevel=${l => changing ? update(a => ({ ...a, level: l })) : setPending({ ...pending, level: l })}
        back=${() => changing ? go(attempt.step || "explore") : go(pending && pending.assignment ? "classes" : "quests")}
        start=${() => { if (changing) { go(attempt.step || "explore"); return; } const base = newAttempt(pending.assignment ? TOPIC[pending.topicId].year : prof.year, pending.topicId, pending.level, pending.date); const a = pending.assignment ? { ...base, assignmentId: pending.assignment.id, assignment: pending.assignment } : base; dirty.current = true; setAttempt(a); setPending(null); go("explore"); }} />` : null; break; }
    case "explore": screen = attempt && html`<${Explore} a=${attempt} update=${update} back=${() => go("support")} next=${() => goStep("plan")} />`; break;
    case "plan": screen = attempt && html`<${Plan} a=${attempt} update=${update} back=${() => goStep("explore")} next=${() => goStep("write")} />`; break;
    case "write": screen = attempt && html`<${Write} a=${attempt} update=${update} save=${save} saveNow=${() => persist(attempt)} prefs=${prefs} setPrefs=${setPrefs} setLevel=${l => update(a => ({ ...a, level: l }))} toPlan=${() => goStep("plan")} toReview=${() => goStep("review")} />`; break;
    case "review": screen = attempt && html`<${Review} a=${attempt} update=${update} who=${prof.name} rewarded=${progress.ledger[attempt.id]} toWrite=${() => goStep("write")} finish=${finish} />`; break;
    case "done": screen = attempt && html`<${Done} a=${attempt} who=${prof.name} reveal=${reveal} rewardRec=${progress.ledger[attempt.id]} progress=${progress} go=${navGo}
        editAgain=${() => { update(a => ({ ...a, completed: false, step: "write" })); go("write"); }} another=${() => { persist(attempt); setAttempt(null); go("quests"); }}
        submitPanel=${online && attempt.assignmentId ? html`<${SubmitPanel} a=${attempt} data=${classData} onSubmit=${submitToTeacher} />` : null} />`; break;
    case "calendar": screen = html`<${Calendar} prof=${prof} attempts=${attempts} sched=${sched} today=${today} startQuest=${startQuest} resume=${resume}
        classDue=${online ? classData.classes.filter(c => c.membership_status === "active").flatMap(c => c.assignments.filter(x => x.due_date && x.status === "published").map(x => ({ ...x, cls: c }))) : []} startAssignment=${startAssignment} />`; break;
    case "collection": screen = html`<${CollectionPage} progress=${progress} setDialog=${setDialog} />`; break;
    case "profile": screen = html`<${Profile} prof=${prof} progress=${progress} today=${today} go=${navGo} setDialog=${setDialog} editChar=${() => go("edit")} />`; break;
    case "practice": screen = practice ? html`<${PracticeRun} key=${practice.topicId + practice.cat} topicId=${practice.topicId} cat=${practice.cat} progress=${progress} setProgress=${setProgress} back=${() => setPractice(null)} />`
      : html`<${PracticeHall} prof=${prof} progress=${progress} run=${(topicId, cat) => setPractice({ topicId, cat })} />`; break;
    case "journal": screen = html`<${Journal} attempts=${attempts} progress=${progress} resume=${resume} del=${del} go=${navGo} />`; break;
    case "guide": screen = html`<${Guide} />`; break;
    case "teacher": screen = html`<${Teacher} sched=${sched} setSched=${setSched} art=${art} setArt=${setArt} index=${index} removeProfile=${removeProfile} />`; break;
    case "credits": screen = html`<${Credits} />`; break;
    case "feedback": screen = html`<${Feedback} />`; break;
  }
  if (!screen) screen = html`<div className="frame panel stack-s"><h1 tabIndex="-1">Nothing to show here yet</h1><p>Choose a quest or open your quest journal.</p><div className="row gap-s"><button className="btn gold" onClick=${() => go("quests")}>Quests</button><button className="btn secondary" onClick=${() => go("journal")}>My quest journal</button></div></div>`;

  const scene = route === "home" ? "room" : ["write", "review", "done", "explore", "plan"].includes(route) ? "library" : "hall";
  const house = prof ? prof.house : "emberhart";
  return html`<div className=${"app house-" + house} style=${{ "--house": HOUSE[house].colour, "--house-deep": HOUSE[house].deep }}>
    <${Backdrop} scene=${scene} house=${house} art=${art} />
    <a className="skip" href="#main">Skip to content</a>
    ${online && accountBar ? React.cloneElement(accountBar, { onClasses: () => navGo("classes") }) : accountBar}
    <${Header} route=${route} go=${navGo} prof=${prof} sound=${sound} toggleSound=${toggleSound} progress=${progress} online=${online} />
    ${online ? null : html`<${StorageBanner} />`}
    <main id="main" key=${route + (practice ? "p" : "")} className="scene-in">
      ${inAct ? html`<${ActivityBar} attempt=${attempt} step=${route} save=${save} goStep=${goStep} changeTopic=${changeQuest} setLevel=${l => update(a => ({ ...a, level: l }))} />` : null}
      ${screen}
    </main>
    <${Footer} go=${navGo} prof=${prof} online=${online} />
    ${dialog ? html`<${Dialog} d=${dialog} close=${() => setDialog(null)} />` : null}
    ${entering ? html`<${DoorTransition} info=${entering} done=${() => setEntering(null)} />` : null}
  </div>`;
}

/* ===== Root: session restore, gate, demo mode, pupil and teacher accounts ===== */
const MODE_KEY = "i2w.mode";
function Root() {
  const demoChosen = () => loadJSON(MODE_KEY, null) === "demo";
  const [st, setSt] = useState(() => BACKEND ? { phase: "loading" } : { phase: demoChosen() ? "demo" : "gate" });
  const [authUi, setAuthUi] = useState(null); /* {role, mode} */
  const statusRef = useRef(() => { });
  const loadAccount = useCallback(async (session) => {
    setSt({ phase: "loading", label: "Opening your account…" });
    try {
      const account = await BACKEND.db.select("account_profiles", { eq: { id: session.user.id }, single: true });
      if (!account) throw new Error("Your account profile was not found. Please contact your teacher or site owner.");
      if (account.role === "teacher") { setSt({ phase: "teacher", account, api: makeTeacherApi(account.id) }); return; }
      const cloud = makeStudentCloud(account.id, (r) => statusRef.current(r));
      const boot = await cloud.loadAll();
      setSt({ phase: "student", account, cloudBox: { cloud, statusRef }, boot });
    } catch (e) { setSt({ phase: "error", error: e, session }); }
  }, []);
  useEffect(() => {
    if (!BACKEND) return;
    let alive = true, sub = null;
    (async () => {
      try {
        const session = await BACKEND.authApi.getSession();
        if (!alive) return;
        if (/type=recovery/.test(location.hash)) { setSt({ phase: "recovery" }); }
        else if (session) loadAccount(session);
        else setSt({ phase: demoChosen() ? "demo" : "gate" });
      } catch (e) { setSt({ phase: "gate", notice: "Could not reach the account server, so only demo mode is available right now. " + friendlyAuthError(e) }); }
      sub = BACKEND.authApi.onChange((event, session) => {
        if (event === "PASSWORD_RECOVERY") setSt({ phase: "recovery" });
        else if (event === "SIGNED_IN" && session) setSt(s => (s.phase === "student" || s.phase === "teacher" || s.phase === "recovery") ? s : (loadAccount(session), s));
        else if (event === "SIGNED_OUT") setSt({ phase: "gate", notice: "You have signed out." });
      });
    })();
    return () => { alive = false; sub && sub.unsubscribe && sub.unsubscribe(); };
  }, []);
  const signOut = async () => {
    try { await BACKEND.authApi.signOut(); } catch (e) { }
    setSt({ phase: "gate", notice: "You have signed out." });
  };
  const bar = (account) => html`<${AccountBar} account=${account} mode="online" onSignOut=${signOut} />`;
  const wrap = (child) => html`<div className="app house-emberhart" style=${{ "--house": HOUSE.emberhart.colour, "--house-deep": HOUSE.emberhart.deep }}>
    <${Backdrop} scene="hall" house="emberhart" art=${loadJSON(K.art, null)} /><main id="main" className="scene-in">${child}</main></div>`;

  switch (st.phase) {
    case "loading": return wrap(html`<${Loading} label=${st.label || "Opening the academy…"} />`);
    case "error": return wrap(html`<div className="frame panel stack-s narrow" role="alert"><h1>Could not open your account</h1><p>${friendlyAuthError(st.error)}</p>
      <div className="row gap-s"><button className="btn gold" onClick=${() => loadAccount(st.session)}>Try again</button><button className="btn secondary" onClick=${signOut}>Sign out</button></div></div>`);
    case "recovery": return wrap(html`<${SetNewPassword} done=${async () => { const s = await BACKEND.authApi.getSession(); history.replaceState(null, "", location.pathname); s ? loadAccount(s) : setSt({ phase: "gate" }); }} />`);
    case "teacher": return html`<${TeacherApp} account=${st.account} api=${st.api} accountBar=${bar(st.account)} />`;
    case "student": return html`<${StudentShell} st=${st} bar=${bar(st.account)} statusRef=${statusRef} />`;
    case "demo": return html`<${App} accountBar=${html`<${AccountBar} mode="demo" onExitDemo=${() => { saveJSON(MODE_KEY, null); setSt({ phase: "gate" }); }} />`} />`;
    default:
      if (authUi) return wrap(html`<${AuthScreen} role=${authUi.role} mode=${authUi.mode} setMode=${m => setAuthUi({ ...authUi, mode: m })} back=${() => setAuthUi(null)} />`);
      return wrap(html`<${Gate} configured=${!!BACKEND} notice=${st.notice} onDemo=${() => { saveJSON(MODE_KEY, "demo"); setSt({ phase: "demo" }); }} onAuth=${(role, mode) => setAuthUi({ role, mode })} />`);
  }
}
/* Keeps the pupil App mounted while the save-status callback is wired to it */
function StudentShell({ st, bar, statusRef }) {
  return html`<${App} cloudBox=${st.cloudBox} boot=${st.boot} account=${st.account} accountBar=${bar} />`;
}

ReactDOM.createRoot(document.getElementById("root")).render(html`<${ErrorBoundary}><${Root} /><//>`);
